static int vol_give_back(void);static void vol_take_again(void);   /* (the volatile block, below) */
static int vol_dropped_now;static void vol_settle_view(void);static volatile int power_request;
static void power_park_point(void) {   /* main, between frames (power_callback) */
    park_busy=1;
    PLOG("park",power_sleeping,vol_held());
    ge_draw_ready();   /* the GE's list done, the flip shown */
    PLOG("park-ge",0,0);
    int held=world_ok_now() && !world_critical_closed() && world_critical_begin(2000);   /* no card read across the sleep */
    PLOG("park-loader",held,0);
    int vr=vol_give_back();(void)vr;   /* then the volatile block, its parts dropped with the loader held: its power lock goes, the sleep may come */
    PLOG("park-vol",vr,vol_held());
    power_parked=1;
    /* a park the resume never ends goes on by itself: 3 s after the switch
     * without the sleep coming (the switch back, the sleep refused), 10 s
     * after a SUSPENDING without the resume */
    uint64_t since=sceKernelGetSystemTimeWide();
    for(;;) {
        uint64_t t=sceKernelGetSystemTimeWide()-since;
        if(!power_park || !running || t>=10000000 || (!power_sleeping && t>=3000000))break;
        sceKernelDelayThread(20000);
    }
    PLOG("unpark",(int)((sceKernelGetSystemTimeWide()-since)/1000),power_park);
    power_park=power_parked=power_sleeping=0;
    power_request=0;   /* the switch's ask answered here: vol_frame giving the block back again after the resume left the city without it 3 s */
    vol_take_again();   /* back: the block first, then the loader */
    PLOG("vol-again",0,vol_held());
    if(held)world_critical_end();
    if(vol_dropped_now){vol_dropped_now=0;vol_settle_view();}   /* the parts the block held (the sleep reserve's: volmem.c) loaded again before the game goes on, as after a save */
#if POWER_LOG
    plog_quiet=0;
#endif
    audio_power(0);   /* the music back (a switch without the sleep sends no RESUME_COMPLETE) */
    movie_suspend=0;park_busy=0;
}
