/* Suspend and resume, one callback: the switch or a suspend asks the main
 * thread to park (power_park_point: the GE's list and the flip done, the
 * loader held, then the volatile block given back, the power lock with it);
 * on SUSPENDING it waits for the park (half a second at most) before the
 * PSP sleeps. A resume (counted once, after a suspend: later notices, the
 * battery's or the AC's, may still carry RESUME_COMPLETE, and each count
 * reopens the long-read files, power.h) ends the park: the block back,
 * then the loader. (A resume with a list in flight crashed the flip thread
 * on the PSP-3000: reports/psp-suspend-crash.) */
#if POWER_LOG
/* The DDR's protection words (0xBC000040-7C: ARK's SystemControl opens the
 * extra 32 MB to user code once, at its boot): read through ARK's KUBridge
 * at the boot and at each resume, logged where they differ and written back
 * as they were (the threads' stacks are in the extra memory). */
#include <kubridge.h>
static unsigned prot_boot[16];static int prot_have;
static void prot_check(int resume) {
    unsigned v[16];int diff=0;
    for(int i=0;i<16;i++)v[i]=kuKernelPeekw((void *)(0xBC000040u+4u*(unsigned)i));
    if(!resume){memcpy(prot_boot,v,sizeof v);prot_have=1;for(int i=0;i<16;i++)PLOG("prot-boot",i,v[i]);return;}
    if(!prot_have)return;
    for(int i=0;i<16;i++)if(v[i]!=prot_boot[i]){diff++;PLOG("prot-resume",i,v[i]);}
    PLOG("prot-diff",diff,0);
    if(diff)for(int i=0;i<16;i++)kuKernelPokew((void *)(0xBC000040u+4u*(unsigned)i),prot_boot[i]);
}
#endif
static int power_callback(int a,int info,void *c) {
    (void)a;(void)c;
    static int asleep;
#if POWER_LOG
    if(info&PSP_POWER_CB_RESUMING)prot_check(1);
#endif
    PLOG("pcb",info,asleep);
    if(power_locked && (info&PSP_POWER_CB_POWER_SWITCH) && !(info&(PSP_POWER_CB_SUSPENDING|PSP_POWER_CB_RESUMING|PSP_POWER_CB_RESUME_COMPLETE))) {
        power_notice_until=sceKernelGetSystemTimeWide()+4000000;   /* the lock holds the sleep off: only the notice */
        return 0;
    }
#if POWER_LOG
    if(info&(PSP_POWER_CB_RESUMING|PSP_POWER_CB_RESUME_COMPLETE))plog_quiet=0;
    else if(info&(PSP_POWER_CB_POWER_SWITCH|PSP_POWER_CB_SUSPENDING))plog_quiet=1;
#endif
    if(info&(PSP_POWER_CB_RESUMING|PSP_POWER_CB_RESUME_COMPLETE)) {
        if(asleep){asleep=0;power_resumes++;}power_resume_at=sceKernelGetSystemTimeWide();movie_suspend=0;power_park=0;
        if(info&PSP_POWER_CB_RESUME_COMPLETE)audio_power(0);
#if POWER_LOG
        if(info&PSP_POWER_CB_RESUME_COMPLETE)plog_flush_now("resume");   /* at once: the card is back */
#endif
        return 0;
    }
    if(info&(PSP_POWER_CB_POWER_SWITCH|PSP_POWER_CB_SUSPENDING)){power_request=1;power_park=1;movie_suspend=1;audio_power(1);}
    if(info&PSP_POWER_CB_SUSPENDING) {
        asleep=1;power_sleeping=1;
        int k=0;for(;k<50 && !power_parked && running;k++)sceKernelDelayThread(10000);
        PLOG("pcb-wait",k,power_parked);
#if POWER_LOG
        plog_flush_now("before");   /* at once, before the sleep: the threads as they go to it */
#endif
    }
    return 0;
}
/* A test's suspend (suspend-test.txt beside the game: "seconds ms", one
 * line or more): at each time from the boot the power callback is called
 * as the switch does it (POWER_SWITCH and SUSPENDING, which waits for the
 * park), the files' handles go stale and the opens fail for ms (io-fail's,
 * the card away), then RESUMING and RESUME_COMPLETE. The emulator has no
 * sleep: the threads keep running, the main one parked. */
#ifndef HOST_SIM
static int suspend_sim_thread(SceSize n,void *arg) {
    (void)n;(void)arg;
    char whole[224];FILE *x=fopen(io_abs("suspend-test.txt",whole,(int)sizeof whole),"r");if(!x)return 0;   /* (a thread without the folder: power.h io_abs) */
    int at[16],ms[16],k=0;while(k<16 && fscanf(x,"%d %d",&at[k],&ms[k])==2)k++;
    fclose(x);
    uint64_t t0=sceKernelGetSystemTimeWide();
    for(int i=0;i<k;i++) {
        uint64_t when=t0+(uint64_t)at[i]*1000000u,now=sceKernelGetSystemTimeWide();
        if(when>now)sceKernelDelayThread((SceUInt)(when-now));
        PLOG("sim-suspend",at[i],ms[i]);
        if(!ms[i]){power_callback(0,PSP_POWER_CB_POWER_SWITCH,NULL);continue;}   /* 0 ms: the switch alone, as with suspend off (power_locked) */
        power_callback(0,PSP_POWER_CB_POWER_SWITCH|PSP_POWER_CB_SUSPENDING,NULL);
        {extern void io_fail_start(unsigned ms);io_fail_start((unsigned)ms[i]);}
        sceKernelDelayThread((SceUInt)ms[i]*1000u);
        power_callback(0,PSP_POWER_CB_RESUMING,NULL);
        power_callback(0,PSP_POWER_CB_RESUME_COMPLETE,NULL);
        PLOG("sim-resume",at[i],0);
    }
    return 0;
}
#endif
static int callback_thread(SceSize n,void *arg) {
    (void)n;(void)arg;
#ifndef HOST_SIM
    {SceUID t=sceKernelCreateThread("SuspendSim",suspend_sim_thread,0x12,0x4000,PSP_THREAD_ATTR_USER,NULL);if(t>=0)sceKernelStartThread(t,0,NULL);}
#endif
    int cb=sceKernelCreateCallback("Exit",exit_callback,NULL);
    sceKernelRegisterExitCallback(cb);
#ifndef HOST_SIM
    if(!vol_is_reserve()){int r=sceKernelPowerLock(0);power_locked=r>=0;PLOG("power-lock",power_locked,r);}   /* with the sleep reserve (volmem.c) the extended memory sleeps: no lock */
#endif
    int pcb=sceKernelCreateCallback("Power",power_callback,NULL);
    if(pcb>=0)scePowerRegisterCallback(-1,pcb);
    sceKernelSleepThreadCB();return 0;
}
/* The CPU's real clock. With an ARK clock plugin on, scePowerSetClockFrequency
 * may not take and the getters then report what was asked: two chains of
 * dependent adds (32 and 64 a pass, the same loop around them) timed by the
 * system clock; their difference is 32 cycles a pass, whatever the loop's
 * branch costs. The least time of five each (a thread switch in one only
 * makes it slower). */
static float cpu_mhz_timed;
#define CLK_ADDS8 "addu $t1,$t1,$t1\n addu $t1,$t1,$t1\n addu $t1,$t1,$t1\n addu $t1,$t1,$t1\n addu $t1,$t1,$t1\n addu $t1,$t1,$t1\n addu $t1,$t1,$t1\n addu $t1,$t1,$t1\n"
static void clock_measure(void) {
#ifndef HOST_SIM
    enum { PASSES=20000 };
    uint64_t best[2]={~0ull,~0ull};
    for(int r=0;r<5;r++) {
        uint64_t t0=sceKernelGetSystemTimeWide();
        __asm__ volatile(".set push\n.set noreorder\n li $t0,%0\n li $t1,1\n1:\n" CLK_ADDS8 CLK_ADDS8 CLK_ADDS8 CLK_ADDS8
                         " addiu $t0,$t0,-1\n bnez $t0,1b\n nop\n.set pop" :: "i"(PASSES) : "t0","t1");
        uint64_t t1=sceKernelGetSystemTimeWide();
        __asm__ volatile(".set push\n.set noreorder\n li $t0,%0\n li $t1,1\n1:\n" CLK_ADDS8 CLK_ADDS8 CLK_ADDS8 CLK_ADDS8 CLK_ADDS8 CLK_ADDS8 CLK_ADDS8 CLK_ADDS8
                         " addiu $t0,$t0,-1\n bnez $t0,1b\n nop\n.set pop" :: "i"(PASSES) : "t0","t1");
        uint64_t t2=sceKernelGetSystemTimeWide();
        if(t1-t0<best[0])best[0]=t1-t0;
        if(t2-t1<best[1])best[1]=t2-t1;
    }
    cpu_mhz_timed=best[1]>best[0]?32.f*PASSES/(float)(best[1]-best[0]):0;   /* cycles a microsecond */
#endif
}
