/* A look's colours on a car's meshes, its far levels' too: the player's
 * (apply_look), a dressed rival's (opp_dress_load). */
static void look_colours(Model *mm,const CarLook *l,int front_brakes) {
    uint32_t paint=0xff000000u|garage_paint(l->paint);
    /* the parts' own paint (0: stock): the spoiler and the roof scoop over the body's, the rims (their
     * metal, not the tyre; a spinner's turning part its own) and the calipers: the performance shop's front brakes'
     * alone, as the original's (CarRenderInfo: PAINT_BRAKE with a FRONT_BRAKE of level 1 or more;
     * CarCustomizeManager::AreBrakesPaintable); the muffler tips' over the shop's tips' chrome (its EXHAUST_TIP
     * material replaced), the mirrors' over the shop's mirrors' (chrome and their glass, no body skin). The engine accents' on the HOSES material of the upgraded
     * engines (garage_set_engine: STYLE01/02 in the garage's pack, F_HOSES). */
    uint32_t pc[PAINT_PARTS];
    for(int k=0;k<PAINT_PARTS;k++){int v=k<4?l->part[k]:l->part_hi[k-4];pc[k]=v?0xff000000u|garage_part_colour(k,v-1):garage_part_body(k)?paint:0;}
    const uint8_t *pt=l->part;
    uint32_t spoiler=pc[PART_SPOILER],rims=pc[PART_RIMS],brakes=pc[PART_BRAKES];
    int spin_paint=l->part_hi[PART_SPINNER-4]!=0,tips_paint=l->exhaust && l->part_hi[PART_MUFFLER-4];
    int mirror_paint=l->mirror && l->part_hi[PART_MIRROR-4];
    /* window tint: the windows' glass (convert_car GLASS 28,40,50,165) darker and denser */
    static const uint32_t tint[GARAGE_TINTS]={0xa532281c,0xc8281e14,0xe61a140e,0xf80c0a08};
    for(uint32_t k=0;k<mm->nm+mm->nlod;k++) {
        Mesh *m=&mm->mesh[k];
        unsigned slot=(m->flags&SLOT_MASK)>>SLOT_SHIFT;
        if((m->flags&F_PAINT) && m->texture==UINT32_MAX)   /* painted library parts (spoilers: slot 4; roof scoops 8, mirrors 11) */
            m->color=slot==4?spoiler:slot==8 && !(m->flags&F_DECAL)?pc[PART_ROOF]:slot==11 && l->mirror?pc[PART_MIRROR]:paint;
        if((m->flags&F_WHEEL) && !(m->flags&F_WHEEL_FIXED) && (m->flags&(F_CHROME|F_METAL))) {
            if(m->flags&F_SPINNER){if(spin_paint)m->color=pc[PART_SPINNER];}
            else if(pt[PART_RIMS])m->color=rims;
        }
        if(tips_paint && slot==9 && (m->flags&F_CHROME) && !(m->flags&F_DECAL))m->color=pc[PART_MUFFLER];
        if(mirror_paint && slot==11 && (m->flags&F_CHROME) && !(m->flags&F_DECAL))m->color=pc[PART_MIRROR];
        if(pt[PART_BRAKES] && front_brakes && (m->flags&F_WHEEL_FIXED) && ((m->flags>>8)&3)<2)m->color=brakes;
        if(pc[PART_ENGINE] && (m->flags&(F_HOSES|F_DECAL))==F_HOSES)m->color=pc[PART_ENGINE];   /* the upgraded engine's hoses (beta issue 66) */
        if((m->flags&F_GLASS) && (m->color==tint[0] || m->color==tint[1] || m->color==tint[2] || m->color==tint[3]))m->color=tint[l->tint<GARAGE_TINTS?l->tint:0];
    }
}
