        memcpy(&q->tex,bh,2);memcpy(&q->flags,bh+2,2);memcpy(&q->n,bh+4,4);
        if(q->tex>=h[1] || q->n>(1u<<20) || ((q->flags&SCENE_ANIM) && q->tex+((q->flags>>8)&15u)>h[1])){ok=0;break;}
        size_t sz=(size_t)q->n*sizeof(SceneVert);SceneVert *v=memalign(16,sz?sz:16);
        if(!v){ok=0;break;}
