        for(int j=0;j<SH_V;j++)for(int i=0;i<SH_U;i++) {
            float a=(i/(float)(SH_U-1))*2-1,b=(j/(float)(SH_V-1))*2-1;
            float x=ox+lx*a*hx+fx*b*hz,z=oz+lz*a*hx+fz*b*hz,y;
            if(!world_ground(x,z,c->ground,1.f,.6f,&y))y=c->ground;
            v[j*SH_U+i]=(P){i/(float)(SH_U-1),j/(float)(SH_V-1),x-ro.x,y+.03f-ro.y,z-ro.z};
            car_ground.h[j][i]=y;
        }
