        car_ground.x0=cx-hx;car_ground.z0=cz-hz;car_ground.sx=2*hx/(SH_U-1);car_ground.sz=2*hz/(SH_V-1);
        car_ground.isx=1/car_ground.sx;car_ground.isz=1/car_ground.sz;car_ground.sy=fx;car_ground.cy=fz;
        static uint16_t idx[(SH_U-1)*(SH_V-1)*6];static int built;
        if(!built){int n=0;for(int j=0;j<SH_V-1;j++)for(int i=0;i<SH_U-1;i++){int k=j*SH_U+i;
            idx[n++]=k;idx[n++]=k+1;idx[n++]=k+SH_U;idx[n++]=k+1;idx[n++]=k+SH_U+1;idx[n++]=k+SH_U;}built=1;}
        sceGumMatrixMode(GU_MODEL);sceGumPushMatrix();sceGumLoadIdentity();
        sceGumDrawArray(GU_TRIANGLES,GU_TEXTURE_32BITF|GU_VERTEX_32BITF|GU_INDEX_16BIT|GU_TRANSFORM_3D,(SH_U-1)*(SH_V-1)*6,idx,v);
        sceGumPopMatrix();
