            float nd=c->nx*dx+c->ny*dy+c->nz*dz;m->eye_terms[2*j]=inv;m->eye_terms[2*j+1]=nd;   /* 1/distance: the coat multiplies */
            float ndv=fmaxf(0,nd*inv);
