/* shade_paint's colours into what the GE reads (in strip order, or the
 * vertices): after the GE is done with the last frame (the street computes
 * the paint before its fence, the GE still drawing). */
static void paint_publish(void) {
    /* the views' (debug_view): the paint's key, black, unshaded (the mesh's colour) */
    uint32_t plain=debug_view&524288?0xffff00ff:debug_view&1?0xff000000:0;
    for(uint32_t k=0;k<model.nm;k++) {
        Mesh *m=&model.mesh[k];if(!player_quant[k].qp)continue;
        uint32_t one=plain?plain:!paint_model?m->color:0;
        if(m->seq) {   /* in strip order */
            QPaintVertex *ps=UNCACHED(player_quant[k].qp);
            for(uint32_t j=0;j<player_quant[k].nq;j++)ps[j].color=one?one:m->paint_col[m->seq[j]];
            MEM_SYNC();
        } else {
            for(uint32_t j=0;j<m->nv;j++)player_quant[k].qp[j].color=one?one:m->paint_col[j];
            sceKernelDcacheWritebackRange(player_quant[k].qp,m->nv*sizeof(QPaintVertex));
        }
    }
}
static void lights(int mirror) {
    /* Key light from above, cool fill from the opposite side. The mirrored
     * floor image uses mirrored lights so it stays lit from above. */
    float m=mirror?-1.f:1.f;
    ScePspFVector3 key={-.25f,m,.35f},fill={.6f,.25f*m,-.75f};
    sceGuEnable(GU_LIGHTING);sceGuEnable(GU_LIGHT0);sceGuEnable(GU_LIGHT1);
    sceGuLight(0,GU_DIRECTIONAL,GU_DIFFUSE_AND_SPECULAR,&key);
    int k=(int)((menu_pose?MENU_PARTS_LIGHT:car_light)*100);   /* the menus: rims, lamps and trim brighter than the paint's street light, as the PS2's */
    sceGuLightColor(0,GU_DIFFUSE,scale_rgb(0xffb8b8b8,k));sceGuLightColor(0,GU_SPECULAR,0xffffffff);
    if(menu_pose){fill=menu_side;if(mirror)fill.y=-fill.y;}   /* the menus: the fill is the PS2's lamp at the screen's left (rims, flank) */
    sceGuLight(1,GU_DIRECTIONAL,GU_DIFFUSE,&fill);sceGuLightColor(1,GU_DIFFUSE,scale_rgb(menu_pose?MENU_FILL:0xff584c48,k));
    sceGuAmbient(scale_rgb(0xff4a4a4a,k));sceGuLightMode(GU_SEPARATE_SPECULAR_COLOR);
}
static void draw_mesh_range(int glass,uint32_t k0,uint32_t k1) {
    const Texture *bound=NULL;   /* the meshes share textures (the skin): bound once while they follow each other */
    for(uint32_t k=k0;k<k1;k++) {
        Mesh *m=&model.mesh[k];if(!!(m->flags&(F_GLASS|F_DECAL))!=glass || !car_vis[k])continue;   /* decals with the glass, over the body; outside the view (car_cull_update) */
        uint32_t f=m->flags;
        if(menu_pose && !(f&F_DECAL) && (f&F_DRIVER))continue;   /* the original's front end replaces the driver with DEFAULTALPHA */
        if(f&F_DECAL){sceGuDepthOffset(DECAL_DEPTH_BIAS);sceGuTexWrap(GU_CLAMP,GU_CLAMP);}
        int lamp=menu_pose && flat_headlamp(f,m->texture,m->color);   /* a headlamp's lens in the showroom: lit white, as the PS2's */
        if((f&F_EMISSIVE) || lamp || ((f&F_GLASS) && m->texture!=UINT32_MAX))sceGuDisable(GU_LIGHTING);else sceGuEnable(GU_LIGHTING);   /* tinted glass (the 206's REAR_DEFROSTER) keeps its own dark art */
        sceGuSpecular(f&F_PAINT?14.f:f&(F_CHROME|F_METAL)?60.f:f&F_CARBON?30.f:12.f);
        sceGuMaterial(GU_SPECULAR,f&(F_PAINT|F_CARBON|F_GLASS)?0xffc0c0c0:f&(F_CHROME|F_METAL)?(menu_pose?MENU_CHROME_SPEC:0xffe0e0e0):f&F_MATTE?0xff080808:0xff303030);
        /* Plain chrome reads mostly as reflection: its diffuse base darkened;
         * chrome over a texture (rims: RACINGHART's gold) keeps its colour,
         * and carbon weave shows grey under the original's gloss. */
        uint32_t col=m->color;
        if(street_hot && (f&F_EMISSIVE) && m->texture==UINT32_MAX)col=TAIL_CORE;   /* the tail lamps' lit cores, as the PS2's at dawn */
        if(lamp_colour(m->color,f,F_EMISSIVE)==BRAKE_LIT)col=street_hot?BRAKE_LIT_HOT:BRAKE_LIT;   /* braking: by the lens' own red (TAIL_CORE over it on the street) */
        if(lamp)col=scale_rgb(col,MENU_LAMP_PCT)&0x00ffffff|(uint32_t)MENU_LAMP_ALPHA<<24;   /* a headlamp's lens: lit white, a touch under the PS2's burnt-out highlights */
        else if(menu_pose && (f&F_GLASS) && m->texture==UINT32_MAX && (col>>24)>=0xc8)col=MENU_TINTED_GLASS;   /* tinted: the showroom's dusk mirrored in it */
        else if(menu_pose && (f&F_GLASS) && col==STOCK_GLASS)col=MENU_STOCK_GLASS;   /* stock glass in the showroom: the street's light grey in it */
        else if(!menu_pose && (f&F_GLASS) && !lamp_glass(f) && m->texture!=UINT32_MAX)col=ART_GLASS_COLOR;   /* the defroster's dark brown art: neutral, the cabin showing through, as the PS2's */
        else if((f&F_GLASS) && col==STOCK_GLASS)col=(col&0x00ffffff)|(uint32_t)((col>>24)*WINDOW_ALPHA_PCT/100)<<24;   /* stock windows: the cabin shows through, as the PS2's (tinted ones stay dark) */
        sceGuColor(f&F_CHROME?scale_rgb(col,m->texture!=UINT32_MAX?CHROME_TEX_PCT:street_hot?STREET_CHROME_PCT:30):f&F_METAL?scale_rgb(col,75):
                   f&F_CARBON?scale_rgb(col,CARBON_PCT):col);
        if(f&F_MATTE)sceGuMaterial(GU_SPECULAR,0xff080808);   /* sceGuColor sets the specular too: a matte part on the skin (white) glinted white under the street's light from above (the 206's rear bumper strip) */
        int q=player_quant[k].qv || player_quant[k].qp;   /* the GE's 16-bit copies (model_quantize): their UVs' offset and scale */
        if(car_damaged && damage_glass && (f&F_GLASS) && !lamp_glass(f) && (m->texture!=UINT32_MAX || (m->color>>24)>=0x96)) {   /* windows crack; original lamp glass stays whole */
            sceGuEnable(GU_TEXTURE_2D);sceGuDisable(GU_LIGHTING);sceGuColor(0xffffffff);
            sceGuTexMode(GU_PSM_8888,0,0,0);sceGuTexImage(0,64,64,64,damage_glass);bound=NULL;
            if(q){sceGuTexScale(player_quant[k].us,player_quant[k].vs);sceGuTexOffset(player_quant[k].uo,player_quant[k].vo);}else sceGuTexScale(1,1);
        } else if(m->texture!=UINT32_MAX) {
            Texture *t=&model.tex[m->texture];sceGuEnable(GU_TEXTURE_2D);
            if(t!=bound){bind_car_texture(t);bound=t;}
            float su=m->uvscale,sv=m->uvscale*t->vrepeat;
            if(q){sceGuTexScale(player_quant[k].us*su,player_quant[k].vs*sv);sceGuTexOffset(player_quant[k].uo*su,player_quant[k].vo*sv);}else{sceGuTexScale(su,sv);sceGuTexOffset(0,0);}
        } else sceGuDisable(GU_TEXTURE_2D);
        if(debug_view&1)sceGuColor(0xff000000),sceGuDisable(GU_TEXTURE_2D),sceGuDisable(GU_LIGHTING);
        if(inside_shut(m->flags))continue;
        int key=player_quant[k].qp && (debug_view&524288);
        if(key)sceGuColor(0xffff00ff),sceGuDisable(GU_TEXTURE_2D),sceGuDisable(GU_LIGHTING);
        int wp=wheel_push(m->flags),pp=piece_push(m->flags);
        if(player_quant[k].qp) {   /* its colours shade_paint's, or the views' plain one (paint_publish) */
            int shaded=paint_model && !(debug_view&1) && !key;
            sceGuDisable(GU_LIGHTING);if(shaded)sceGuEnable(GU_FRAGMENT_2X);sceGuTexFunc(GU_TFX_MODULATE,GU_TCC_RGBA);
            enum { QP=GU_TEXTURE_16BIT|GU_COLOR_8888|GU_VERTEX_16BIT|GU_TRANSFORM_3D };
            car_quant_push();
            if(m->seq)sceGumDrawArray(GU_TRIANGLE_STRIP,QP,player_quant[k].nq,NULL,player_quant[k].qp);
            else sceGumDrawArray(GU_TRIANGLES,QP|GU_INDEX_16BIT,m->ni,m->i,player_quant[k].qp);
            car_quant_pop();
            sceGuDisable(GU_FRAGMENT_2X);sceGuTexFunc(GU_TFX_MODULATE,GU_TCC_RGBA);
        } else if(player_quant[k].qv) {
            enum { QT=GU_TEXTURE_16BIT|GU_NORMAL_16BIT|GU_VERTEX_16BIT|GU_TRANSFORM_3D };
            car_quant_push();
            if(m->seq)sceGumDrawArray(GU_TRIANGLE_STRIP,QT,player_quant[k].nq,NULL,player_quant[k].qv);
            else sceGumDrawArray(GU_TRIANGLES,QT|GU_INDEX_16BIT,m->ni,m->i,player_quant[k].qv);
            car_quant_pop();
        } else mesh_draw(m);
        wheel_pop(wp);wheel_pop(pp);
        if(f&F_DECAL){sceGuDepthOffset(0);sceGuTexWrap(GU_REPEAT,GU_REPEAT);}
    }
    sceGuTexScale(1,1);sceGuTexOffset(0,0);
}
static void draw_meshes(int glass) { draw_mesh_range(glass,0,model.nm); }
/* Opaque car mirrored about the floor plane, later covered by the
 * translucent turntable. No reflection passes: it is seen dimmed. */
static void draw_floor_mirror(void) {
    if(!floor_mirror)return;
    if(texture_flush_pending) {sceGuTexFlush();texture_flush_pending=0;}
    ScePspFVector3 shift={0,2*model.floor_y,0},flip={1,-1,1};
    sceGumMatrixMode(GU_MODEL);sceGumLoadIdentity();sceGumTranslate(&shift);sceGumScale(&flip);
    lights(1);sceGuTexMapMode(GU_TEXTURE_COORDS,0,0);sceGuDisable(GU_BLEND);sceGuDepthMask(GU_FALSE);
    draw_meshes(0);
    sceGumLoadIdentity();sceGuDisable(GU_LIGHT1);
}
/* The dawn street's sheen on the paint, added over it (the paint's own
 * colour multiplies the skin, which caps it at the skin's green): the
 * PS2's 350Z from behind has its trunk lid and bumper top glowing pale
 * yellow-green under the sky. A wide lobe of a light above the camera,
 * the panels facing up toward the eye lit most. */
static const float SHEEN_GAIN=1.4f,SHEEN_RISE=2.f;   /* the lobe: N.H^40 */
static PaintTransfer sheen_transfer;
static const uint32_t SHEEN_RGB=0x68c098;   /* BGR */
static void paint_sheen_warm(void) {
    paint_transfer_prepare(&sheen_transfer,paint_material,garage_paint_material(GARAGE_PAINT_RACHEL),SHEEN_RGB);
}
static void draw_street_sheen(void) {
    /* the paint's own highlight (paint_tune: at dawn the sheen above stands
     * for it; with both, the PS2's 350Z from behind went yellow) */
    int hl=pl.m && pl.hl;   /* shade_paint's, per vertex */
    if((!street_hot || SHEEN_GAIN<=0) && !hl)return;
    if(street_hot)paint_transfer_prepare(&sheen_transfer,pl.m,garage_paint_material(GARAGE_PAINT_RACHEL),SHEEN_RGB);
    static unsigned kept_transfer;int transfer_changed=kept_transfer!=sheen_transfer.generation;kept_transfer=sheen_transfer.generation;
    typedef struct { uint32_t c;int16_t x,y,z,pad; } P;   /* the coat's 16-bit positions (car_quant's matrix) */
    sceGuDisable(GU_LIGHTING);sceGuDisable(GU_TEXTURE_2D);sceGuDisable(GU_ALPHA_TEST);sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD,GU_FIX,GU_FIX,0xffffff,0xffffff);sceGuDepthMask(GU_TRUE);sceGuDepthFunc(GU_EQUAL);
    static uint32_t *per;static uint32_t per_n;   /* a strip's mesh: the colours per vertex here, then in strip order */
    /* The sheen alone (no highlight): half the vertices worked out a frame,
     * alternating, the other half's from the last (kept in hl_col, unused
     * without the highlight); all of them when the car or the light changed. */
    static const void *kept;static unsigned parity;
    int cache=street_hot && !hl,all_meshes=!cache || kept!=(const void *)model.data || transfer_changed;
    kept=cache?(const void *)model.data:NULL;parity^=1;
    for(uint32_t k=0;k<model.nm;k++) {
        const Mesh *m=&model.mesh[k];if(!player_quant[k].qp || !player_quant[k].qc || (m->flags&F_WHEEL) || !car_vis[k])continue;
        int all=all_meshes || car_fresh[k];   /* (a mesh back in view: all its sheen, not half) */
        if(m->seq && m->nv>per_n){uint32_t *n=realloc(per,m->nv*sizeof(uint32_t));if(n){per=n;per_n=m->nv;}}
        if(m->seq && m->nv>per_n)continue;
        uint32_t *v=m->seq?per:NULL;P *out=m->seq?NULL:sceGuGetMemory(m->nv*sizeof(P));
        const float *et=m->eye_terms && !memcmp(&eye_terms_at,&eye_obj,sizeof eye_obj)?m->eye_terms:NULL;   /* shade_paint's 1/distance, for this eye */
        for(uint32_t j=0;j<m->nv;j++) {
            const Vertex *c=&m->v[j];uint32_t col;
            if(!street_hot || (!all && (j&1)!=parity)){col=m->hl_col[j];goto put;}   /* the highlight alone, or the sheen kept */
            /* v the unit view vector, l = (v + R up) / |v + R up| the light,
             * q = l + v the half vector unnormalised: N.q = (N.v + R ny) / |l|
             * + N.v and |q|^2 = 2 + 2 (1 + R vy) / |l|, so N.H^2 = (N.q)^2 / |q|^2
             * with one square root (shade_paint's 1/distance and N.(eye - v)) */
            float dy=eye_obj.y-c->y,inv,nd;
            if(et){inv=et[2*j];nd=et[2*j+1];}
            else{float dx=eye_obj.x-c->x,dz=eye_obj.z-c->z;inv=1/sqrtf(dx*dx+dy*dy+dz*dz);nd=c->nx*dx+c->ny*dy+c->nz*dz;}
            float vy=dy*inv,ndv=nd*inv,il=1/sqrtf(1+2*SHEEN_RISE*vy+SHEEN_RISE*SHEEN_RISE);
            float nq=ndv*(1+il)+SHEEN_RISE*c->ny*il,g=0;
            if(nq>0) {   /* N.H^40 = (N.H^2)^20: 5 products */
                float a=nq*nq/(2+2*il*(1+SHEEN_RISE*vy)),a2=a*a,a4=a2*a2,a16=a4*a4;a16*=a16;
                g=fminf(1.f,SHEEN_GAIN*a16*a4);
            }
            int q=0;float f=0;
            if(street_hot && sheen_transfer.relative)paint_transfer_view(ndv,&q,&f);
            col=0xff000000;
            for(int ch=0;ch<3;ch++) {   /* original material response, with the calibrated reference retained exactly */
                float response=street_hot && sheen_transfer.relative?paint_transfer_value(&sheen_transfer,q,f,ch):(float)((SHEEN_RGB>>(8*ch))&255);
                float value=response*g;
                int x=(value>=255.f?255:(int)value)+(hl?(int)((m->hl_col[j]>>(8*ch))&255):0);
                col|=(uint32_t)(x>255?255:x<0?0:x)<<(8*ch);
            }
            if(cache)m->hl_col[j]=col;
            put:
            if(v)v[j]=col;else{const QCoatVertex *q=&player_quant[k].qc[j];out[j]=(P){col,q->x,q->y,q->z,0};}
        }
        car_quant_push();
        if(v) {   /* in strip order */
            P *sv=sceGuGetMemory(player_quant[k].nq*sizeof(P));
            for(uint32_t j=0;j<player_quant[k].nq;j++){const QCoatVertex *q=&player_quant[k].qc[j];sv[j]=(P){per[m->seq[j]],q->x,q->y,q->z,0};}
            sceGumDrawArray(GU_TRIANGLE_STRIP,GU_COLOR_8888|GU_VERTEX_16BIT|GU_TRANSFORM_3D,player_quant[k].nq,NULL,sv);
        } else sceGumDrawArray(GU_TRIANGLES,GU_COLOR_8888|GU_VERTEX_16BIT|GU_INDEX_16BIT|GU_TRANSFORM_3D,m->ni,m->i,out);
        car_quant_pop();
    }
    sceGuDepthFunc(GU_GEQUAL);sceGuDepthMask(GU_FALSE);sceGuEnable(GU_ALPHA_TEST);
    sceGuBlendFunc(GU_ADD,GU_SRC_ALPHA,GU_ONE_MINUS_SRC_ALPHA,0,0);
}
static void draw_neon(int k,const Car *c);
extern int neon_force;   /* (below: the rivals' neon) */
static void draw_tubes(const float (*t)[6],int n,uint32_t rgb);
static void draw_shine(const Model *mm,int glass,uint32_t k0,uint32_t k1);
/* A car's body at the level of detail the original draws for its size on
 * screen (CarRenderInfo::Render, RenderFast for the traffic): eView::
 * GetPixelSize, a 3 m radius over the distance times the projection's 356
 * (the same at our 71.5 deg), against CarBodyLodSwapSize (120, 45, 20
 * pixels: level B from ~9 m, C from ~24 m, D from ~53 m) for the player and
 * the racers, or the traffic's TrafficCarBodyLodSwapSize (80, 40, 20: B
 * from ~13 m, C from ~27 m). Below 18 pixels (~59 m) no environment map,
 * below 4 (~267 m) the car is not drawn. The racers' and the player's
 * street packs are their B (within 9 m the original's A: the port keeps the
 * B there, as before), the traffic's its A; a level the pack has not
 * (load_lods) draws the nearest finer one. */
static const float CAR_LOD_PX[4]={120.f,45.f,20.f,0},TRAFFIC_LOD_PX[4]={80.f,40.f,20.f,0};
enum { CAR_ENVMAP_PX=18, CAR_HIDDEN_PX=4 };
static unsigned car_lod_draws[3][4];   /* [racers, traffic, the player][level drawn] (viewer-stats.json car_lods) */
static unsigned car_lod_hidden,car_lod_unshone;   /* cars left out under 4 pixels; reflections left out under 18 */
/* The slim's swaps farther than the original's (asked of the port): the
 * pixels a car covers taken as the reach's % of them against the table,
 * its levels coming in at that much more distance. The traffic's at twice
 * the distance (B from ~27 m, C ~53 m, D ~107 m): in the calibrated PPSSPP
 * and on a PSP-3000 its finer levels cost nothing to measure. The racers',
 * the player's and the environment map's (18 pixels) at 1.5 times (B to
 * ~36 m, C to ~80 m, the shine to ~89 m): a PSP-3000's Outer Ring with the
 * rivals far ahead in view, the same race by the fixed step, took 99.8 %
 * at 125 and 150 against 99.7-99.8 at the original's and 99.6 at twice;
 * a run at twice with them nearer (the street's full pack where the
 * original draws its D) had taken 0.8 point. The PSP-1000 (small_memory)
 * keeps the original's. */
int car_lod_reach=150;   /* % the racers' and the player's (poked) */
int traffic_lod_reach=200;   /* % the traffic's (poked; 100: the original's) */
int car_shine_reach=150;   /* % every car's environment map (poked) */
static float lod_k(int traffic) { return small_memory?1.f:(traffic?traffic_lod_reach:car_lod_reach)*.01f; }
static float shine_k(void) { return small_memory?1.f:car_shine_reach*.01f; }
int car_lod_force=-1;   /* 0-3 (poked: the calibrated PPSSPP's PPSSPP_CALIB_SET, psp_prof.py --poke): every car at that level, as the original's ForceCarLOD; inspection only */
static float car_px_h=356.f;   /* the view's H (CalculateH: 256 / tan(fov / 2)): the street's 356, the rearview mirror's own (rvm_draw) */
static float car_pixels(float x,float y,float z,const ScePspFVector3 *from) {
    float dx=x-from->x,dy=y-from->y,dz=z-from->z;
    return 3.f*car_px_h/sqrtf(fmaxf(dx*dx+dy*dy+dz*dz,1e-4f));
}
/* The level drawn for px pixels: the table's, the nearest finer one the
 * model has, its pack's own (base) at the finest. */
static int car_level(const Model *mm,float px,int traffic,int base) {
    const float *table=traffic?TRAFFIC_LOD_PX:CAR_LOD_PX;
    px*=lod_k(traffic);
    int want=0;while(want<3 && px<table[want])want++;
    if(car_lod_force>=0)want=car_lod_force;
    if(!mm->nlod)return base;
    for(int l=want;l>base;l--)if(mm->lod_n[l])return l;
    return base;
}
/* The player's car on the street at the level of detail the original draws
 * for its size on screen (draw_street_car's rule, its least level A): its
 * pack is the B, the full paint, down to 45 pixels (~24 m: the replays',
 * the start's and the ending's cameras); below, its stock pack's far levels
 * (player_lods) in its skin and paint, lit by the GE as a racer's, its
 * paint not shaded on the CPU (shade_paint, paint_publish, the sheen), the
 * environment map by the GE (draw_shine) down to 18 pixels. player_pick
 * sets it a frame, before the paint; the street's draw alone (player_street)
 * draws it. */
static int player_level=-1,player_street;static float player_px=1e9f;
static void draw_car(void) {
    if(texture_flush_pending) {sceGuTexFlush();texture_flush_pending=0;}
    car_cull_update();
    lights(0);sceGuTexFunc(GU_TFX_MODULATE,GU_TCC_RGBA);
    int far=player_street && player_level>=0 && !menu_pose;
    uint32_t k0=far?model.lod_at[player_level]:0,k1=far?k0+model.lod_n[player_level]:model.nm;
    if(player_street)car_lod_draws[2][far?player_level:model.nlod?model.lod_base:1]++;
    for(int pass=0;pass<2;pass++) {
        sceGuEnable(GU_LIGHTING);sceGuTexMapMode(GU_TEXTURE_COORDS,0,0);
        if(pass) {sceGuEnable(GU_BLEND);sceGuDepthMask(GU_TRUE);}
        else {sceGuDisable(GU_BLEND);sceGuDepthMask(GU_FALSE);}
        draw_mesh_range(pass,k0,k1);
        sceGuTexFlush();
        if(!pass)probe_mark(PROBE_P_COAT);
        if(debug_view&524288)continue;   /* the paint's key: nothing over it */
        if(far){if(reflections && player_px*shine_k()>=CAR_ENVMAP_PX)draw_shine(&model,pass,k0,k1);continue;}
        draw_reflections(pass);
        if(!pass)probe_mark(PROBE_P_SHEEN),draw_street_sheen();
    }
    sceGuDisable(GU_LIGHT1);sceGuDepthMask(GU_FALSE);
    if(player_look.neon && fleet_car(player_car) && !player_street && !menu_pose)draw_neon(player_look.neon,NULL);   /* (the street's after its shadow: draw_drive; the menus' after their grade) */
    if(fleet_car(player_car) && (piece_open[2]>.5f || piece_open[3]>.5f)) {   /* the engine's and trunk's neon, seen with the hood or lid up */
        static char at[16];static float tube[2][NEON_TUBES_MAX][6];static int nt[2];
        const char *m=fleet_car(player_car)->model;
        if(strcmp(at,m)){snprintf(at,sizeof at,"%s",m);for(int k=0;k<2;k++)nt[k]=garage_neon_tubes(m,k,tube[k]);}
        if(player_look.neon_engine && piece_open[2]>.5f)draw_tubes(tube[0],nt[0],garage_neon(player_look.neon_engine));
        if(player_look.neon_trunk && player_look.audio==3 && piece_open[3]>.5f)draw_tubes(tube[1],nt[1],garage_neon(player_look.neon_trunk));   /* the tubes: the CUSTOM LAYOUT's markers (the others have none) */
    }
}

/* ------------------------------------------------------------------ drive */
/* Playability telemetry for the scripted drivers. */
static float prof[6];static unsigned frame_hist[4];
/* The main menu's frames (script 14's stage 7 holds it there): the vblanks
 * as frame_hist's, and the ms sums of each frame's CPU (its list built),
 * the wait for the last frame's list (ge_fence) and for its flip. */
static unsigned menu_hist[4],menu_n;static double menu_ms[3];
/* Rachel's lines the game puts off (its timer 0x11d960, then 0x14a170 in
 * the Xbox default.xbe): asked for some seconds on, once she is quiet;
 * roam: only the seconds of free roam count. Parameters as bit numbers,
 * -1 any. */
static void hoods_load(const char *path);   /* below, with Rachel's other lines */
enum { LATER_N=8 };
static struct { float left;int roam;const char *event;signed char p[4]; } later[LATER_N];
