    static unsigned us[MAX_READS],offs[CASES][MAX_READS];
    void *buf=memalign(64,512<<10);
    fprintf(o,"card-bench 1 %s city.n2cy %u bytes, open %u us\n",where,size,open_us);
    fprintf(o,"case KB reads total_KB ms MB/s min_ms p50_ms p90_ms max_ms\n");
    uint32_t seed=0x2545f491u;char raw[CASES][24];
    unsigned *all[CASES];int alln[CASES]={0};
