        all[c]=malloc(n*sizeof(unsigned));alln[c]=all[c]?(int)n:0;if(all[c])memcpy(all[c],us,n*sizeof(unsigned));
        qsort(us,n,sizeof(unsigned),us_cmp);
        snprintf(raw[c],sizeof raw[c],"%s%u",cs[c].seq?"row":"scattered",cs[c].kb);
        fprintf(o,"%s %u %u %u %.1f %.3f %.2f %.2f %.2f %.2f%s\n",raw[c],cs[c].kb,n,n*cs[c].kb,sum/1000.f,sum?(double)n*piece/sum:0,
                us[0]/1000.f,us[n/2]/1000.f,us[n*9/10]/1000.f,us[n-1]/1000.f,ok?"":" (a read failed)");
