#endif
    if(vol_is_reserve())return 1;   /* the sleep reserve is the game's own memory: the dialog wants the volatile block alone */
    if(begin){int r=vol_give_back();if(r && vol_paused && vol_save_loader){world_critical_end();vol_paused=0;}return r;}
    if(vol_wanted && savedata_idle() && vol_acquire()){vol_wanted=0;vol_back_in();}
