    if(cycle_left>0){if(!--cycle_left)vol_dialog(0);}
    else if(vol_cycle>0 && vol_held()) {   /* a save's give-back every vol_cycle frames, as the dialog's (the drops' holes, A/B) */
        static unsigned n;
        if(++n>=(unsigned)vol_cycle){n=0;if(vol_dialog(1)){if(vol_cycle_hold>0)cycle_left=vol_cycle_hold;else vol_dialog(0);}}   /* (the dialog's own path: give-back, take again, the view settled) */
    }
