static void heap_sample(unsigned frames) {
    frames_seen=frames;
    if(RELEASE && !in_test)return;   /* (the telemetry's only) */
    kernel_free_watch();
    if(frames%30)return;
    struct mallinfo mi=mallinfo();
    if(frames%600==0 && heap_logged<HEAP_LOG_MAX){unsigned *h=heap_log[heap_logged++];h[0]=frames;h[1]=(unsigned)mi.uordblks;h[2]=(unsigned)mi.arena;h[3]=(unsigned)sceKernelTotalFreeMemSize();}
    if((unsigned)mi.uordblks>heap_peak.used){heap_peak.used=(unsigned)mi.uordblks;heap_peak.frame=frames;}
    if((unsigned)mi.arena>heap_peak.arena)heap_peak.arena=(unsigned)mi.arena;
}
