/* Additional state only: the legacy low-clock history remains inside the
 * sampler. Main alone writes this state; no extra kernel thread queries. */
static struct { int32_t uid[3];uint32_t warm,shown,raw_index,at_us; } coop_runs;
_Static_assert(sizeof coop_runs<=WORLD_COOP_MAIN_STATE_BYTES,"coop main static budget");
static void thread_runs(float *ms,WorldCoopSample *sample,int eligible) {
    sample->at_us=sceKernelGetSystemTimeLow();sample->valid=0;
    uint32_t dt=sample->at_us-coop_runs.at_us;
    int fresh=eligible && sample->raw_index!=UINT32_MAX &&
        sample->shown==coop_runs.shown+1u && sample->raw_index==coop_runs.raw_index+1u &&
        dt>0 && dt<=100000u;   /* a gap over100ms cannot prime the three-sample window */
#ifdef HOST_SIM
    ms[0]=ms[1]=ms[2]=0;sample->game_us=sample->loader_us=sample->mixer_us=0;
    sample->game_uid=sample->loader_uid=sample->mixer_uid=-1;coop_runs.warm=0;
    (void)fresh;
#else
    static uint32_t last[3];SceUID th[3]={sceKernelGetThreadId(),world_loader_thread(),audio_thread_id()};
    uint32_t delta[3];
    for(int q=0;q<3;q++) {
        SceKernelThreadRunStatus status;memset(&status,0,sizeof status);status.size=sizeof status;
        int rc=th[q]>=0?sceKernelReferThreadRunStatus(th[q],&status):-1;
        uint32_t u=rc>=0?status.runClocks.low:last[q];delta[q]=u-last[q];
        ms[q]=delta[q]/1000.f;last[q]=u;   /* preserve legacy RAW values, including invalid samples */
        uint32_t bit=1u<<q;
        if(fresh && rc>=0 && (coop_runs.warm&bit) && coop_runs.uid[q]==th[q])sample->valid|=bit;
        if(eligible && rc>=0)coop_runs.warm|=bit;else coop_runs.warm&=~bit;
        coop_runs.uid[q]=th[q];
    }
    sample->game_us=delta[0];sample->loader_us=delta[1];sample->mixer_us=delta[2];
    sample->game_uid=th[0];sample->loader_uid=th[1];sample->mixer_uid=th[2];
#endif
    coop_runs.shown=sample->shown;coop_runs.raw_index=sample->raw_index;coop_runs.at_us=sample->at_us;
}
#else
static void thread_runs(float *ms) {
#ifdef HOST_SIM
    ms[0]=ms[1]=ms[2]=0;
#else
    static uint32_t last[3];SceUID th[3]={sceKernelGetThreadId(),world_loader_thread(),audio_thread_id()};
    for(int q=0;q<3;q++) {
        SceKernelThreadRunStatus s;memset(&s,0,sizeof s);s.size=sizeof s;
        uint32_t u=th[q]>=0 && sceKernelReferThreadRunStatus(th[q],&s)>=0?s.runClocks.low:last[q];
        ms[q]=(u-last[q])/1000.f;last[q]=u;
    }
#endif
}
#endif
