/* A unit's word, the table's trailing spaces off ("km\xa0"). A ring of
 * buffers: the callers print it at once. */
static const char *unit_word(uint32_t label,const char *english) {
    static char ring[4][24];static int next;
    const char *t=lang_or(label,english);size_t n=strlen(t);
    while(n && (t[n-1]==' ' || (unsigned char)t[n-1]==0xa0))n--;
    char *o=ring[next];next=(next+1)&3;
    snprintf(o,sizeof ring[0],"%.*s",(int)n,t);return o;
}
