static const uint32_t DAWN_LIGHTS=0xe8ffc0;   /* the added lights at dawn (BGR): the terminal's windows warm white, the garage's lamps dimmer, as the PS2's */
static const float FOG_DAWN_START=.6f;static const uint32_t FOG_DAWN=0x00606870;   /* a warm grey haze: rose, it tinted the terminal's windows pink */
/* The dawn's red as the place has it. The cast above (the sky's, the
 * grade's, the screen's, the paint's mirrored sky and road) was fitted at
 * the airport, whose "Sunrise Screen Tint" is a deep rose (189, 62, 113 at
 * 0.88); the Resort Loop's grid has a green-grey one (175, 204, 150 at
 * 0.82) and on the PS2 a grey dawn, its silver cars grey. dawn_warm: how far the
 * place's tint leans to red (its red over the mean of its green and blue,
 * by its intensity), 1 at the airport; each colour of the cast keeps its
 * luma and only that share of its hue. Without the maps, the airport's. */
extern int fog_tints;
float dawn_warm_force=-1;   /* >= 0: this instead of the place's (an A/B; street-tune.txt's 23rd value) */
static float dawn_warm=1;
static const float DAWN_WARM_AIRPORT=.4725f;   /* (1 - (62 + 113) / 2 / 189) x 0.88 */
static void dawn_warm_update(void) {
    float w=1;
    if(dawn_warm_force>=0)w=dawn_warm_force;
    else if(fog_ok() && fog_tints) {
        const FogTint *t=fog_tint();float m=fmaxf(t->r,fmaxf(t->g,t->b));
        w=m>0?(t->r-.5f*(t->g+t->b))/m*fminf(1,fmaxf(0,t->intensity))/DAWN_WARM_AIRPORT:0;
    }
    dawn_warm=fminf(1,fmaxf(0,w));
}
static float dawn_hue(const float *c,int ch) { float l=.299f*c[0]+.587f*c[1]+.114f*c[2];return l+(c[ch]-l)*dawn_warm; }
static uint32_t dawn_hue_bgr(uint32_t c) {   /* the colour (0xAABBGGRR) with the place's share of its hue */
    float f[3];for(int k=0;k<3;k++)f[k]=(c>>(8*k)&255);
    uint32_t o=c&0xff000000u;
    for(int k=0;k<3;k++){float v=dawn_hue(f,k);o|=(uint32_t)fminf(255,fmaxf(0,v+.5f))<<(8*k);}
    return o;
}
