    float f[3]={cam.dir[0].p,cam.dir[1].p,cam.dir[2].p},n=sqrtf(f[0]*f[0]+f[1]*f[1]+f[2]*f[2]);
    if(n<1e-4f){f[0]=sinf(car.yaw);f[1]=0;f[2]=cosf(car.yaw);n=1;}
    for(int i=0;i<3;i++)f[i]/=n;
