static int live_shakes;static float live_peak,live_amp,live_noise;   /* stats: kicks started, the strongest weighted acceleration (m/s^2), the last kick's amplitude, the largest noise angle (deg) */
static float live_terr[2],live_terr_max;static int live_terr_frames;   /* the terrain's frequency and amplitude this frame (debug 4096); stats: its largest amplitude, frames with any */
static float live_dbg[4];   /* debug 4096: noise pitch, yaw; shake pitch, yaw (rad) */
