        if(!cam_high(C[0],C[2]))continue;
        if(!world_wall_strip(C[0],C[2],&nx,&nz,&lo,&hi))return 1;   /* the whole cell */
        float s0=nx*a[0]+nz*a[2],s1=nx*b[0]+nz*b[2];
