/* the block's pointers into the draw's tables; 0: not an N2VS this build reads */
static int vista_compact_fix(unsigned char *d,uint32_t size) {
    const uint32_t *h=(const uint32_t *)d;
    if(size<32 || memcmp(d,"N2VS",4) || h[1]!=1 || h[5]!=size)return 0;
    uint32_t nt=h[2],nm=h[3],nz=h[4];
    if(nt>MAX_TEX || nm>MAX_MESH || 32+48ull*nt+80ull*nm+8ull*nz>size)return 0;
    VistaBound *b=calloc(nm?nm:1,sizeof *b);if(!b)return 0;
    memset(&vista_model,0,sizeof vista_model);memset(vista_levels,0,sizeof vista_levels);
    const unsigned char *t=d+32,*m=t+48*nt;
    for(uint32_t k=0;k<nt;k++,t+=48) {
        const uint32_t *o=(const uint32_t *)(t+8);unsigned lv=t[4];
        if(lv>VISTA_LEVELS){free(b);return 0;}
        for(unsigned j=0;j<=lv;j++)if(o[j+1]>=size || o[0]+1024>size){free(b);return 0;}
        Texture *x=&vista_model.tex[k];x->w=*(const uint16_t *)t;x->h=*(const uint16_t *)(t+2);x->vrepeat=1;x->clut=d+o[0];x->pixels=d+o[1];
        vista_levels[k]=(int)lv;for(unsigned j=0;j<lv;j++)vista_mip[k][j]=d+o[j+2];
    }
    for(uint32_t k=0;k<nm;k++,m+=80) {
        const float *f=(const float *)m;const uint32_t *u=(const uint32_t *)(m+52);
        uint16_t tex=*(const uint16_t *)(m+72);
        if((uint64_t)u[0]+10ull*u[1]>size || (tex!=0xffff && tex>=nt)){free(b);return 0;}
        VistaBound *v=&b[k];
        memcpy(v->center,f,12);memcpy(v->half,f+3,12);memcpy(v->o,f+6,12);v->s=f[9];v->uo=f[10];v->vo=f[11];v->uvs=f[12];
        v->v=(const VistaVertex *)(d+u[0]);v->n=u[1];v->triangles=u[2];v->mesh=k;v->strip=m[74];
        Mesh *e=&vista_model.mesh[k];e->color=u[3];e->flags=u[4];e->texture=tex==0xffff?UINT32_MAX:tex;e->ni=u[2]*3;
        vista_sec_of[k]=m[75];
    }
    vista_model.nt=nt;vista_model.nm=nm;vista_model.bytes=size;vista_model.data=d;
    vista_bounds=b;vista_vertices=NULL;vista_mip_data=NULL;vista_vertex_bytes=size;vista_batches=nm;
    vista_sec=vista_sec_of;vista_vv_zones=nz;vista_zone_tab=m;vista_mask=UINT32_MAX;vista_zone=-2;
    return 1;
}
static void vista_compact_sync(int want) {
    int zone=world_stats()->zone;
    if(vista_jettison_zone!=-3 && zone>=0 && zone!=vista_jettison_zone)vista_jettison_zone=-3;   /* the next zone: tried again */
    if(!want || (debug_view&512)){if(vista_ok || vr_state!=VR_IDLE)vista_jettison();return;}   /* debug 512: held out, as with no room (a diagnosis) */
    if(vista_ok) {
        if(vista_pressure()!=vista_pressure_seen){vista_jettison();vista_jettison_zone=zone;vista_jettisons++;}   /* the city short of room: the panoramas go first */
        return;
    }
    if(vr_state==VR_READ)return;
    if(vr_state==VR_FAIL){vista_jettison();vista_jettison_zone=zone;return;}
    if(vr_state==VR_DONE) {
        unsigned char *d=vr_buf;vr_buf=NULL;vr_state=VR_IDLE;
        sceKernelDcacheWritebackRange(d,vr_size);   /* for the GE */
        if(vista_compact_fix(d,vr_size)){vista_ok=1;vista_compact=1;vista_pressure_seen=vista_pressure();vista_reads++;}
        else{free(d);vista_n2vs_size=0;}   /* not this build's: the old way from now on */
        return;
    }
    if(vista_jettison_zone!=-3 || vista_n2vs_size<=0)return;
    uint32_t used=(uint32_t)mallinfo().uordblks,need=(uint32_t)vista_n2vs_size+(uint32_t)pre_squeeze_kb*1024u;
    if(!memory_profile.heap_budget || used>memory_profile.heap_budget || need>memory_profile.heap_budget-used){vista_jettison_zone=zone;vista_refused++;return;}
    if(vr_go<0) {
        extern char *getcwd(char *buf,size_t size);
        if(!getcwd(vr_dir,sizeof vr_dir)){vista_n2vs_size=0;return;}
        vr_go=sceKernelCreateSema("vista_go",0,0,1,NULL);
        SceUID t=vr_go>=0?sceKernelCreateThread("VistaRead",vista_read_thread,0x30,0x2000,PSP_THREAD_ATTR_USER,NULL):-1;
        if(t<0 || sceKernelStartThread(t,0,NULL)<0){vista_n2vs_size=0;return;}
    }
    if(!(vr_buf=memalign(16,(size_t)vista_n2vs_size))){vista_jettison_zone=zone;vista_refused++;return;}
    sceKernelDcacheWritebackInvalidateRange(vr_buf,(unsigned)vista_n2vs_size);
    vr_size=(uint32_t)vista_n2vs_size;vr_state=VR_READ;sceKernelSignalSema(vr_go,1);
}
/* whether the PSP-1000's profile reads the built pack (the dist has one) */
static int vista_compact_wanted(void) {
    if(!small_memory)return 0;
    if(vista_n2vs_size<0){FILE *f=fopen("vista.n2vs","rb");vista_n2vs_size=0;if(f){if(!fseek(f,0,SEEK_END))vista_n2vs_size=ftell(f);fclose(f);if(vista_n2vs_size<32)vista_n2vs_size=0;}}
    return vista_n2vs_size>0;
}
/* The planes and the spotlights' beams beyond the city's range
 * (worldanim.c), on the skyline's projection out to 9 km: in the skyline's
 * pass, or alone when the street shows no skyline (then the depth they
 * leave cleared, as the skyline's). */
/* The distant layer (world.c's: the original's far LOD sections past the
 * city's range) in the same pass, so the one depth clear after it serves
 * both: a clear of its own cost the 4104 0.85 ms of GE a frame in the
 * calibrated PPSSPP. Its haze: what the city's reaches at its range (the
 * region's intensity), held past it (a ramp 100 km long), as the original's,
 * which never covers more than its intensity, so the city's cells come in
 * over their own far shells in the same fog. draw_drive sets far_layer. */
static struct { int on;float range,s,e;uint32_t c; } far_layer;
static int draw_far_layer(void) {
    float e[3]={eye.x,eye.y,eye.z},fw[3]={-cam_back.x,-cam_back.y,-cam_back.z};
    if(!far_layer.on || world_landmark_range()<=far_layer.range || (debug_view&32)){world_draw_landmarks(e,fw,1e9f);return 0;}   /* none: its last frame's stats cleared */
    float k=far_layer.e>far_layer.s?fminf(1,fmaxf(0,(far_layer.range-far_layer.s)/(far_layer.e-far_layer.s))):1,L=1e5f,ss=far_layer.range-k*L;
    sceGuEnable(GU_FOG);sceGuFog(ss,ss+L,far_layer.c);
#ifdef FAR_DEBUG
    sceGuFog(-2.f,-1.f,0x00ff00ff);   /* diagnosis: the distant layer flat magenta */
#endif
    world_draw_landmarks(e,fw,far_layer.range);
    sceGuDisable(GU_FOG);
    return world_landmark_stats()->drawn_cells>0;
}
#if SKY_METRIC
static void sky_metric_far(int after);   /* the distant layer's pixels for the sky metric (its depth is cleared after it) */
#endif
static void draw_far_world(int alone) {
    float r[3]={ro.x,ro.y,ro.z},e[3]={eye.x,eye.y,eye.z};
    if(alone) {
        sceGumMatrixMode(GU_PROJECTION);sceGumPushMatrix();sceGumLoadIdentity();sceGumPerspective(cur_fovy,(float)W/H,50.f,9000.f);
        sceGumMatrixMode(GU_MODEL);sceGuEnable(GU_DEPTH_TEST);sceGuDepthMask(GU_FALSE);sceGuDisable(GU_FOG);
    }
    worldanim_draw_far(r,e,drive_range());
#if SKY_METRIC
    sky_metric_far(0);
#endif
    int layer=draw_far_layer();
#if SKY_METRIC
    sky_metric_far(1);
#endif
    if(alone) {
        if(worldanim_stats()->drawn_far || layer)sceGuClear(GU_DEPTH_BUFFER_BIT);
        sceGuAlphaFunc(GU_GREATER,96,255);sceGuDisable(GU_FRAGMENT_2X);
        sceGumMatrixMode(GU_PROJECTION);sceGumPopMatrix();sceGumMatrixMode(GU_MODEL);sceGumLoadIdentity();
    }
}
/* The panoramas under the region's haze, as the distant layer past the
 * city's range (draw_far_layer): the original draws the PAN_ sheets as any
 * model of the view, under its fog, as the dome (draw_sky). Unfogged, the
 * night rain's grey fog left them dark cut-outs over it, palms and towers
 * on the sky (beta issue 105). The added lights fade to nothing (a black
 * fog), as the city's (world.c). 0: unfogged, as before (an A/B; poked). */
int vista_region_fog=1;
static int vista_haze(float *start,float *end) {
    if(!vista_region_fog || !far_layer.on)return 0;
    float k=far_layer.e>far_layer.s?fminf(1,fmaxf(0,(far_layer.range-far_layer.s)/(far_layer.e-far_layer.s))):1,L=1e5f;
    if(k<=0)return 0;
    *start=far_layer.range-k*L;*end=*start+L;
    return 1;
}
static void draw_vista(void) {
    vista_drawn=vista_triangles=0;
    if(!vista_ok || !quick_vista){draw_far_world(1);return;}
    unsigned char visible[vista_batches];
    float ty=tanf(cur_fovy*(GU_PI/360.f)),tx=ty*(float)W/H;
    /* Camera-space frustum planes in world space. The AABB's support
     * radius is tighter than its sphere, especially for low, wide hills. */
    ScePspFVector3 forward={-cam_back.x,-cam_back.y,-cam_back.z};
    float planes[6][4]={{forward.x,forward.y,forward.z,-50.f},
                        {-forward.x,-forward.y,-forward.z,9000.f},
                        {forward.x*tx+cam_right.x,forward.y*tx+cam_right.y,forward.z*tx+cam_right.z,0},
                        {forward.x*tx-cam_right.x,forward.y*tx-cam_right.y,forward.z*tx-cam_right.z,0},
                        {forward.x*ty+cam_up.x,forward.y*ty+cam_up.y,forward.z*ty+cam_up.z,0},
                        {forward.x*ty-cam_up.x,forward.y*ty-cam_up.y,forward.z*ty-cam_up.z,0}};
    vista_zone_update();
    for(unsigned k=0;k<vista_batches;k++) {
        visible[k]=1;
        if(vista_pvs && vista_sec && vista_bounds){unsigned sx=vista_sec[vista_bounds[k].mesh];if(sx<32 && !(vista_mask>>sx&1)){visible[k]=0;continue;}}
        if(vista_bounds) {
            const VistaBound *b=&vista_bounds[k];float delta[3]={b->center[0]-eye.x,b->center[1]-eye.y,b->center[2]-eye.z};
            for(int p=0;p<6;p++){
                float d=planes[p][3];
                for(int a=0;a<3;a++)d+=planes[p][a]*delta[a]+fabsf(planes[p][a])*b->half[a];
                if(d<0){visible[k]=0;break;}
            }
        }
        if(visible[k]){vista_drawn++;vista_triangles+=vista_bounds?vista_bounds[k].triangles:vista_model.mesh[k].ni/3;}
    }
    sceGumMatrixMode(GU_PROJECTION);sceGumPushMatrix();sceGumLoadIdentity();sceGumPerspective(cur_fovy,(float)W/H,50.f,9000.f);
    sceGumMatrixMode(GU_MODEL);sceGumLoadIdentity();{ScePspFVector3 o={-ro.x,-ro.y,-ro.z};sceGumTranslate(&o);}
    sceGuEnable(GU_DEPTH_TEST);
    sceGuDepthRange(65535,0);
    if(far_over_vista){draw_far_world(0);sceGumLoadIdentity();ScePspFVector3 o={-ro.x,-ro.y,-ro.z};sceGumTranslate(&o);}   /* first: the panoramas behind its depth */
    sceGuDepthMask(GU_FALSE);sceGuDisable(GU_LIGHTING);sceGuDisable(GU_FOG);   /* sorted among themselves... */
    float hs=0,he=0;int hazed=vista_haze(&hs,&he);uint32_t haze_c=~0u;
    if(hazed)sceGuEnable(GU_FOG);
    sceGuEnable(GU_ALPHA_TEST);sceGuAlphaFunc(GU_GREATER,0x40,0xff);sceGuTexFunc(GU_TFX_MODULATE,GU_TCC_RGBA);
    sceGuTexMapMode(GU_TEXTURE_COORDS,0,0);sceGuTexScale(1,1);sceGuTexOffset(0,0);sceGuEnable(GU_FRAGMENT_2X);
    {
        enum { VT=GU_TEXTURE_16BIT|GU_VERTEX_16BIT|GU_TRANSFORM_3D };
        if(vista_mips){sceGuTexFilter(GU_LINEAR_MIPMAP_LINEAR,GU_LINEAR);sceGuTexLevelMode(GU_TEXTURE_AUTO,0);}
        for(int pass=0;pass<2;pass++){
            if(pass){sceGuEnable(GU_BLEND);sceGuDepthMask(GU_TRUE);}else{sceGuDisable(GU_BLEND);sceGuDepthMask(GU_FALSE);}
            const Texture *bound=NULL;
            for(unsigned k=0;k<vista_batches;k++){
                const VistaBound *b=&vista_bounds[k];const Mesh *m=&vista_model.mesh[b->mesh];
                if(!visible[k] || !!(m->flags&(F_GLASS|F_VISTA_ADD))!=pass)continue;sceGuColor(m->color);
                if(pass)sceGuBlendFunc(GU_ADD,GU_SRC_ALPHA,m->flags&F_VISTA_ADD?GU_FIX:GU_ONE_MINUS_SRC_ALPHA,0,0x00ffffff);   /* the lights over the hills added, as the original (black boxes drawn opaque: beta issue 115) */
                if(hazed){uint32_t c=m->flags&F_VISTA_ADD?0:far_layer.c;if(c!=haze_c){sceGuFog(hs,he,c);haze_c=c;}}
                if(m->texture==UINT32_MAX)sceGuDisable(GU_TEXTURE_2D);
                else {const Texture *t=&vista_model.tex[m->texture];sceGuEnable(GU_TEXTURE_2D);if(t!=bound){vista_bind(m->texture);bound=t;}}
                sceGuTexScale(b->uvs,b->uvs);sceGuTexOffset(b->uo,b->vo);
                sceGumLoadIdentity();{float q=b->s*(32768.f/32767.f);ScePspFVector3 o={b->o[0]-ro.x,b->o[1]-ro.y,b->o[2]-ro.z},k={q,q,q};sceGumTranslate(&o);sceGumScale(&k);}
                sceGumDrawArray(b->strip?GU_TRIANGLE_STRIP:GU_TRIANGLES,VT,b->n,NULL,b->v);
            }
        }
        sceGuDisable(GU_BLEND);sceGuDepthMask(GU_FALSE);sceGuTexScale(1,1);sceGuTexOffset(0,0);sceGuTexFilter(GU_LINEAR,GU_LINEAR);
        if(hazed)sceGuDisable(GU_FOG);
        sceGumLoadIdentity();{ScePspFVector3 o={-ro.x,-ro.y,-ro.z};sceGumTranslate(&o);}
    }
    if(!far_over_vista)draw_far_world(0);
    sceGuDisable(GU_FRAGMENT_2X);
    sceGuClear(GU_DEPTH_BUFFER_BIT);
    sceGuEnable(GU_DEPTH_TEST);sceGuDepthMask(GU_FALSE);sceGuAlphaFunc(GU_GREATER,96,255);   /* ...and behind the whole city */
    sceGumMatrixMode(GU_PROJECTION);sceGumPopMatrix();sceGumMatrixMode(GU_MODEL);sceGumLoadIdentity();
}
/* The PSP-1000's heap (small_memory): the sky the time of day shows, the
 * other two (88 KB each) let go; loaded between frames, the GE done with
 * the last (the street's frame, beside vista_sync). The original keeps the
 * one its track's time of day loads too. */
static void sky_sync(void) {
    if(!small_memory || !world_ok)return;
    int k=tod_sky();if(sky_ok[k])return;
    ge_fence();
    for(int j=0;j<SKY_N;j++)if(j!=k && sky_ok[j]){fail_model(&sky_model[j]);sky_ok[j]=0;}
    sky_ok[k]=load_model_into(&sky_model[k],sky_file[k]);
}
/* The night fog in the sky's colour. The region's night fog (fog_haze) is a
 * warm city glow (120,70,57; 144,77,6...), laid up to its intensity over
 * what the range's edge holds, and the dome behind it is a dark blue (~19,
 * 26,39 at its rim): a far building coming in at the edge stood out against
 * it as a pale column (the 4101 at ~2207). At night the fog takes the
 * dome's rim colour as drawn (its texture's bottom row through its colour),
 * the region's intensity and start kept: the far city fades into the sky
 * behind it. The sky metric over the 4101 and the Outer Ring: 0.83 -> 0.61
 * and 2.01 -> 1.69 pixels a frame. (Tinting the dome's rim with the
 * region's haze instead, in its own pass, moved it 2%.) */
#ifndef SKY_HAZE
#define SKY_HAZE 1
#endif
int sky_haze=SKY_HAZE;   /* 0: the region's night fog colour, as before (poked; make SKY_HAZE=0) */
static uint32_t sky_rim;   /* the dome's rim as drawn last (0x00bbggrr; 0 none yet) */
static uint32_t sky_rim_of(const Model *sm,uint32_t col) {
    const Mesh *m=&sm->mesh[0];if(m->texture==UINT32_MAX)return 0;
    const Texture *t=&sm->tex[m->texture];if(!t->clut)return 0;
    const uint32_t *pal=(const uint32_t *)t->clut;unsigned r=0,g=0,b=0;
    for(uint32_t x=0;x<t->w;x++){uint32_t c=pal[((const uint8_t *)t->pixels)[(t->h-1)*t->w+x]];r+=c&255;g+=(c>>8)&255;b+=(c>>16)&255;}
    r/=t->w;g/=t->w;b/=t->w;
    r=r*(col&255)/255;g=g*((col>>8)&255)/255;b=b*((col>>16)&255)/255;
    return (r|g<<8|b<<16)?r|g<<8|b<<16:1;
}
/* The sky dome hangs below the horizon (its centre 20 m under the eye), and
 * what the city leaves undrawn there (a cell coming in through the screen
 * door, a hole) showed its dark rim: black dots on the asphalt. So the sky
 * stops at the row of the ground ahead where the street's fog is half way
 * (world.c world_ground_fill 2), and under it the clear, in the asphalt's
 * colour, shows instead: fewer pixels than the whole dome, where a band of
 * asphalt drawn over it (world.c ground_fill, 1) cost the PSP-3000 5.6
 * points of the 4127's frames on the card. The row is the ground's line
 * that far ahead, at its lower end (the camera rolls): the sky never cut
 * above the ground. */
#define SKY_CUT_EYE_M 2.f   /* the ground under the eye (the chase camera's ~2 m; the bumper's, lower, cuts less) */
static int sky_cut_row(float fs,float fe) {
    if(world_ground_fill!=2)return H;
    float fx=-cam_back.x,fz=-cam_back.z,l=sqrtf(fx*fx+fz*fz);if(l<1e-3f)return H;fx/=l;fz/=l;
    float d=fmaxf(fs+(fe-fs)*.5f,30.f);
    ScePspFMatrix4 p,v;sceGumMatrixMode(GU_PROJECTION);sceGumStoreMatrix(&p);sceGumMatrixMode(GU_VIEW);sceGumStoreMatrix(&v);sceGumMatrixMode(GU_MODEL);
    float sx[2],sy[2];
    for(int k=0;k<2;k++) {   /* two points of the ground's line d ahead, as far to each side */
        float o=k?d:-d,w[3]={eye.x-ro.x+fx*d-fz*o,eye.y-ro.y-SKY_CUT_EYE_M,eye.z-ro.z+fz*d+fx*o},c[4],q[4];
        for(int r=0;r<4;r++)q[r]=(&v.x.x)[r]*w[0]+(&v.y.x)[r]*w[1]+(&v.z.x)[r]*w[2]+(&v.w.x)[r];
        for(int r=0;r<4;r++)c[r]=(&p.x.x)[r]*q[0]+(&p.y.x)[r]*q[1]+(&p.z.x)[r]*q[2]+(&p.w.x)[r]*q[3];
        if(c[3]<1e-3f)return H;
        sx[k]=(1.f+c[0]/c[3])*(W/2);sy[k]=(1.f-c[1]/c[3])*(H/2);
    }
    float y=sy[0];
    if(fabsf(sx[1]-sx[0])>1e-3f){float a=(sy[1]-sy[0])/(sx[1]-sx[0]);y=fmaxf(sy[0]-a*sx[0],sy[0]+a*(W-sx[0]));}
    return y>=H-1?H:y<1?1:(int)y+1;
}
/* The region's haze over the sky: the original draws the dome as any model
 * of the view (StuffSky, eViewPlatInterface::Render), under the view's fog,
 * so its colour goes toward the place's fog colour by the fog's intensity
 * (the most it lays on the far city): the Street X's yard, its fog a pale
 * yellow at 0.2, had a sky 1.3-1.5 times the port's. Set per frame by
 * draw_drive from the region's fog (sky_haze_k 0: none, as before). */
static float sky_haze_k;static uint32_t sky_haze_c;
