    int ta=a*neon_tube_pct/100;uint32_t col=(uint32_t)(ta>255?255:ta)<<24|garage_neon(k);
    const float (*t)[6]=NULL;int n=neon_under(model,&t),markers=n>0;
    float edge[4][6];
