        float e4[4][6]={{cx-hx,y,cz+hz*.62f,cx-hx,y,cz-hz*.62f},{cx+hx,y,cz+hz*.62f,cx+hx,y,cz-hz*.62f},
                        {cx-hx*.8f,y,cz+hz,cx+hx*.8f,y,cz+hz},{cx-hx*.8f,y,cz-hz,cx+hx*.8f,y,cz-hz}};
        memcpy(edge,e4,sizeof edge);t=(const float (*)[6])edge;n=4;
