    if(band && drape)halo_ground_fill(mm,car_on,neon_halo_mm*.001f);
    for(int i=0;band && i<n;i++) {
        float a0[3]={t[i][0],t[i][1],t[i][2]},b0[3]={t[i][3],t[i][4],t[i][5]};
        if(i==1 && markers) for(int j=0;j<3;j++){float d=(b0[j]-a0[j])*.06f;a0[j]+=d;b0[j]-=d;}   /* the front's middle tube */
        float g0[3]={a0[0],mm->floor_y+.03f,a0[2]},g1[3]={b0[0],mm->floor_y+.03f,b0[2]};
        {float mx=mm->center[0]-(a0[0]+b0[0])*.5f,mz=mm->center[2]-(a0[2]+b0[2])*.5f,l=sqrtf(mx*mx+mz*mz),k2=l>1e-3f?neon_halo_in_mm*.001f/l:0;
         g0[0]+=mx*k2;g0[2]+=mz*k2;g1[0]+=mx*k2;g1[2]+=mz*k2;}   /* in under the car */
        if(drape)q=neon_halo_draped(q,g0,g1,neon_halo_mm*.001f,halo,car_on,measure?&mt:NULL,g0[1]+lift);
        else q=neon_band(q,g0,g1,lift,neon_halo_mm*.001f,halo,NULL);   /* its light on the ground (fading far off, not widening: the original's band widens) */
    }
