    GlowV *tubes=q;
    for(int i=0;a>0 && i<n;i++) {
        float a0[3]={t[i][0],t[i][1],t[i][2]},b0[3]={t[i][3],t[i][4],t[i][5]};
        if(i==1 && markers) for(int j=0;j<3;j++){float d=(b0[j]-a0[j])*.06f;a0[j]+=d;b0[j]-=d;}
        q=neon_band(q,a0,b0,0,neon_tube_mm*.001f*grow,col,eo);   /* (the tubes are the body's: lowered with it; the lift is the halo's, back on the ground) */
    }
