    sceGuDisable(GU_LIGHTING);sceGuEnable(GU_TEXTURE_2D);sceGuEnable(GU_BLEND);sceGuDepthMask(GU_TRUE);sceGuDisable(GU_ALPHA_TEST);
    sceGuBlendFunc(GU_ADD,GU_SRC_ALPHA,GU_FIX,0,0x00ffffff);
