/* The eye in the car's model space (the current model matrix's rotation, transposed). */
static ScePspFVector3 eye_in_car(const Car *c) {
    ScePspFMatrix4 m;sceGumStoreMatrix(&m);
    float d[3]={eye.x-c->x,eye.y-c->y,eye.z-c->z};
    return (ScePspFVector3){m.x.x*d[0]+m.x.y*d[1]+m.x.z*d[2],m.y.x*d[0]+m.y.y*d[1]+m.y.z*d[2],m.z.x*d[0]+m.z.y*d[1]+m.z.z*d[2]};
}
static void draw_neon(int k,const Car *c) {   /* the player's car (its matrix and eye_obj: car_transform, the menus' pose; c: the street's) */
    const FleetCar *f=fleet_car(player_car);
    draw_neon_on(&model,f?f->model:"350Z",neon_lift,k,&eye_obj,c);
}
/* The cars' lamps as the original's (flares.c has the flares' own rules):
 * - each car's head and tail lights at its model's markers: the headlights
 *   on (the game's night), the tail lamps at 0.85 and at full braking, the
 *   centre lamp only braking (Car::UpdateBrakelightsState,
 *   CarRenderInfo::RenderFlaresOnCar). The pedal past 0.05 brakes; the
 *   traffic's lamps stay lit BRAKE_HOLD after it lets go; a rail car (the
 *   traffic on its lane, moved by its driver) brakes while it slows harder
 *   than BRAKE_DECEL.
 * - the streak (UpdateCarStreakingFlares, RenderFlares): with the nitrous
 *   open, and on the free roam's rival while it can be challenged or races,
 *   the tail lamps again along the car's last three frames, 8 between each
 *   two (in the game's order, which also crosses from the newest back to
 *   the oldest), at half the intensity times the nitrous left (the rival:
 *   half), without the headlights. */
static const float BRAKE_HOLD=.5f,TAIL_ON=.85f;
static float lamps_clock,lamps_dt;
int lamps_streak=1,lamps_cars=1;   /* 0: no streak, no cars' flares (A/B; poked) */
/* telemetry (viewer-stats.json "lamps"): frames drawn; the most flares,
 * markers and quads of a frame, quads dropped; frames with lit brake lamps
 * on the player, a racer or the rival, the traffic, and with a streak */
static struct { unsigned frames,flares,markers,quads,dropped,brake_player,brake_racer,brake_traffic,streak,centre,course_max,course_frames; } lamps_log;
static const LampSet *lamps_of(const Car *c);   /* (below, with the racers) */
static float streak_of(const Car *c);
/* model to world: the drawing's turn (sceGumRotateY, X by -pitch, Z), row major */
static void rot_of(float yaw,float pitch,float roll,float m[9]) {
    float sy,cy,sp,cp,sr,cr;flares_sincos(yaw,&sy,&cy);flares_sincos(pitch,&sp,&cp);flares_sincos(roll,&sr,&cr);
    m[0]=cy*cr-sy*sr*sp;m[1]=-cy*sr-sy*cr*sp;m[2]=sy*cp;
    m[3]=sr*cp;         m[4]=cr*cp;          m[5]=sp;
    m[6]=-sy*cr-cy*sr*sp;m[7]=sy*sr-cy*cr*sp;m[8]=cy*cp;
}
/* Once a frame, before the cars are drawn: the traffic's hold, the streak's frames. */
static void lamps_update(void) {
    float dt=world_clock-lamps_clock;lamps_clock=world_clock;if(dt<0 || dt>.25f)dt=0;
    lamps_dt=dt;
    Car *all[TRAFFIC_MAX+8];int na=gather_cars(all);
    for(int i=0;i<na;i++) {
        Car *c=all[i];
        if(!c->traffic)c->brake_hold=0;
        else if(c->brake_in>.05f)c->brake_hold=BRAKE_HOLD;
        else if(c->brake_hold>0)c->brake_hold-=dt;
        if(dt>0) {   /* a new frame of the game */
            c->trail_at=(c->trail_at+1)%3;float *t=c->trail[c->trail_at];
            t[0]=c->x;t[1]=c->y;t[2]=c->z;t[3]=c->yaw;t[4]=c->pitch;
            if(c->trail_n<3)c->trail_n++;
        }
    }
}
static void draw_flares(void) {
    float e[3]={eye.x,eye.y,eye.z},r[3]={cam_right.x,cam_right.y,cam_right.z},u[3]={cam_up.x,cam_up.y,cam_up.z},b[3]={cam_back.x,cam_back.y,cam_back.z};
    flares_begin(e,r,u,b,cur_fovy,lamps_dt);
    float cp=cosf(car.pitch),at[3]={car.x,car.y,car.z},nose[3]={sinf(car.yaw)*cp,sinf(car.pitch),cosf(car.yaw)*cp};
    flares_draw_world(at,nose);
    probe_mark(PROBE_L_CARS);
    Car *all[TRAFFIC_MAX+8];int na=gather_cars(all);int seen=0;
    for(int i=0;i<na;i++) {
        const Car *c=all[i];
        if((c==&car && ((debug_view&64) || (cam.view==VIEW_BUMPER && !scene_camera()))) || (c->blink>0 && (shown&1)))continue;   /* not drawn (a reset's ghost: every other frame) */
        const LampSet *s=lamps_of(c);if(!s || !s->n || !lamps_cars)continue;
        float dx=c->x-eye.x,dz=c->z-eye.z;
        if(dx*dx+dz*dz>210.f*210.f || world_sphere_outside(c->x,c->y+.5f,c->z,9.f))continue;
        float m[9],p[3]={c->x,c->y,c->z};rot_of(c->yaw,c->pitch,c->roll,m);
        int br=car_braking(c);
        float lf=fminf(1.f,(210.f-sqrtf(dx*dx+dz*dz))/30.f);   /* out at 210 m, up to whole 30 m in: not lit at once */
        flares_draw_car(s,m,p,lf,(br?1:TAIL_ON)*lf,(br?1:0)*lf,c==&car?garage_bulb_colour(player_look.lights):0);
        if(br)seen|=c==&car?1:c->traffic?4:2;
        if(br)for(int q=0;q<s->n;q++)if(s->lamp[q].kind==LAMP_CENTRE)seen|=16;
        float k=streak_of(c);
        if(k>0 && c->trail_n>=3)seen|=8;
        if(k<=0 || c->trail_n<3 || !lamps_streak)continue;
        for(int seg=3;seg>0;seg--) {
            const float *a=c->trail[(seg+c->trail_at+1)%3],*z=c->trail[(seg+c->trail_at+2)%3];
            float ma[9];rot_of(a[3],a[4],0,ma);
            flares_draw_streak(s,ma,a,z,8,(br?1:TAIL_ON)*k,br?k:0);
        }
    }
    flares_end(e);
    const FlareStats *fs=flares_stats();lamps_log.frames++;
    if(fs->flares>lamps_log.flares)lamps_log.flares=fs->flares;
    if(fs->markers>lamps_log.markers)lamps_log.markers=fs->markers;
    if(fs->quads>lamps_log.quads)lamps_log.quads=fs->quads;
    lamps_log.dropped+=fs->dropped;
    if(fs->course_flares>lamps_log.course_max)lamps_log.course_max=fs->course_flares;
    lamps_log.course_frames+=fs->course_flares>0;
    lamps_log.brake_player+=seen&1;lamps_log.brake_racer+=(seen>>1)&1;lamps_log.brake_traffic+=(seen>>2)&1;
    lamps_log.streak+=(seen>>3)&1;lamps_log.centre+=(seen>>4)&1;
}
/* The menus' car (RenderFEFlares, RenderFlaresOnCar without a Car): its
 * headlights lit, the tail lamps at their 0.85, the centre lamp out; drawn
 * over the graded scene, as the game's flares come after its car. The
 * game's RenderFECarFlares starts at 0 and only the shop's Headlight Bulb
 * category (slot 0x9f, IceSelectionScreen: the Car Specialties Shop's
 * Lights) sets it: elsewhere the menus' car has its lamps out (beta issue
 * 29); there in the bulbs browsed (beta issue 54). */
int fe_flares=0;   /* 1: drawn everywhere (poked, to compare) */
static unsigned fe_flares_frames;   /* telemetry: frames with the menu car's flares drawn */
static int fe_bulbs_shown(void);static uint32_t fe_bulbs(void);   /* (the shop's: below) */
static void draw_fe_flares(float fovy) {
    if((!fe_flares && !fe_bulbs_shown()) || !model.lamps.n)return;
    float e[3]={eye.x,eye.y,eye.z},r[3]={cam_right.x,cam_right.y,cam_right.z},u[3]={cam_up.x,cam_up.y,cam_up.z},b[3]={cam_back.x,cam_back.y,cam_back.z};
    ScePspFMatrix4 M;   /* the car's place: the turntable's turn, lowered as drawn */
    sceGumMatrixMode(GU_MODEL);sceGumLoadIdentity();car_on_platform();
    {ScePspFVector3 o={0,-MENU_DROP,0};sceGumTranslate(&o);}
    sceGumStoreMatrix(&M);sceGumLoadIdentity();
    float m[9]={M.x.x,M.y.x,M.z.x,M.x.y,M.y.y,M.z.y,M.x.z,M.y.z,M.z.z},p[3]={M.w.x,M.w.y,M.w.z},o[3]={ro.x,ro.y,ro.z};
    flares_begin(e,r,u,b,fovy,0);
    flares_draw_car(&model.lamps,m,p,1,TAIL_ON,0,fe_bulbs());
    flares_end(o);
    if(flares_stats()->quads)fe_flares_frames++;
}
/* The Nitrous Purge's shop: the car on the turntable blows the kit browsed
 * (purge_smoke), in bursts (1.2 s of every 2.1), as the game's car shows it. */
static int fe_purge_kit(void);   /* the kit browsed, -1 none (the shop's: below) */
static void purge_smoke(int kit,const float m[9],const float p[3],const float v[3],const Model *mm,const char *model,float dt);
static unsigned fe_purge_frames;   /* telemetry: frames the menus' car purged */
static float fe_purge_cycle;       /* its bursts' clock */
static void draw_fe_purge(float dt) {
    static int was;float cycle=fe_purge_cycle;int kit=fe_purge_kit();const FleetCar *f=fleet_car(player_car);
    if(kit<0 || !f){if(was)fx_clear();was=0;return;}
    if(!was){fx_clear();cycle=0;was=1;}   /* (the street's left over: not drawn here) */
    ScePspFMatrix4 M;   /* the car's place, as draw_fe_flares' */
    sceGumMatrixMode(GU_MODEL);sceGumLoadIdentity();car_on_platform();
    {ScePspFVector3 o={0,-MENU_DROP,0};sceGumTranslate(&o);}
    sceGumStoreMatrix(&M);sceGumLoadIdentity();
    float m[9]={M.x.x,M.y.x,M.z.x,M.x.y,M.y.y,M.z.y,M.x.z,M.y.z,M.z.z},p[3]={M.w.x,M.w.y,M.w.z},v[3]={0,0,0};
    fx_update(dt);
    cycle=fe_purge_cycle=fmodf(cycle+dt,2.1f);
    if(cycle<1.2f){purge_smoke(kit,m,p,v,&model,f->model,dt);fe_purge_frames++;}
    float r[3]={ro.x,ro.y,ro.z},rt[3]={cam_right.x,cam_right.y,cam_right.z},u[3]={cam_up.x,cam_up.y,cam_up.z};
    sceGuEnable(GU_DEPTH_TEST);fx_draw(r,rt,u);
}
/* The Car Specialties Shop's Hydraulics browsed: the menus' car bounces on
 * the level on trial, as the original's garage screen (fe_hydraulics.h,
 * beta issue 70); at rest otherwise, and closed with the menus
 * (front_close_all). Its body on the plane of its corners (the hubs), the
 * wheels down to the turntable until their corner passes the lift height. */
static int fe_hydro_level(void);   /* the level browsed, 0 none (the shop's: below) */
static FeHydro fe_hydro={0,0,10.f,{0,0,0,0}};
static unsigned fe_hydro_frames;static float fe_hydro_peak;   /* telemetry: frames off rest, the highest corner (m) */
static void fe_hydro_update(float dt) {
    fe_hydro_step(&fe_hydro,fe_hydro_level(),dt);
    if(fe_hydro_moving(&fe_hydro)) {
        fe_hydro_frames++;
        for(int i=0;i<4;i++)fe_hydro_peak=fmaxf(fe_hydro_peak,fe_hydro.h[i]);
    }
}
/* the corner (0 front left, 1 front right, 2 rear right, 3 rear left) of
 * the model's wheel k, -1 none (x left, z ahead) */
static int fe_hydro_corner(int k) {
    if(!(model.hubs>>k&1))return -1;
    int front=model.hub[k][2]>0,left=model.hub[k][0]>0;
    return front?(left?0:1):(left?3:2);
}
/* The body's lift and tilt, on the matrix of the car placed and lowered
 * (car_on_platform, MENU_DROP); travel: the wheels' MENU_DROP, less each
 * corner's drop. */
static void fe_hydro_apply(float *travel) {
    if(!fe_hydro_moving(&fe_hydro))return;
    float x[4]={0,0,0,0},z[4]={0,0,0,0};int found=0;   /* (no hub at a corner: no tilt, fe_hydro_pose) */
    for(int k=0;k<4;k++){int c=fe_hydro_corner(k);if(c>=0 && !(found>>c&1)){x[c]=model.hub[k][0];z[c]=model.hub[k][2];found|=1<<c;}}
    if(found!=15)for(int c=0;c<4;c++)x[c]=z[c]=0;
    float h,p,r;fe_hydro_pose(&fe_hydro,x,z,&h,&p,&r);
    ScePspFVector3 up={0,h,0};sceGumTranslate(&up);sceGumRotateX(-p);sceGumRotateZ(r);   /* (GU: x left, so +Z lifts the left; +X dips the nose) */
    for(int k=0;travel && k<4;k++){int c=fe_hydro_corner(k);travel[k]=MENU_DROP-(c>=0?fe_hydro_wheel_drop(&fe_hydro,c):0);}
}
/* The player's headlights on the street (eUpdateHeadlightCamera and the
 * ground's headlight mode): a camera on the car, 2 m ahead of its centre
 * and 4 m up, looks down its nose tilted 0.8 down for 1 ahead (~39
 * degrees), 80 degrees high by 4:3 across, 1 to 100 m; the ground in its
 * view takes its pattern (the Xbox's HEADLIGHTS, the GameCube's
 * HEADLIGHTS2) times the bulbs' colour (the stock 0x48554800, doubled) on
 * its own light. The game lights whatever scenery its camera sees; the
 * port lays a grid on the road ahead instead (a second pass of the world
 * is beyond the GE's budget): worked out once on the car's floor (x
 * across, z ahead: where the pattern lands on a road as flat as the car's
 * floor, and how far it has faded toward 100 m), then each frame its rows
 * are set on the road. A row's centre takes the ground's height there
 * (its 1 m cell's, world_ground_cell: the blended world_ground cost five
 * times as much; half the rows a frame, the other half's from the frame
 * before; the rows under the car take its ground, the far two faded ones
 * the row before's lift; each look-up from the row before's height, so a slope,
 * a dip and a crest are followed; a row where the ground is not known
 * keeps the row before's lift), its points moved by the same height
 * straight up or down (across the row, the car's own roll), a little
 * above the road (more far away, where the rows are farther apart than a
 * crest's curve), and the pattern projected again from the light onto
 * where they now are. A flat grid in the car's matrix ran into the road
 * ahead on a rise and on landing, and hung over the far side of a crest.
 * The GE lays it on the street drawn under it as street x (1 + pattern x
 * colour x headlight_gain): the destination's colour is the source's
 * factor. */
int headlight_cone=1;   /* 0: none (an A/B; poked) */
int headlight_gain=300;   /* % (the street's own light is dim at night: the game adds the pattern to it, not over it; poked) */
static const float HL_ROWS[]={-1,.5f,2.2f,4.5f,7.6f,11.5f,16.5f,23,32,46,66,90};
enum { HL_U=7, HL_V=(int)(sizeof HL_ROWS/sizeof HL_ROWS[0]) };
typedef struct { float u,v;uint32_t c;float x,y,z; } HlVertex;
static HlVertex __attribute__((aligned(16))) hl_grid[HL_U*HL_V];static float hl_floor=1e9f;static int hl_gain;static uint32_t hl_grid_bulb;
/* The player's bulbs (the Car Specialties Shop's Lights: garage_bulb_colour,
 * CarRenderInfo's colour, the stock 0x48554800) and the light's colour by
 * them: each channel doubled, times headlight_gain, halved (drawn doubled:
 * GU_FRAGMENT_2X). */
