    {P *q=sceGuGetMemory(2*sizeof(P));q[0]=(P){0xffffffff,0,0,0};q[1]=(P){0xffffffff,128,64,0};
     sceGuDrawArray(GU_SPRITES,GU_COLOR_8888|GU_VERTEX_32BITF|GU_TRANSFORM_2D,2,NULL,q);}
    sceGuBlendFunc(GU_ADD,GU_FIX,GU_SRC_COLOR,0,0);   /* dst * vertex colour: black at the top */
    {P *q=sceGuGetMemory(4*sizeof(P));q[0]=(P){0xff000000,0,0,0};q[1]=(P){0xff000000,128,0,0};q[2]=(P){0xffffffff,0,WET_FADE,0};q[3]=(P){0xffffffff,128,WET_FADE,0};
     sceGuDrawArray(GU_TRIANGLE_STRIP,GU_COLOR_8888|GU_VERTEX_32BITF|GU_TRANSFORM_2D,4,NULL,q);}
