    if(half_frame!=shown)frame_halve();
    sceGuDisable(GU_DEPTH_TEST);sceGuDepthMask(GU_TRUE);sceGuDisable(GU_FOG);sceGuDisable(GU_ALPHA_TEST);sceGuDisable(GU_LIGHTING);
    sceGuEnable(GU_TEXTURE_2D);sceGuTexMapMode(GU_TEXTURE_COORDS,0,0);sceGuTexFilter(GU_LINEAR,GU_LINEAR);sceGuTexWrap(GU_CLAMP,GU_CLAMP);
    sceGuTexScale(1,1);sceGuTexOffset(0,0);sceGuTexMode(GU_PSM_5650,0,0,0);
