        sceGuDrawBufferList(GU_PSM_5650,(void *)BLUR_S,256);sceGuScissor(0,0,256,128);sceGuDisable(GU_BLEND);
        sceGuTexFunc(GU_TFX_REPLACE,GU_TCC_RGB);sceGuTexImage(0,256,128,256,vram+WET_A);
        blur_rect(0,0,256,128,0,0,256,128,0x80808080);
        sceGuDisable(GU_TEXTURE_2D);sceGuEnable(GU_BLEND);sceGuBlendFunc(GU_REVERSE_SUBTRACT,GU_FIX,GU_FIX,fl<<16|fl<<8|fl,0xffffff);
        {P *q=sceGuGetMemory(2*sizeof(P));q[0]=(P){0xffffffff,0,0,0};q[1]=(P){0xffffffff,256,128,0};
         sceGuDrawArray(GU_SPRITES,GU_COLOR_8888|GU_VERTEX_32BITF|GU_TRANSFORM_2D,2,NULL,q);}
        sceGuDrawBufferList(GU_PSM_8888,draw_offset,STRIDE);sceGuScissor(0,0,W,H);sceGuTexFlush();sceGuEnable(GU_TEXTURE_2D);
        sceGuTexImage(0,256,128,256,vram+BLUR_S);sceGuBlendFunc(GU_ADD,GU_FIX,GU_FIX,0xcccccc,0xffffff);   /* + 0.8 */
        blur_rect(0,0,W,H,0,0,256,128,0xffffffff);
