        keep=1;for(int i=BLUR_N-1;i>=0;i--){b[i]=i?fminf(1.f,w[i]/sum/keep):1.f;keep*=1-b[i];}
        float dist=(2.f+blur.nos_t*(4.f-2.f)/15.f)*1.2f*.75f,r=blur.dir[0],u=blur.dir[1],fw=blur.dir[2];
        sceGuDrawBufferList(GU_PSM_5650,(void *)BLUR_S,256);sceGuScissor(0,0,256,128);sceGuDisable(GU_BLEND);
        sceGuTexImage(0,256,128,256,vram+WET_A);sceGuTexFunc(GU_TFX_MODULATE,GU_TCC_RGB);sceGuEnable(GU_FRAGMENT_2X);   /* the grey 130: 128 is 1 */
