                if(t1<128)blur_rect(0,t1,256,128,0,t1,256,128,one);
                if(x0>0)blur_rect(0,t0,x0,t1,0,t0,x0,t1,one);
                if(x1<256)blur_rect(x1,t0,256,t1,x1,t0,256,t1,one);
