/* ------------------------------------------------------------------ races */
/* Retail race events on courses built from their outlines (convert_races.py).
 * The player races three AI opponents in tuned cars; traffic stays on. */
/* Opponents: the vinyl-and-rims presets (presets/opponents) and the stock
 * fleet. A race picks among the cars open by its career stage (stage 0
 * and 1: the starters), the strongest few, so they climb with the career
 * as the original's do. */
typedef struct { char pack[24],phys[24],label[12];float top,score;int stage,fleet; } OppCar;
static const char *opp_presets[][2]={{"opp-skyline","SKYLINE"},{"opp-rx8","RX8"},{"opp-supra","SUPRA"},{"opp-eclipse","ECLIPSE"},
                                     {"opp-lancerevo8","LANCEREVO8"},{"opp-imprezawrx","IMPREZAWRX"}};
enum { OPP_MAX=48, OPP_PICK=6, RACERS=4 };
static OppCar opp_pool[OPP_MAX];static int opp_n;
/* each rival's parts and profile as matched to the player (opp_match), its top speed */
static CarPerf opp_perf[RACERS-1];static CarPhys opp_tuned[RACERS-1];static float opp_top[RACERS-1];
static float opp_measure[RACERS];   /* telemetry: the player's measure, then each rival's */
static void opp_pool_build(void) {
    opp_n=0;
    for(int i=0;i<fleet_count() && opp_n<OPP_MAX;i++) {
        const FleetCar *f=fleet_car(i);OppCar *o=&opp_pool[opp_n++];
        snprintf(o->pack,sizeof o->pack,"car-%s",f->model);snprintf(o->phys,sizeof o->phys,"car-%s",f->model);
        snprintf(o->label,sizeof o->label,"%s",f->shortname);o->top=f->top_ms;o->score=f->accel+f->top+f->handling;o->stage=f->flags&FLEET_OPEN?0:f->stage;o->fleet=i;
        for(int p=0;p<6 && opp_n<OPP_MAX;p++)if(!strcmp(opp_presets[p][1],f->model)) {   /* its tuned preset, a little ahead */
            OppCar *t=&opp_pool[opp_n++];*t=*o;snprintf(t->pack,sizeof t->pack,"%s",opp_presets[p][0]);snprintf(t->phys,sizeof t->phys,"%s",opp_presets[p][0]);t->score+=.05f;
        }
    }
    if(!opp_n)for(int p=0;p<6;p++){OppCar *o=&opp_pool[opp_n++];   /* no fleet table: the presets */
        snprintf(o->pack,sizeof o->pack,"%s",opp_presets[p][0]);snprintf(o->phys,sizeof o->phys,"%s",opp_presets[p][0]);
        snprintf(o->label,sizeof o->label,"%s",opp_presets[p][1]);o->top=61.f;o->score=1;o->stage=0;o->fleet=-2;}
}
/* A career preset's car (career_rival_preset: Caleb and his crew, their
 * opp-NAME packs) in the pool, added the first time: on its model's stock
 * physics, matched as a random rival is, never drawn by a stage (OPP_CREW);
 * -1 without its pack or room. */
enum { OPP_CREW=99 };
static int opp_pool_preset(const char *pack,const char *model) {
    for(int i=0;i<opp_n;i++)if(!strcmp(opp_pool[i].pack,pack))return i;
    int fl=-1;for(int i=0;i<fleet_count();i++)if(!strcmp(fleet_car(i)->model,model)){fl=i;break;}
    char name[48];snprintf(name,sizeof name,"%s.n2pv",pack);
    FILE *t=fl>=0 && opp_n<OPP_MAX?fopen(name,"rb"):NULL;if(!t)return -1;
    fclose(t);
    const FleetCar *f=fleet_car(fl);OppCar *o=&opp_pool[opp_n];
    snprintf(o->pack,sizeof o->pack,"%s",pack);snprintf(o->phys,sizeof o->phys,"car-%s",f->model);
    snprintf(o->label,sizeof o->label,"%s",f->shortname);o->top=f->top_ms;o->score=-1;o->stage=OPP_CREW;o->fleet=fl;
    return opp_n++;
}
/* The OPP_PICK strongest cars open by stage (the stage 1 starters below). */
static int opp_candidates(int stage,int *out) {
    int n=0;
    for(int i=0;i<opp_n;i++)if(opp_pool[i].stage<=(stage<1?1:stage)) {
        int at=n<OPP_PICK?n++:OPP_PICK;   /* insertion into the top OPP_PICK by score */
        if(at==OPP_PICK && opp_pool[i].score<=opp_pool[out[OPP_PICK-1]].score)continue;
        if(at==OPP_PICK)at=OPP_PICK-1;
        while(at>0 && opp_pool[out[at-1]].score<opp_pool[i].score){out[at]=out[at-1];at--;}
        out[at]=i;
    }
    return n;
}
/* A quick race (the PS2's: the 206 against a 106, a Corolla and a Focus):
 * the stock cars of the player's car's tier (open at the start, or its
 * stage), in the fleet's order, then the nearest in the fleet's figures;
 * in their stock paint. The 106 is a European car the US data lacks. */
static int quick_next;   /* the next race_start is a quick race's */
static int opp_like_player(int *out) {
    const FleetCar *me=fleet_car(player_car);float ms=me?me->accel+me->top+me->handling:1.5f;int n=0;
    int tier=me?(me->flags&FLEET_OPEN?-1:me->stage):-1;
    for(int i=0;i<opp_n && n<RACERS-1;i++) {
        const FleetCar *f=opp_pool[i].fleet>=0?fleet_car(opp_pool[i].fleet):NULL;
        if(!f || opp_pool[i].fleet==player_car || strncmp(opp_pool[i].pack,"car-",4))continue;
        if((f->flags&FLEET_OPEN?-1:f->stage)==tier)out[n++]=i;
    }
    while(n<RACERS-1) {
        int best=-1;float bd=1e9f;
        for(int i=0;i<opp_n;i++) {
            if(opp_pool[i].fleet<0 || opp_pool[i].fleet==player_car || strncmp(opp_pool[i].pack,"car-",4))continue;
            int dup=0;for(int q=0;q<n;q++)dup|=out[q]==i;if(dup)continue;
            float d=fabsf(opp_pool[i].score-ms);if(d<bd){bd=d;best=i;}
        }
        if(best<0)break;out[n++]=best;
    }
    return n;
}
enum { RACE_OFF, RACE_COUNTDOWN, RACE_ON, RACE_DONE };
#define HURRY_S 30.f   /* a drift's time to finish after the first rival (RaceParameters::InitWithDefaults) */
static char drift_word[24];   /* the last combo's word (drift_word_for) */
