/* No I/O from a draw call (the system dialog is a main-thread operation). */
static const char *profile_label(void) { return profile_name[0]?profile_name:"No Profile"; }
static int test_look_far=1;   /* (poked) the test driver's traffic forecast as far as it takes to stop (PathDriver.look_far) */
static int race_row=-1;   /* the career race on (its row), -1 none */
