    if(!d){opp_dress_why[k]=OPP_DRESS_BUILD;return 0;}
    plain_model=1;int ok=load_model_buffer(&opp_model[k],d,len);plain_model=0;   /* (the model owns d) */
    if(!ok){fail_model(&opp_model[k]);opp_dress_why[k]=OPP_DRESS_PARSE;return 0;}
    look_lamps(&opp_model[k],f->model,l);
    model_strips(&opp_model[k]);
