        for(uint32_t t=0;t<opp_model[k].nt;t++)if(opp_model[k].tex[t].key==0){Texture *x=&opp_model[k].tex[t];x->clut=NULL;x->pixels=opp_skin[k];x->w=x->h=OPP_SKIN;}
