    zone_reset();
    ge_fence();
    fe_free(tourn_res_s);fe_free(tourn_std_s);tourn_res_s=tourn_std_s=NULL;   /* (read again at the next course's end) */
    fe_free(sponsor_pop_s);sponsor_pop_s=NULL;
