        for(int k=0;k<race.nr;k++){const Car *c=race.r[k].c;p[k]=(RPose){c->x,c->y,c->z,c->ground,c->yaw,c->pitch,c->roll,c->steer,c->spin,c->wheel};}
        if(!(rp_n&1))replay_record_traffic();
        while(rp_laps<16 && race.r[0].lap>rp_laps)rp_lap_end[rp_laps++]=rp_n/(float)rp_hz;
