        if(!p->on || p->model>=TRAFFIC_MODELS || !traffic_ok[p->model]){tr->active=0;continue;}
        float dx=q->x-p->x,dz=q->z-p->z;
        if(!q->on || q->model!=p->model || q->skin!=p->skin || dx*dx+dz*dz>15*15){q=p;dx=dz=0;}
        Car *c=&tr->car;float ox=c->x,oz=c->z;
