        c->x=p->x+dx*tf;c->y=p->y+(q->y-p->y)*tf;c->z=p->z+dz*tf;c->ground=c->y;
        c->yaw=lerp_angle(p->yaw/10430.f,q->yaw/10430.f,tf);c->pitch=(p->pitch+(q->pitch-p->pitch)*tf)/64.f;c->roll=(p->roll+(q->roll-p->roll)*tf)/64.f;
        c->vx=dx*rp_hz/rp_tdiv;c->vz=dz*rp_hz/rp_tdiv;c->vy=0;c->steer=0;
