    {static const int view_pov[VIEW_N]={[VIEW_FAR]=TV_POV_FAR,[VIEW_NEAR]=TV_POV_NEAR,[VIEW_HOOD]=TV_POV_HOOD,[VIEW_BUMPER]=TV_POV_BUMPER,[VIEW_DRIFT]=TV_POV_DRIFT,[VIEW_NEAR_PC]=TV_POV_NEAR,[VIEW_FAR_PC]=TV_POV_FAR};tvcam_start_pov(view_pov[rp_view%VIEW_N]);}   /* it opens in the race's own view */
