static int loading_refused(const char *stage);
/* Past the results, the original puts the player's car on the course's
 * line and its racers go (RaceCoordinator::RCStatePostRaceCallback, at
 * CAnimLocator::FindRaceAnimOriginPosition: a sprint's finish line, a
 * circuit's start): the free roam starts there, not wherever the car
 * stopped (beta issue 92). The spot on the course facing along it, else
 * the first clear one up to 40 m before it, either side (a drag's middle
 * is the station's pillars). at: the line's x, y, z and yaw (GU), taken
 * while the course still runs the race's way. Check only resident base
 * collision, under the loader ACK, before ending the race or retiring its
 * overlay. A refused query must leave the origin's owners and pose intact. */
static int race_return_pose(const float at[4],float pose[4]) {
    int previous=world_collision_base_only(1);if(previous<0)return 0;
    float fx=sinf(at[3]),fz=cosf(at[3]),rx=cosf(at[3]),rz=-sinf(at[3]),gy;
    int found=0;
    for(int d=0;d<=40;d+=4)for(int k=0;k<5;k++) {
        float side=(k&1?1:-1)*2.5f*((k+1)/2),px=at[0]-fx*d+rx*side,pz=at[2]-fz*d+rz*side,py=at[1];
        /* car_fits allows an unstreamed cell. A new street pose needs
         * actual ground and collision, not that permissive answer. */
        if(!world_collision_known(px,pz) || !world_ground(px,pz,py,4.f,4.f,&gy))continue;
        py=gy;
        if(car_fits(px,py,pz,at[3])){pose[0]=px;pose[1]=py;pose[2]=pz;pose[3]=at[3];found=1;goto done;}
    }
done:
    world_collision_base_only(previous);
    return found;
}
static int spawn_place(const float p[4]);
/* Return to Explore Mode (the pause's, Post Race's): a city race's too goes
 * back to where it was engaged, the street's place by its marker kept as it
 * started (NotifyEnterEvent's; RaceStarter::StartCareerFreeRoamFromInGame
 * reads it back, NotifyEnterFreeRoamFromPostRace and FromPause leave it),
 * after the finish or halfway through (beta issue 198). A race with no such
 * place (a test's start off the street) as before: after the finish its
 * line, halfway where the car is. */
static void race_leave(void) {
    step_mark("race-leave");
    int q=race.quick,ev=race.event;
    int closed_city=!q && world_level;
    if(closed_city && !race_city_return_matches(ev)){loading_refused("postrace-city-origin");return;}
    if(closed_city && (world_critical_closed() || !world_critical_begin(10000))){loading_refused("postrace-city-owner");return;}
    int to_engage=!q && !world_level && race_city_return_matches(ev);
    float at[4],pose[4];int to_line=!q && !world_level && race.state==RACE_DONE && !to_engage;   /* (a closed track's: its marker in the city, back_to_city) */
    if(to_line){
        if(world_critical_closed() || !world_critical_begin(10000)){loading_refused("postrace-return-owner");return;}
        const RaceEvent *e=race_event(ev);course_pose(e,e->circuit?0:e->length,&at[0],&at[1],&at[2],&at[3]);
        if(!race_return_pose(at,pose)){loading_refused("postrace-line-placement");return;}
    }
    race_end();
    if(admission_failed)return;   /* an overlay-owner failure keeps the gate closed */
    menu=MENU_OFF;   /* a pause return consumes its menu only after retirement */
    if(q){post_stage=0;front_request=FRONT_MAIN;ui_seen.quick_races++;return;}
    if(to_line){
        car_set_phys(&car,player_phys());car_place(&car,pose[0],pose[1],pose[2],pose[3],model.floor_y,player_top());camera_snap();nos_sync(1);
        world_critical_end();   /* the validated base pose committed before any movie can change residents */
    }
    if(to_engage){
        memcpy(pose,race_city_return.pose,sizeof pose);race_city_return.valid=0;
        step_mark("race-leave-engage");spawn_place(pose);   /* no ground there: where the car is */
        if(admission_failed)return;
    }
    step_mark("back-to-city");back_to_city(ev);
    if(admission_failed)return;   /* no movies/roam or UI commit after a failed city load/placement */
    post_stage=0;
    step_mark("race-leave-movies");movies_play();   /* the story's next scenes, only after the street pose commits */
    step_mark("race-leave-roam");career_roam_begin();step_mark("race-leave-done");
}
/* A restart, as the original's (RaceCoordinator's restart stage): the
 * scene again, skipped to its countdown, with its short sound. */
static void race_restart(void) {
    int ev=race.event,q=race.quick,rv=race_reversed(ev);race_end();if(admission_failed)return;menu=MENU_OFF;post_stage=0;race_set_reversed(ev,rv);quick_next=q;race_restarting=1;
    int solo=race_solo;if(dyno_test_on)race_solo=1;   /* the test track's run alone */
    int started=race_start(ev);race_solo=solo;race_restarting=0;if(!started)return;race.quick=q;
    if(dyno_test_on)dyno_test_race_setup();
    else if(q)quick_apply();   /* Restart keeps None, laps, opponents and difficulty. */
    if(q && !race_intro_finish_loading(race_event(ev),1))return;
    intro_skip_now();
}
