static FeScreen *map_s,*engage_s;
static int map_events[CAREER_MAX],map_n,map_sel,engage_ev=-1,engage_declined=-1,engage_from_map,engage_auto=1,engage_choice,engage_speech;static unsigned engage_pick;
#define HUD_COVERED (replay_on || (results_up() && results_s && menu==MENU_OFF) || fin_scene_on() || shopnis_active() || menu==MENU_MAP || menu==MENU_IGMAP || menu==MENU_SHOP || menu==MENU_STATUS || menu==MENU_OPTS || menu==MENU_AUDIO || menu==MENU_ENGAGE || menu==MENU_SPONSOR || menu==MENU_SMS || menu==MENU_TIP || menu==MENU_SHOWGO || (menu==MENU_MAIN && (race.state!=RACE_OFF || pause_s)))   /* the pause hides the HUD, in a race and on the street, as the PS2's (beta issue 116) */
/* The races menu lists the career in order (all events when there is no
 * career data). */
static int race_index_of(int id) { for(int i=0;i<races_count();i++)if(race_event(i)->id==id)return i;return -1; }
static int menu_race_count(void) { return career_count()?career_count():races_count(); }
