/* The race's screens (the HUD, the pause, the five of the debrief): at boot,
 * and on the PSP-1000's heap (small_memory) let go while the frontend is up
 * and read again when it closes: its Parts (parts.n2ui, 1.45 MB) found no
 * block with them in (4.8 MB free, the largest 0.9 MB). The original's
 * frontend and its in-game screens share no pool either (FEngMemoryPool
 * holds the screen shown). out: let go; loads, drops and the last load's ms
 * for the telemetry. */
static struct { int out;unsigned drops,loads,garage_out;float ms; } race_screens;   /* garage_out: the garage's catalogue freed for a race (garage_unload) */
static void race_screens_load(void) {
    uint64_t t0=sceKernelGetSystemTimeWide();
    ge_fence();
    hud_s=hud_race_s=fe_load("hud.n2ui");pause_s=fe_load("pause.n2ui");fe_widen(pause_s,480.f/640.f);results_s=fe_load("results.n2ui");reward_s=fe_load("reward.n2ui");stats_s=fe_load("stats.n2ui");if(stats_s)fe_show(stats_s,1,1);postrace_s=fe_load("postrace.n2ui");if(postrace_s){fe_show(postrace_s,1,1);fe_widen(postrace_s,480.f/640.f);}replay_s=fe_load("replay.n2ui");if(replay_s)fe_show(replay_s,1,1);
    fe_show(pause_s,1,1);fe_show(results_s,1,1);fe_show(reward_s,1,1);debrief_gen++;
    hud_style_s[0]=hud_style_s[1]=NULL;hud_gen++;
    if(race_screens.out) {
        if(world_ok && !traffic_navail)traffic_load();
        race_screens.out=0;race_screens.loads++;race_screens.ms=(sceKernelGetSystemTimeWide()-t0)/1000.f;
    }
}
static int race_screens_drop(void) {
    if(!small_memory || race_screens.out || race.state!=RACE_OFF || replay_on)return 0;
    ge_fence();ge_flip_wait();
    if(hud_mode_s){fe_free(hud_mode_s);hud_mode_s=NULL;hud_mode_of=-1;}
    FeScreen **all[]={&hud_race_s,&pause_s,&results_s,&reward_s,&stats_s,&postrace_s,&replay_s};
    for(unsigned k=0;k<sizeof all/sizeof *all;k++){fe_free(*all[k]);*all[k]=NULL;}
    hud_s=NULL;hud_style_s[0]=hud_style_s[1]=NULL;hud_gen++;debrief_gen++;
    /* and the replay's buffers (0.77 MB of poses, the traffic's): the
     * frontend plays none, the next race takes them again (race_replay_ensure) */
    replay_release();
    /* and the traffic's models (~1 MB, the six with their strips, read
     * together at boot): the garage's custom car found no room for its rims
     * and its skin; the original's frontend and track keep their cars in
     * pools of their own (CarLoader) */
    for(int i=0;i<TRAFFIC_MAX;i++)traffic[i].active=0;
    for(int i=0;i<TRAFFIC_MODELS;i++)if(traffic_ok[i]){fail_model(&traffic_model[i]);traffic_ok[i]=0;}
    traffic_navail=0;
    /* and the racers' (~0.9 MB, the three of the last race): the next start
     * reads its own (load_racer, as opp_loaded no longer matches); the
     * showroom's 1.1 MB found the heap 8.4 MB free and no block for it */
    opp_models_drop();
    race_screens.out=1;race_screens.drops++;
    return 1;
}
/* The PSP-1000's heap (small_memory): through a race the city's cells need
 * every block (the 2nd Bellevue, the Outer Ring, the University Hill and the
 * Black Tusk took turns in red as the frame's time moved), so the pause
 * (251 KB) and the five screens of its end (613 KB) are not kept while it
 * runs: the pause read as it opens and let go as it shuts, the end's as the
 * race ends (race_debrief_ensure), the city giving them room (fe_load_room);
 * race_screens_sync, once a street frame. The original's FEng pool holds
 * the screen shown, 400 KB. */
static int race_debrief_ensure(void);
static void debrief_drop(void) {
    ge_fence();
    FeScreen **all[]={&results_s,&reward_s,&stats_s,&postrace_s,&replay_s};
    for(unsigned k=0;k<sizeof all/sizeof *all;k++){fe_free(*all[k]);*all[k]=NULL;}
    debrief_gen++;
}
static int results_up(void);
static void race_screens_sync(void) {
    if(!small_memory || race_screens.out)return;
    static int tried;   /* the end's screens: once a race's end (none: its plain text) */
    if(menu==MENU_MAIN && !pause_s){pause_s=fe_load("pause.n2ui");if(pause_s){fe_widen(pause_s,480.f/640.f);fe_show(pause_s,1,1);}}
    else if(menu==MENU_OFF && pause_s && (race.state==RACE_ON || race.state==RACE_COUNTDOWN)){ge_fence();fe_free(pause_s);pause_s=NULL;}
    if(race.state==RACE_DONE && !results_s && !tried) {
        tried=1;race_debrief_ensure();
        if(!pause_s){pause_s=fe_load("pause.n2ui");if(pause_s){fe_widen(pause_s,480.f/640.f);fe_show(pause_s,1,1);}}   /* the post-race's pause, there till the next start */
    }
    if(race.state!=RACE_DONE)tried=0;
    if((race.state==RACE_ON || race.state==RACE_COUNTDOWN) && results_s && !replay_on)debrief_drop();
    /* and the garage's catalogue (~220 KB of names): the car is built, the
     * race asks for none; the frontend's next look reads it again */
    if(race.state==RACE_ON && garage_unload())race_screens.garage_out++;
}
static int race_assets_ensure(void) {
    if(!race_replay_ensure())return 0;
    if(small_memory){debrief_drop();if(pause_s && menu==MENU_OFF){fe_free(pause_s);pause_s=NULL;}admission_log("debrief-on-demand",1,0,-1);return 1;}
    return race_debrief_ensure();
}
static int race_debrief_ensure(void) {
    if(small_memory)city_room(700u<<10);
    FeScreen *owners[FE_DEBRIEF_COUNT]={results_s,reward_s,stats_s,postrace_s,replay_s};
    FeDebriefReport report;int ok=fe_debrief_ensure(owners,&report);
    admission_log(fe_load_stage_name(report.stage),ok,report.requested_bytes,report.failed_slot);
    /* the PSP-1000's: a screen that found no block (the generator's replay,
     * 0.85 MB, in a heap 64 KB short: the front-flow's results gone, v0.2.4)
     * takes the room it asked from the city, then the city's residents, as a
     * car's load (load_player); the street's next frame asks its cells again */
    for(int retry=0;!ok && small_memory && retry<2 && report.failed_slot>=0 && report.loads[report.failed_slot].error==ENOMEM;retry++) {
        size_t n=report.loads[report.failed_slot].requested_bytes;
        if(retry==0)city_room((unsigned)(n+n/4+(32u<<10)));else city_retire();
        ok=fe_debrief_ensure(owners,&report);
        admission_log(retry?"debrief-city-retire":"debrief-city-room",ok,report.requested_bytes,report.failed_slot);
    }
    if(!ok)return 0;
    results_s=owners[FE_DEBRIEF_RESULTS];reward_s=owners[FE_DEBRIEF_REWARD];stats_s=owners[FE_DEBRIEF_STATS];
    postrace_s=owners[FE_DEBRIEF_POSTRACE];replay_s=owners[FE_DEBRIEF_REPLAY];debrief_gen++;
    admission_log("debrief-owners",1,report.owned_after,-1);
    return 1;
}
/* A loaded bank's PCM malloc request, as audio_aems_load made it (decode
 * may shorten playback, not that allocation), and its file's size. Kept
 * by the load: reading the file's header here again opened the four
 * banks at every admission line, 40 opens before a race (16/10), each a
 * walk of the Memory Stick's folder. No mixer pointers are borrowed. */
static unsigned admission_bank_bytes(int slot,unsigned *compressed) {
    if(compressed)*compressed=0;
    return snd_ok?audio_aems_bytes(slot,compressed):0;
}
/* Requested owner bytes are components of mallinfo.used, never an amount
 * to add to it. Texture bytes are already inside world.resident_bytes.
 * Strip scratch is a serial bound, not a persistent owner or a measurement. */
/* Written only in a diagnostic run (a smoke, tools/boot_flow.py's drive, or
 * a memory-admission.on beside the game): appended at every load's stage,
 * it reached 103 MB in the main dist (16/10), opened over host0: at each
 * one in plain play. Past 4 MB at the boot it moves to
 * memory-admission.old.jsonl and starts again; 2000 entries a boot at most. */
static int admission_diag=-1;   /* -1 not decided yet, 0 off, 1 on (main) */
static void admission_log(const char *stage,int ok,unsigned requested,int slot) {
    last_mark=stage;last_mark_ms=(uint32_t)(sceKernelGetSystemTimeWide()/1000);
    static int entries,rotated;
    if(admission_diag<=0 || entries>=2000)return;
    if(!rotated) {
        rotated=1;FILE *q=fopen("memory-admission.jsonl","rb");
        if(q){fseek(q,0,SEEK_END);long n=ftell(q);fclose(q);
              if(n>4L<<20){remove("memory-admission.old.jsonl");rename("memory-admission.jsonl","memory-admission.old.jsonl");}}
    }
    FILE *f=fopen("memory-admission.jsonl","a");if(!f)return;
    entries++;
    allocator_diag_emit(f,race_serial);
    struct mallinfo h=mallinfo();const WorldStats *w=world_stats();
    unsigned packs=0,derived=0,strips=0,scratch=0;int models=0;
    for(int k=0;k<RACERS-1;k++){const Model *m=&opp_model[k];models+=m->data!=NULL;
        if(m->data)packs+=m->bytes;
        if(m->coat_data)derived+=m->coat_bytes+m->paint_bytes;
        if(m->strip_data)strips+=m->strip_owned_bytes;
        if(m->strip_scratch_bound>scratch)scratch=m->strip_scratch_bound;
    }
    const IntroPrepareInfo *p=intro_prepare_info();
    fprintf(f,"{\"stage\":\"%s\",\"ok\":%d,\"race_serial\":%u,\"requested_bytes\":%u,\"slot\":%d,\"gate_closed\":%d,\"heap_used\":%d,\"heap_free\":%d,\"heap_arena\":%d,\"world_resident_reported\":%u,\"world_texture_included\":%u,\"models\":%d,\"model_packs_owned\":%u,\"model_coat_paint_owned\":%u,\"model_strips_owned\":%u,\"strip_scratch_serial_bound\":%u,\"debrief_owned\":%u,\"replay_owned\":%u,\"intro_prepared_owned\":%u,\"intro_prepare_stage\":%d,\"rival_bank\":\"%s\",\"showroom_owned\":%d}\n",
        stage,ok,race_serial,requested,slot,world_critical_closed(),h.uordblks,h.fordblks,h.arena,w->resident_bytes,w->tex_bytes,models,packs,derived,strips,scratch,race_debrief_owned(),race_replay_owned(),p->owned_bytes,p->status,snd_ok?audio_aems_bank(1):"",scene.blob!=NULL);
    WorldOwnedBytes owned;
    fprintf(f,"{\"stage\":\"%s-owner-detail\",\"intro_live_owned\":%u,\"rating_owned\":%u,\"worker_owner_snapshot_valid\":%d",stage,intro_live_bytes(),garage_rating_stats()->resident_bytes,world_owned_bytes(&owned));
    if(world_owned_bytes(&owned))fprintf(f,",\"world_cell_blobs\":%u,\"world_split_blobs\":%u,\"world_textures_mips\":%u,\"world_batches\":%u,\"world_calls\":%u,\"world_items\":%u,\"world_archive_metadata_partial\":%u",owned.cell_blob_bytes,owned.split_bytes,owned.texture_bytes,owned.batch_bytes,owned.call_bytes,owned.item_bytes,owned.archive_metadata_bytes);
    fprintf(f,",\"audio_pcm_requested_from_immutable_assets\":[%u,%u,%u,%u],\"audio_single_replacement_overlap_bound\":%u}",admission_bank_bytes(0,NULL),admission_bank_bytes(1,NULL),admission_bank_bytes(2,NULL),admission_bank_bytes(3,NULL),admission_audio_overlap_bound);
    fprintf(f,"\n");fclose(f);
}
static void postrace_open(int from) { post_stage=3;postrace_from=from;postrace_sel=0;postrace_ask=0; }
static void stats_open(int from) { stats_at=0;for(int k=0;k<race.nr;k++)if(race.place[k]==0)stats_at=k;stats_from=from;post_stage=2; }
