/* World map (from the pause, in free roam): the open career events. */
static void map_open(void) {
    if(!map_s){map_s=fe_load("worldmap.n2ui");fe_show(map_s,1,1);ui_open=NULL;}
    map_n=0;
    for(int k=0;k<career_count();k++)if(career_state()->open[k] && career_on_radar(k) && race_index_of(career_event(k)->id)>=0)map_events[map_n++]=k;   /* never a hidden race (IsEventVisibleOnRadar, beta issue 180) */
    if(!map_s || !map_n){if(menu_race_count()){menu=MENU_RACES;menu_sel=0;}return;}   /* the plain list without it */
    if(map_sel>=map_n)map_sel=0;
    menu=MENU_MAP;ui_seen.maps++;
}
/* The event dialog (UI_EngageRaceDialog.fng): it opens on Decline
 * (RaceEngageDialog's INIT_COMPLETE), Left picks Accept, Right Decline, Up
 * and Down nothing; X takes it, O declines (beta issue 179). */
static void engage_open(int k,int from_map) {
    if(!engage_s){engage_s=fe_load("engage.n2ui");fe_show(engage_s,1,1);ui_open=NULL;}
    if(!engage_s){race_say("Unable to open race. Please try again.");race.note_timer=3.f;return;}
    engage_ev=k;engage_from_map=from_map;engage_choice=1;menu=MENU_ENGAGE;ui_seen.engages++;
    {   /* Rachel on the prologue's three races, once each, as their dialog comes
         * (CareerSpeech::HandleEngageRequest), off if declined (HandleEngageDecline) */
        static unsigned said;const CareerEvent *e=career_event(k);int id=e?e->id:0,bit=id==4011?1:id==4001?2:id==4102?4:0;
        engage_speech=0;
        if(bit && e->stage==0 && !(said&bit)) {
            said|=(unsigned)bit;engage_speech=id==4011?audio_speech_match("Career",0,19,0,-1):id==4001?audio_speech_match("Career",0,20,3,-1):audio_speech_match("Career",0,21,9,-1);
            career_said+=engage_speech;
        }
    }
    engage_pick=shown*2654435761u>>16;   /* its body drawn among the row's, as the original's bRandom */
    career_engage(k,"career.sav");   /* the race engaged (a hidden one found) */
}
