/* Script 199's findings (viewer-stats flow199) */
static struct { int yaw,crib,event,hidden_k,hidden_open,hidden_street,hidden_radar,offer_rachel,offer_own,stage;char room[24];float left[3],raced[2],back[3],moved,from_raced; } flow199={.hidden_k=-1,.stage=-1};
/* The shops' scenes (shopnis.c): the shop the career's street entered
 * (its exit scene when the shop is left), -1 none; and the scene's step. */
static int shop_city=-1;
/* The career's garage menu (UI_CareerCrib.fng) in the garage's own room
 * however it was reached: from the pause's Jump to Garage
 * (PauseMenu::QuitToCrib: FEngSetFirstFrontendScreen("UI_CareerCrib.fng"))
 * and from the main menu's Career (StartCareerHelper), as from its door; the
 * crib's CarViewer platform, CRIB01 (uiCareerCrib::Setup). Without it the
 * garage's menu came up over the main menu's showroom (beta issue 199).
 * Set as the garage menu opens, cleared with the main menu. */
static int crib_room;
/* The menus' room: the shop's the car came in from off the street (the
 * original's +0x40 of its record), the career's garage's, else the showroom */
static const char *scene_wanted(void) {
    static const char *const room[]={"shop-CARLOT01.n2sc","shop-PERFSHOP01.n2sc","shop-PARTSSHOP01.n2sc",
                                     "shop-PAINTSHOP01.n2sc","shop-AUDIOSHOP01.n2sc","shop-CRIB01.n2sc"};   /* by SHOP_* */
    const CareerShop *sh=shop_city>=0?career_shop(shop_city):NULL;
    if(!sh && crib_room && career_count())return room[SHOP_CRIB];
    return sh && sh->kind<6?room[sh->kind]:"showroom.n2sc";
}
/* The frontend's ambience zone (EAXS_PFController::GetAmbientZone, its
 * frontend branch), by the shop the car came in from as the menus' room:
 * the car lot (CARLOT01) 0x17, the garage (CRIB01) 0x1d, the performance
 * shop (PERFSHOP01) 0x1a or the hidden CC_MEGALOW's 0x18, the parts shop
 * (PARTSSHOP01) 0x17 for SH_BODYSHOP and 0x19 for the others, the
 * graphics shop (PAINTSHOP01) 0x1b, the specialties (AUDIOSHOP01) 0x16; in
 * the career with no shop the garage's 0x1d; outside the career 0x1c (the
 * main menu, Quick Race, the options, My Cars). Beta issue 176. */
static int front_ambience_zone(void) {
    const CareerShop *sh=shop_city>=0?career_shop(shop_city):NULL;
    if(sh)switch(sh->kind) {
        case SHOP_LOT:return 0x17;
        case SHOP_CRIB:return 0x1d;
        case SHOP_PERF:return !strcmp(sh->name,"CC_MEGALOW")?0x18:0x1a;
        case SHOP_BODY:return !strcmp(sh->name,"SH_BODYSHOP") || !strcmp(sh->name,"SH_BODYSHOP_01")?0x17:0x19;
        case SHOP_GRAPHICS:return 0x1b;
        case SHOP_SPECIALTY:return 0x16;
        default:return -1;
    }
    if(crib_room && career_count())return 0x1d;
    return 0x1c;
}
