/* A tournament's next course (the URL's): a quick race's stays one, as
 * race_restart keeps it (race_start clears race.quick), with its options and
 * its load ended as for its first course; without, its second course was a
 * career race's: the reward screen, Post Race with Return to Explore Mode,
 * and Quit to Main Menu not taken as the quick race's end. */
static void tourn_next(void) { int next=race.tour[race.tour_at+1],at=race.tour_at+1,q=race.quick;race_end();if(admission_failed)return;post_stage=0;tour_keep=1;quick_next=q;if(!race_start(next))return;race.tour_at=at;race.quick=q;if(q){quick_apply();race_intro_finish_loading(race_event(next),1);} }
/* Post Race's item taken (after its question, if it asks one) */
static void postrace_take(int act) {
    switch(act) {
    case PR_NEXT:tourn_next();break;
    case PR_EXPLORE:race_leave();break;   /* race_leave commits the UI only after the return succeeds */
    case PR_RESTART:race_restart();break;
    case PR_STATS:if(stats_s && race.mode!=RMODE_DRIFT)stats_open(3);break;
    case PR_REPLAY:replay_start();break;
    case PR_QUIT:if(race.quick)race_leave();else{race_end();if(!admission_failed){post_stage=0;gps_off();front_request=FRONT_MAIN;}}break;
    }
}
static int menu_input(uint32_t pressed) {
    if(dyno_hold)return 0;   /* on the dyno's rollers its screens are the pause */
    if(menu!=MENU_OFF && menu!=MENU_SMS)menu_sound(pressed);   /* the pause, map, dialogs and sponsorship (the SMS: its own, below) */
    if(menu==MENU_OFF) {
        if(replay_on){replay_input(pressed);return 0;}   /* Start leaves the replay, as the PS2's (not a pause: the playback runs) */
        /* Start pauses, but not once the race's end is up: the original's
         * RaceCoordinator leaves the pause request unanswered in its post-race
         * state (RCStatePostRaceCallback; beta issues 154 and 191) */
        if((pressed&PSP_CTRL_START) && !results_up()){menu=MENU_MAIN;menu_sel=0;pause_ask=0;return 1;}
        if((pressed&PSP_CTRL_SELECT) && race.state==RACE_OFF && career_count()){sms_summon();return menu!=MENU_OFF;}
        if((pressed&PSP_CTRL_DOWN) && race.state==RACE_OFF && career_count() && !world_level && !((pressed&CTL_SHIFT_DOWN) && manual_on() && race.drag.gear>1)){status_open();return menu!=MENU_OFF;}   /* Career Status, as the PS2's Down (a manual gearbox's Down shifts down to first: manual_control) */
        if(results_up()) {
            if(!results_s){if(pressed&PSP_CTRL_CROSS){race_leave();return 1;}return 0;}
            if(post_stage==2) {   /* Post Race Stats: Left/Right the racers, Triangle (or O) back */
                if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_UP))stats_at=(stats_at+race.nr-1)%race.nr;
                if(pressed&(PSP_CTRL_RIGHT|PSP_CTRL_DOWN))stats_at=(stats_at+1)%race.nr;
                if(pressed&(PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE))post_stage=stats_from;
                return 1;
            }
            if(post_stage==3 && postrace_ask) {   /* OK / Cancel */
                menu_sound(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT|PSP_CTRL_CROSS|PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE));
                if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT))postrace_ok=!postrace_ok;
                if(pressed&(PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE))postrace_ask=0;
                else if(pressed&PSP_CTRL_CROSS) {
                    int act=postrace_ask-1;postrace_ask=0;
                    if(postrace_ok)postrace_take(act);
                }
                return 1;
            }
            if(post_stage==3) {   /* Left/Right pick, X takes, Triangle (or O) back */
                int n;const PostItem *it=postrace_items(&n);if(postrace_sel>=n)postrace_sel=n-1;
                int before=postrace_sel;
                if((pressed&(PSP_CTRL_LEFT|PSP_CTRL_UP)) && postrace_sel>0)postrace_sel--;   /* no wrapping, as the PS2's */
                if((pressed&(PSP_CTRL_RIGHT|PSP_CTRL_DOWN)) && postrace_sel<n-1)postrace_sel++;
                /* IconScrollerMenu plays navigation sounds when the selection moves. */
                uint32_t sound=pressed&(PSP_CTRL_CROSS|PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE);
                if(postrace_sel!=before) sound|=pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT|PSP_CTRL_UP|PSP_CTRL_DOWN);
                menu_sound(sound);
                if(pressed&(PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE))post_stage=postrace_from;
                else if(pressed&PSP_CTRL_CROSS) {
                    const char *l2;int act=it[postrace_sel].action;
                    if(postrace_question(act,&l2)){postrace_ask=act+1;postrace_ok=0;}
                    else postrace_take(act);
                }
                return 1;
            }
            if(post_stage==4 && (pressed&(PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE))){post_stage=0;return 1;}   /* the standings: back to the course's */
            if(post_stage==0 && (pressed&PSP_CTRL_SQUARE) && stats_s && race.mode!=RMODE_DRIFT){stats_open(0);return 1;}   /* Race Stats, on the player's row */
            if(pressed&PSP_CTRL_CROSS) {
                if(tourn_on() && post_stage==0 && tourn_std_s){post_stage=4;return 1;}   /* the course's points, then the standings (Triangle or O: back, below) */
                if(postrace_more() && (post_stage==4 || !tourn_std_s)) {   /* the tournament's next course: the career's Post Race (Next Race), the quick race's straight on */
                    if(!race.quick && postrace_s){postrace_open(post_stage);return 1;}
                    tourn_next();return 1;
                }
                if(post_stage==4)post_stage=0;   /* its last: on as a race's end */
                if(post_stage==0 && race.quick && postrace_s){postrace_open(0);return 1;}   /* the quick race: Post Race, as the PS2's (no reward) */
                if(post_stage==1 && !race.quick && career_count() && career_needs_sponsor() && !sponsor_pop_s) {
                    sponsor_pop_s=fe_load("sponsorpop.n2ui");
                    if(!sponsor_pop_s && small_memory && pause_s && fe_memory_failure()) {
                        /* The pause screen is idle here; race_screens_sync reloads it on demand. */
                        fe_free(pause_s);pause_s=NULL;ui_open=NULL;
                        sponsor_pop_s=fe_load("sponsorpop.n2ui");
                    }
                    if(sponsor_pop_s) {
                        fe_show(sponsor_pop_s,1,1);fe_widen(sponsor_pop_s,480.f/640.f);post_stage=5;ui_open=NULL;return 1;
                    }
                }
                if(post_stage==0 && reward_s)post_stage=1;
                else if(post_stage==1 && postrace_s)postrace_open(1);   /* the career's Post Race after the reward */
                else race_leave();
                return 1;
            }
            if(post_stage==1 && (pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE))){post_stage=0;return 1;}
            if(post_stage==5 && (pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE))){post_stage=1;return 1;}   /* the popup: back to the reward */
        }
        return 0;
    }
    if(menu==MENU_IGMAP){igmap_input(pressed);return 1;}
    if(menu==MENU_SHOWGO) {   /* UI_EngageEventDialog: Accept (the countdown) or Decline */
        if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT|PSP_CTRL_UP|PSP_CTRL_DOWN))showgo.choice=!showgo.choice;
        if((pressed&PSP_CTRL_CROSS) && !showgo.choice) {
            const CareerShow *v=career_show(showgo.show);menu=MENU_OFF;
            showgo.state=SG_GO;showgo.left=v->time;showgo.started++;
            gps_off();gps_to_show(showgo.show);   /* destination and its marker share the showcase identity */
        } else if(pressed&(PSP_CTRL_CROSS|PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE)){showgo.state=SG_OFF;showgo.declined=showgo.show;menu=MENU_OFF;}   /* not again until the car leaves it */
        return 1;
    }
    if(menu==MENU_TIP) {   /* UI_EngageMessageDialog: X Advance to gameplay, O Go to Inbox */
        if(pressed&(PSP_CTRL_CROSS|PSP_CTRL_START))menu=MENU_OFF;
        else if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE)){menu=MENU_OFF;sms_open();}
        return 1;
    }
    if(menu==MENU_STATUS) {   /* Left/Right the pages, X Continue */
        if((pressed&PSP_CTRL_LEFT) && status_page>0)status_page--;
        if((pressed&PSP_CTRL_RIGHT) && status_page<2)status_page++;
        if(pressed&(PSP_CTRL_CROSS|PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE|PSP_CTRL_START))menu=MENU_OFF;
        return 1;
    }
    if(menu==MENU_OPTS || menu==MENU_AUDIO){opts_input(pressed);return 1;}
    if(menu==MENU_SHOP) {   /* UI_EngageShopDialog: Enter Shop or Cancel, Cancel in focus (EngageShopDialog's INIT_COMPLETE) */
        if(pressed&PSP_CTRL_LEFT)engage_choice=0;else if(pressed&PSP_CTRL_RIGHT)engage_choice=1;   /* UIMSG_GO_LEFT/RIGHT: Accept/Decline, no wrap; Up/Down nothing (beta issue 179) */
        if((pressed&PSP_CTRL_CROSS) && !engage_choice) {
            menu=MENU_OFF;
            gps_off();   /* into any shop off the street the GPS stops, its target or not (PlayerCareerState::NotifyEnterShopFromFreeRoam) */
            step_mark("shop-visit");
            spawn_here(shop_at);   /* NotifyEnterShopFromFreeRoam: the car's place, and the shop to come out of on a resume */
            career_visit_shop(shop_at,"career.sav");   /* the required street visit and its SMS, never a frontend-only garage load */
            shop_city=shop_at;   /* left, the shop lets the car out to the street there */
            step_mark("shop-enter-scene");
            int started=shop_scene_start(shop_at,SHOPNIS_ENTER);
            if(started==0)shop_go_in();   /* the car drives in through its door first (ShopNIS), then the shop */
        }
        else if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE|PSP_CTRL_CROSS))menu=MENU_OFF;   /* a new Up edge may ask again */
        return 1;
    }
    if(menu==MENU_MAP) {
        /* CribWorldMapScreen::ScrollEvent: held at the list's ends, no wrap (beta issue 135) */
        if((pressed&(PSP_CTRL_LEFT|PSP_CTRL_UP)) && map_sel>0)map_sel--;
        if((pressed&(PSP_CTRL_RIGHT|PSP_CTRL_DOWN)) && map_sel<map_n-1)map_sel++;
        if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE)){menu=MENU_MAIN;menu_sel=1;}
        else if(pressed&PSP_CTRL_START)menu=MENU_OFF;
        else if(pressed&PSP_CTRL_CROSS)engage_open(map_events[map_sel],1);
        return 1;
    }
    if(menu==MENU_SPONSOR) {   /* a contract stage cannot start without one: no way out but signing */
        /* IconScrollerMenu: Left/Right from sponsor to sponsor, to the
         * ends; its CTextScroller: Up/Down the contract's terms */
        int was=sponsor_sel;
        if((pressed&PSP_CTRL_LEFT) && sponsor_sel>0)sponsor_sel--;
        if((pressed&PSP_CTRL_RIGHT) && sponsor_sel<sponsor_n-1)sponsor_sel++;
        if(sponsor_sel!=was)sponsor_scroll=0;
        if(pressed&PSP_CTRL_UP)sponsor_scroll=sms_text_scroll(sponsor_scroll,sponsor_lines,-1);
        if(pressed&PSP_CTRL_DOWN)sponsor_scroll=sms_text_scroll(sponsor_scroll,sponsor_lines,1);
        if(pressed&PSP_CTRL_CROSS) {
            const CareerSponsor *sp=career_sponsor(sponsor_list[sponsor_sel]);
            career_sign_sponsor(sponsor_list[sponsor_sel],"career.sav");
            char m[40];snprintf(m,sizeof m,"%s  +$%d",sp->name,sp->bonus);race_say(m);menu=MENU_OFF;
            ge_fence();fe_free(sponsor_s);sponsor_s=NULL;ui_open=NULL;   /* four times a career: not kept (its logos) */
        }
        return 1;
    }
    if(menu==MENU_SMS) {
        if(!sms_reading && sms_delete_ask) {   /* "Are you sure you want to delete this message?" */
            if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT|PSP_CTRL_UP|PSP_CTRL_DOWN))sms_delete_yes=!sms_delete_yes;
            if((pressed&PSP_CTRL_CROSS) && sms_delete_yes && sms_n) {
                career_sms_delete(sms_list[sms_sel]);sms_list_build();
                if(!sms_n){menu=MENU_OFF;career_save("career.sav");}   /* the last one of its mailbox: back to the street (SMSMailboxViewer state 3) */
            }
            menu_sound(pressed);   /* the dialog's, as the other menus' */
            if(pressed&(PSP_CTRL_CROSS|PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE))sms_delete_ask=0;
        } else if(!sms_reading) {
            /* SMSMailboxViewer: Up/Down the subjects (no wrap), L/R the
             * mailboxes (PAD_LTRIGGER/RTRIGGER; the D-pad's Left and Right
             * have no answer there), X reads, Square deletes, Triangle back
             * to the street (O as well, the PSP's back). Its sounds are its
             * own (its NotifySoundMessage gives none): ScrollVert's Up and
             * Down and ScrollHoriz's Up sound either way, each only when the
             * list or the mailbox moved; Back's; Square's dialog with
             * Accept's; reading one, none (beta issue 181) */
            int at=sms_sel,was=sms_box;
            if((pressed&PSP_CTRL_UP) && sms_sel>0)sms_sel--;
            if((pressed&PSP_CTRL_DOWN) && sms_sel<sms_n-1)sms_sel++;
            if((pressed&PSP_CTRL_LTRIGGER) && sms_box>SMS_BOX_INBOX)sms_box--;
            if((pressed&PSP_CTRL_RTRIGGER) && sms_box<SMS_BOX_UNLOCKS)sms_box++;
            if(sms_sel<at || sms_box!=was)menu_sound(PSP_CTRL_UP);else if(sms_sel>at)menu_sound(PSP_CTRL_DOWN);
            if(sms_box!=was){sms_sel=0;sms_list_build();}
            if((pressed&PSP_CTRL_CROSS) && sms_n){sms_reading=1;sms_scroll=0;career_sms_read(sms_list[sms_sel]);}
            else if((pressed&PSP_CTRL_SQUARE) && sms_n){sms_delete_ask=1;sms_delete_yes=0;menu_sound(PSP_CTRL_CROSS);}   /* No in focus (DialogInterface::ShowTwoButtons) */
            else if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE)){menu=MENU_OFF;career_save("career.sav");menu_sound(PSP_CTRL_TRIANGLE);}
            else if(pressed&(PSP_CTRL_SELECT|PSP_CTRL_START)){menu=MENU_OFF;career_save("career.sav");}
        /* SMSMessageViewer: the text's scroll silent (CTextScroller), Back
         * to the mailboxes silent, Accept back to the street with Back's
         * sound */
        } else if(pressed&PSP_CTRL_UP){sms_scroll=sms_text_scroll(sms_scroll,sms_lines,-1);}
        else if(pressed&PSP_CTRL_DOWN){sms_scroll=sms_text_scroll(sms_scroll,sms_lines,1);}
        else if(pressed&PSP_CTRL_TRIANGLE){sms_reading=0;sms_fresh=1;sms_list_build();}   /* Go to Mailboxes */
        else if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_CROSS)){sms_reading=0;menu=MENU_OFF;career_save("career.sav");menu_sound(PSP_CTRL_TRIANGLE);}   /* Return to Gameplay */
        return 1;
    }
    if(menu==MENU_ENGAGE) {
        if(pressed&PSP_CTRL_LEFT)engage_choice=0;else if(pressed&PSP_CTRL_RIGHT)engage_choice=1;   /* UIMSG_GO_LEFT/RIGHT: Accept/Decline, no wrap; Up/Down nothing (beta issue 179) */
        if((pressed&PSP_CTRL_CROSS) && !engage_choice){const CareerEvent *ce=career_event(engage_ev);int i=race_index_of(ce->id);menu=MENU_OFF;
            if(i>=0){char w[8],sn[4];snprintf(w,sizeof w,"%d",ce->id);snprintf(sn,sizeof sn,"%d",ce->stage);
                     if(movie_queue("pre",w,sn,0))movies_play();   /* its movie before, every time (RaceEngageDialog::AcceptRace) */
                     gps_off();if(!race_start(i))return 1;career_pace();trax_play(trax_next[1],1);}}   /* a race, a new song */
        else if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE|PSP_CTRL_CROSS)) {
            if(engage_speech){engage_speech=0;audio_speech_cancel();}
            if(engage_from_map)menu=MENU_MAP;
            else {engage_declined=engage_ev;menu=MENU_OFF;}   /* a new Up edge may ask again */
        }
        return 1;
    }
    if(menu==MENU_MAIN && pause_s) {
        int n;const PauseItem *it=pause_items(&n);
        if(menu_sel>=n)menu_sel=n-1;
        if(pause_ask) {   /* OK / Cancel (Cancel in focus): Triangle or O back to the pause */
            if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT))pause_ok=!pause_ok;
            if(pressed&(PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE)){pause_ask=0;return 1;}
            if(!(pressed&PSP_CTRL_CROSS))return 1;
            int act=pause_ask-1;
            if(!pause_ok){pause_ask=0;return 1;}
            switch(act) {
            case P_RESTART:race_restart();break;
            case P_QUIT:race_leave();break;
            case P_FRONT:   /* PauseMenu::QuitToCrib: NotifyEnterCribFromPauseMenu keeps the car's place, the garage's menu in its room */
                spawn_here(-1);crib_room=1;career_save("career.sav");   /* its Resume Career: the free roam from that place */
                front_request=FRONT_CRIB;return 1;   /* return_to_front owns the pending pause until retirement */
            case P_QUIT_TUNE:dyno_test_back(-1);return 1;   /* DoQuitTuning: back where the dyno was entered */
            case P_MAIN:   /* PauseMenu::QuitGame: from the free roam its place kept (NotifyExitToMainMenuFromFreeRoamOrRace), from a race the engaged one stays */
                if(career_count() && !race.quick){if(race.state==RACE_OFF)spawn_here(-1);career_save("career.sav");}   /* the place written with the career (the main menu's Resume Career starts there) */
                if(race.state!=RACE_OFF)race_end();if(!admission_failed){gps_off();front_request=FRONT_MAIN;}break;
            }
            if(admission_failed)return 1;   /* keep the pause and its confirmation on refused retirement */
            pause_ask=0;menu=MENU_OFF;
            return 1;
        }
        if((pressed&(PSP_CTRL_LEFT|PSP_CTRL_UP)) && menu_sel>0)menu_sel--;   /* no wrapping, as the PS2's */
        if((pressed&(PSP_CTRL_RIGHT|PSP_CTRL_DOWN)) && menu_sel<n-1)menu_sel++;
        if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE|PSP_CTRL_START)){menu=MENU_OFF;return 1;}
        if(pressed&PSP_CTRL_CROSS) {
            int act=it[menu_sel].action;const char *l2;
            if(pause_question(act,&l2)){pause_ask=act+1;pause_ok=0;return 1;}
            if(act==P_REPLAY){if(pause_replay_ok()){menu=MENU_OFF;pause_from_replay=1;replay_start();}return 1;}   /* none recorded yet: nothing */
            menu=MENU_OFF;
            switch(act) {
            case P_MAP:igmap_open();break;
            case P_OPTIONS:opts_open();break;
            case P_DYNO:dyno_test_back(DP_MAIN);break;   /* ReturnToShop: the dyno's menu */
            case P_TUNE:dyno_test_back(DP_TUNE);break;   /* StartTuning: the tuning */
            }
        }
        return 1;
    }
    /* the debug menus, without the pause screen */
    int n=menu_items();
    if(pressed&PSP_CTRL_UP)menu_sel=(menu_sel+n-1)%n;
    if(pressed&PSP_CTRL_DOWN)menu_sel=(menu_sel+1)%n;
    if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE|PSP_CTRL_START)){menu=menu==MENU_RACES && !pause_s?MENU_MAIN:MENU_OFF;menu_sel=0;return 1;}
    if(pressed&PSP_CTRL_CROSS) {
        if(menu==MENU_RACES){int i=menu_race_index(menu_sel);if(i>=0 && menu_race_open(menu_sel) && !(career_count() && challenge_on())){if(career_count())career_engage(menu_sel,NULL);if(!race_start(i))return 1;career_pace();trax_play(trax_next[1],1);menu=MENU_OFF;}}   /* locked: stays */
        else if(race.state!=RACE_OFF) {
            if(menu_sel==1)reposition_on_course();
            if(menu_sel==2)race_leave();
            menu=MENU_OFF;
        } else {
            if(menu_sel==0)menu=MENU_OFF;
            else if(menu_sel==1){if(menu_race_count()){menu=MENU_RACES;menu_sel=0;}}
            else if(menu_sel==2){car_respawn();menu=MENU_OFF;}
            else if(menu_sel==3){audio_music_next();menu=MENU_OFF;}
            else {front_request=FRONT_MAIN;menu=MENU_OFF;}
        }
    }
    return 1;
}
static void menu_draw(void) {
    if(menu==MENU_OFF || (menu==MENU_MAIN && pause_s) || menu==MENU_MAP || menu==MENU_IGMAP || menu==MENU_SHOP || menu==MENU_STATUS || menu==MENU_OPTS || menu==MENU_AUDIO || menu==MENU_ENGAGE || menu==MENU_SPONSOR || menu==MENU_SMS || menu==MENU_TIP || menu==MENU_SHOWGO)return;
    hud_back_color(0xff201810);
    if(menu==MENU_MAIN) {
        const char **items=race.state==RACE_OFF?menu_free:menu_race;int n=menu_items();
        hud_text_color(0xffffd590);hud_xy(24,10);hud_printf("  PAUSE  ");
        for(int i=0;i<n;i++) {
            hud_text_color(i==menu_sel?0xff40ffff:0xffe0e0e0);
            hud_xy(20,12+i*2);hud_printf("%s %-26s",i==menu_sel?">":" ",items[i]);
        }
        return;
    }
    int n=menu_race_count(),first=menu_sel-6<0?0:menu_sel-6;if(first>n-13&&n>13)first=n-13;if(n<=13)first=0;
    const CareerState *cs=career_state();int open=0,done=0;
    for(int k=0;k<career_count();k++){open+=cs->open[k];done+=cs->best[k]!=0;}
    hud_text_color(0xffffd590);hud_xy(6,3);
    if(career_count())hud_printf("  CAREER  $%-7u REP %-6u  %d/%d done  %d open  ",cs->money,cs->rep,done,n,open);
    hud_xy(6,4);hud_printf("  RACES (%d)  X race  O back  ",n);
    for(int k=first;k<n && k<first+13;k++) {
        int i=menu_race_index(k);if(i<0)continue;
        const RaceEvent *e=race_event(i);const CareerEvent *ce=career_event(k);
        int lock=!menu_race_open(k);
        hud_text_color(lock?(k==menu_sel?0xff707070:0xff505050):k==menu_sel?0xff40ffff:cs->best[k]?0xff80ff80:0xffe0e0e0);
        hud_xy(6,6+(k-first)*2);
        int laps=e->circuit?(ce && ce->laps?ce->laps:2):1;
        if(!ce)hud_printf("%s %4d  %-9s %5.1f km",k==menu_sel?">":" ",e->id,e->circuit?"Circuit":"Sprint",e->length/1000.f);
        else if(lock)hud_printf("%s %4d  %-9s %5.1f km   BLOQUEADA        ",k==menu_sel?">":" ",e->id,career_type_names[ce->type<6?ce->type:0],e->length/1000.f);
        else hud_printf("%s %4d  %-9s %5.1f km %dv $%-6d %s",k==menu_sel?">":" ",e->id,career_type_names[ce->type<6?ce->type:0],e->length/1000.f,laps,ce->money,
                                 cs->best[k]?(cs->best[k]==1?"1o lugar":cs->best[k]==2?"2o lugar":cs->best[k]==3?"3o lugar":"4o lugar"):"nova    ");
    }
}
static void race_hud(void) {
    if(race.state==RACE_OFF)return;
    const RaceEvent *e=race_event(race.event);
    hud_back_color(0x00000000);
    int pos=0;for(int k=0;k<race.nr;k++)if(race.place[k]==0)pos=k+1;
    int m=(int)(race.clock/60),sec=(int)race.clock%60,cs=(int)(race.clock*100)%100;
    hud_text_color(0xff40ffff);
    if(!fehud_ok) {
        hud_xy(1,3);hud_printf("POS %d/%d  ",pos?pos:race.nr,race.nr);
        if(e->circuit)hud_printf("LAP %d/%d  ",race.r[0].lap<1?1:race.r[0].lap+1>race.laps?race.laps:race.r[0].lap+1,race.laps);
        else hud_printf("%4.1f km  ",fmaxf(0,(e->length-race.r[0].progress)/1000.f));
        hud_printf("%02d:%02d.%02d ",m,sec,cs);
    }
    if(race.state==RACE_COUNTDOWN && !fehud_ok) {
        int n=(int)ceilf(race.countdown-.5f);
        hud_text_color(0xff40ffff);hud_xy(28,14);
        if(n>0)hud_printf("  %d  ",n);else hud_printf(" GO! ");
    }
    if(results_up() && !results_s) {
        hud_back_color(0xff201810);hud_text_color(0xffffd590);
        hud_xy(18,9);hud_printf("  RESULT - %s %d  ",e->circuit?"Circuit":"Sprint",e->id);
        for(int k=0;k<race.nr;k++) {
            const Racer *r=&race.r[race.place[k]];int me=race.place[k]==0;
            hud_text_color(me?0xff40ffff:0xffe0e0e0);hud_xy(18,11+k*2);
            const char *who=me?"You":opp_pool[r->model].label;
            if(r->finished)hud_printf(" %d. %-14s %02d:%05.2f ",k+1,who,(int)(r->time/60),fmodf(r->time,60));
            else hud_printf(" %d. %-14s   --:--   ",k+1,who);
        }
        if(race.rewarded) {
            const CareerReward *rw=&race.reward;const CareerState *cs=career_state();
            hud_text_color(0xff80ff80);hud_xy(18,20);
            hud_printf(" Prize: $%d  +%d REP          ",rw->money,rw->rep);
            hud_text_color(0xffe0e0e0);hud_xy(18,21);
            hud_printf(" Career: $%u  REP %u         ",cs->money,cs->rep);
            for(int j=0;j<rw->nopened;j++){hud_text_color(0xff40ffff);hud_xy(18,22+j);hud_printf(" Unlocked: race %d     ",rw->opened[j]);}
        }
        hud_text_color(0xffe0e0e0);hud_xy(18,25);hud_printf("  X: back to free roam  ");
    }
}

/* An eligible event marker offers Up, not an automatic dialog. These
 * legacy distance/speed gates are separate from the interaction button. */
static int engage_k=-1;
static float engage_gate;   /* m/s, 0 none (the original's); v0.2.5's 3 m/s only for the A/B of script 15 (yaw 4.3, 5.3) */
static void career_engage_update(void) {
    engage_k=-1;
    if(race.state!=RACE_OFF || !career_count() || (engage_gate>0 && fabsf(speed_of(&car))>engage_gate))return;   /* at any speed, as the original's (Player::UpdateCurrentTrackPathZone: the zone the car is in, every frame) */
    if(challenge_on()){challenge_blocked++;return;}   /* a world challenge on: IsEnterable only for its goal */
    float best=8.f*8.f;
    for(int k=0;k<career_count();k++) {
        /* the races on offer, a hidden one too: driving into it finds it (career_engage) */
        int i=race_index_of(career_event(k)->id);if(i<0 || (career_event(k)->flags&CAREER_LATER) || !career_state()->open[k])continue;
        if(!career_shown(k) && career_record(k) && career_record(k)->suv)continue;   /* an SUV race wants an SUV */
        const float *p=career_marker(k);float dx=p[0]-car.x,dz=p[2]-car.z,d=dx*dx+dz*dz;
        if(d<best && fabsf(p[1]-car.ground)<4.f){best=d;engage_k=k;}
    }
}

/* The magazine's cover (magazines.n2mg, tools/convert_magazines.py): the
 * photo shoot's reward, as the original shows it after the session; six
 * seconds, X, O or START close it. Each shoot's magazine is the game's
 * (career.n2cr, its cover's setup): a shoot on location (the game's
 * cameras, MAGAZINES_SHOWCASE.BIN) has the photo taken, the street from
 * the session's camera, under its masthead; a studio cover
 * (MAGAZINES_FRONTEND.BIN) the magazine's background, the player's car
 * posed in front of it, then its girl, masthead and headlines over them
 * (of each layer the game draws one of its choices at random, the port
 * takes the first). The layers (256x256, 8-bit with an RGBA palette, the
 * cover in their top left 168 x 220) are read for the cover alone and
 * freed after it. */
enum { COVER_LAYERS=4, COVER_IMG=256*256+1024 };
static struct { int on,n,preview,shoot,cam,declined,opt,show,control;float t,bounce,x0,z0;uint8_t *img[COVER_LAYERS],kind[COVER_LAYERS];FeScreen *s; } cover={.shoot=-1,.declined=-1};
static int covers_shown,shows_taken,show_offs,show_cash;
/* The player's level this frame (draw_car), by the eye's distance to the car
 * (car_transform's eye_obj); the magazine cover's posed car keeps its own. */
static void player_pick(void) {
    player_level=-1;player_px=1e9f;
    if(!car_lods || cover.on)return;
    player_px=3.f*356.f/sqrtf(fmaxf(eye_obj.x*eye_obj.x+eye_obj.y*eye_obj.y+eye_obj.z*eye_obj.z,1e-4f));
    int l=model.nlod?car_level(&model,player_px,0,model.lod_base):0;
    if(model.nlod && l>model.lod_base)player_level=l;
}
