static void cover_open(int shoot) {
    cover_close();
    FILE *f=fopen("magazines.n2mg","rb");if(!f)return;
    char magic[4];uint32_t ver,n;
    if(fread(magic,1,4,f)!=4 || memcmp(magic,"N2MG",4) || fread(&ver,4,1,f)!=1 || ver!=1 || fread(&n,4,1,f)!=1 || !n || n>64){fclose(f);return;}
    const CareerShow *v=career_show(shoot);
    uint32_t want=(uint32_t)shoot%n;   /* the magazine by its name, else by the shoot's order */
    if(v && v->magazine[0]) {
        long at=ftell(f);
        for(uint32_t m=0;m<n;m++) {
            uint8_t head[12];if(fread(head,1,12,f)!=12)break;
            if(!strncmp((const char *)head,v->magazine,7)){want=m;break;}
            if(fseek(f,8L*head[8],SEEK_CUR))break;
        }
        fseek(f,at,SEEK_SET);
    }
    uint8_t kinds[64];uint32_t offs[64];int ne=0;   /* the magazine's layers: of each kind, one by the shoot (the game draws one, 0x11ced0) */
    for(uint32_t m=0;m<=want;m++) {
        uint8_t head[12];if(fread(head,1,12,f)!=12){fclose(f);return;}
        int nl=head[8];
        for(int k=0;k<nl;k++) {
            uint8_t e[8];if(fread(e,1,8,f)!=8){fclose(f);return;}
            if(m==want && ne<64){kinds[ne]=e[0];memcpy(&offs[ne],e+4,4);ne++;}
        }
    }
    for(int kind=0;kind<COVER_LAYERS;kind++) {
        int of=0,at=-1;for(int i=0;i<ne;i++)of+=kinds[i]==kind;
        if(!of)continue;
        int pick=(shoot+kind)%of;for(int i=0;i<ne;i++)if(kinds[i]==kind && pick--==0)at=i;
        uint8_t *img=at>=0?memalign(16,COVER_IMG):NULL;if(!img)continue;
        if(fseek(f,(long)offs[at],SEEK_SET)==0 && fread(img,1,COVER_IMG,f)==COVER_IMG){cover.img[cover.n]=img;cover.kind[cover.n++]=(uint8_t)kind;}
        else free(img);
    }
    fclose(f);
    if(!cover.n)return;
    sceKernelDcacheWritebackAll();
    cover.on=1;cover.t=0;covers_shown++;
}
/* The shoot's cameras (Cycle Cameras). On location, the game's three
 * (MAGAZINES_SHOWCASE.BIN; Xbox default.xbe 0x54dcc): the point looked at
 * ahead, to the left and up of the car (its heading, level), the eye
 * around it from its front, at least 3 degrees up (the distance's
 * horizontal part not shortened: the game's), the lens the 4:3 screen's
 * width; the game draws one at random, the port goes through them in
 * turn. A studio cover's: in front of the car a little to its side, low
 * (the cover's), the other side, its back, its side. */
static const CareerShow *cover_shoot_cams(void) { const CareerShow *v=career_show(cover.shoot);return v && v->cam[0][2]>0?v:NULL; }
static int cover_cams(void) { return cover_shoot_cams()?3:4; }
static const CareerShow *cover_studio(void) { const CareerShow *v=career_show(cover.shoot);return v && !cover_shoot_cams() && v->studio[2]>0?v:NULL; }
static void cover_camera(void) {
    const CareerShow *v=cover_shoot_cams(),*s=cover_studio();
    if(s && !cover.preview) {   /* a studio cover: the game's pose, the studio's turntable turned into the car's heading */
        const float *p=s->studio,d2r=3.14159265f/180.f,ca=cosf(p[0]*d2r),sa=sinf(p[0]*d2r);
        float fx=sinf(car.yaw),fz=cosf(car.yaw),lx=cosf(car.yaw),lz=-sinf(car.yaw),e[3],t[3];
        for(int k=0;k<2;k++) {
            const float *q=p+3+3*k;float a=q[0]*ca+q[1]*sa,b=-q[0]*sa+q[1]*ca,*o=k?t:e;   /* ahead and to the left of the car */
            o[0]=car.x+a*fx+b*lx;o[1]=car.ground+q[2];o[2]=car.z+a*fz+b*lz;
        }
        look_camera(e,t,2.f*atanf(tanf(p[2]*d2r*.5f)*.75f)/d2r);
        if(p[9]!=0) {   /* its roll */
            ScePspFMatrix4 m;sceGumMatrixMode(GU_VIEW);sceGumStoreMatrix(&m);sceGumLoadIdentity();sceGumRotateZ(p[9]*d2r);sceGumMultMatrix(&m);sceGumMatrixMode(GU_MODEL);
        }
        return;
    }
    if(v) {
        const float *c=v->cam[cover.cam%3],d2r=3.14159265f/180.f;
        float fx=sinf(car.yaw),fz=cosf(car.yaw),lx=cosf(car.yaw),lz=-sinf(car.yaw);   /* ahead, to the left */
        float t[3]={car.x+c[3]*fx+c[4]*lx,car.ground+.5f+c[5],car.z+c[3]*fz+c[4]*lz};   /* (the game's car at its centre, ~0.5 m up) */
        float az=c[0]*d2r,el=fmaxf(c[1],3.f)*d2r;
        float e[3]={t[0]+c[2]*(cosf(az)*fx+sinf(az)*lx),t[1]+c[2]*sinf(el),t[2]+c[2]*(cosf(az)*fz+sinf(az)*lz)};
        look_camera(e,t,2.f*atanf(tanf(c[6]*d2r*.5f)*.75f)/d2r);
        return;
    }
    static const float turn[4]={.65f,-.65f,2.6f,1.57f},dist[4]={8.5f,8.5f,8.f,7.5f},high[4]={1.3f,1.3f,1.6f,1.1f};
    int c=cover.preview?cover.cam&3:0;
    float a=car.yaw+turn[c],d=dist[c];
    float e[3]={car.x+sinf(a)*d,car.ground+high[c],car.z+cosf(a)*d},t[3]={car.x,car.ground+1.55f,car.z};
    look_camera(e,t,cover.preview?45.f:38.f);
}
/* The session (UI_ShowCase_Preview.fng, showcase.n2ui): stopped at an open
 * photo shoot, the viewfinder over the street, the car posed. Its four
 * options (bottom to top), Up/Down and X: Take Picture (the shoot done, its cover), Cycle
 * Cameras (also Left/Right or Square), Show Off (the doors, the hood and
 * the lid open, the hydraulics hop) and Control Car (the car driven, slow,
 * to place it; Triangle or Up back to the options). O leaves it (the shoot
 * still open: the car has to leave its place before it asks again). */
enum { COVER_PICTURE, COVER_CAMERAS, COVER_SHOWOFF, COVER_CONTROL, COVER_OPTS };
static void cover_options(void) {   /* the option's text, highlight and backing (the package's, by their places): its HIGHLIGHT, the others' UNHIGHLIGHT */
    if(!cover.s)return;
    for(int i=0;i<COVER_OPTS;i++) {
        uint32_t sc=i==cover.opt?FE_SCRIPT_HIGHLIGHT:FE_SCRIPT_UNHIGHLIGHT;
        fe_play(cover.s,fe_find(cover.s,0x95ad094cu-(uint32_t)i),sc);
        fe_play(cover.s,fe_find_nth(cover.s,0xc2ea8deau-(uint32_t)i,0),sc);   /* (the first: a second group has the first's name) */
        fe_play(cover.s,fe_find(cover.s,0xf9f1f5d0u-(uint32_t)i),sc);
    }
}
static void cover_preview(int shoot) {
    cover_close();
    cover.s=fe_load("showcase.n2ui");
    if(cover.s) {
        fe_show(cover.s,1,1);
        static const uint32_t hide[]={0x609ff3e9u,0x609ff3eau,0xd0e625f3u,0xd0e625f4u};   /* the package's three Backs: one */
        for(unsigned k=0;k<sizeof hide/sizeof *hide;k++)for(int n=0,o;(o=fe_find_nth(cover.s,hide[k],n))>=0;n++)fe_alpha(cover.s,o,0);
    }
    cover.on=1;cover.preview=1;cover.shoot=shoot;cover.cam=0;cover.t=0;cover.opt=COVER_PICTURE;cover.x0=car.x;cover.z0=car.z;
    cover_options();
}
/* a layer over the cover's place: the screen's middle, its full height */
static void cover_sprite(const uint8_t *img) {
    typedef struct { float u,v;float x,y,z; } V;
    V *v=sceGuGetMemory(2*sizeof(V));
    const float w=168.f*272.f/220.f,x0=(480.f-w)*.5f;
    v[0]=(V){0,0,x0,0,0};v[1]=(V){168,220,x0+w,272,0};
    sceGuClutMode(GU_PSM_8888,0,0xff,0);sceGuClutLoad(256/8,img+256*256);
    sceGuTexMode(GU_PSM_T8,0,0,0);sceGuTexImage(0,256,256,256,img);sceGuTexFunc(GU_TFX_REPLACE,GU_TCC_RGBA);
    sceGuTexFilter(GU_LINEAR,GU_LINEAR);sceGuTexWrap(GU_CLAMP,GU_CLAMP);sceGuTexScale(1,1);sceGuTexOffset(0,0);sceGuTexFlush();
    sceGuDrawArray(GU_SPRITES,GU_TEXTURE_32BITF|GU_VERTEX_32BITF|GU_TRANSFORM_2D,2,0,v);
}
static void draw_cover(void) {
    sceGuDisable(GU_DEPTH_TEST);sceGuDisable(GU_LIGHTING);sceGuDisable(GU_FOG);sceGuEnable(GU_TEXTURE_2D);
    sceGuEnable(GU_BLEND);sceGuBlendFunc(GU_ADD,GU_SRC_ALPHA,GU_ONE_MINUS_SRC_ALPHA,0,0);
    for(int k=0;k<cover.n;k++)if(cover.kind[k]==0)cover_sprite(cover.img[k]);   /* the background */
    sceGuClear(GU_DEPTH_BUFFER_BIT);sceGuEnable(GU_DEPTH_TEST);
    car_transform();wheels_of(&model,&car);
    if(cover_studio())wheel_steer=-cover_studio()->studio[1]*3.14159265f/180.f;   /* the pose's front wheels (the showroom's sign: MENU_STEER) */
    draw_car();wheels_of(NULL,NULL);   /* the car, posed (cover_camera) */
    sceGumMatrixMode(GU_MODEL);sceGumLoadIdentity();
    sceGuDisable(GU_DEPTH_TEST);sceGuDisable(GU_LIGHTING);sceGuEnable(GU_TEXTURE_2D);sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD,GU_SRC_ALPHA,GU_ONE_MINUS_SRC_ALPHA,0,0);
    static const uint8_t order[3]={2,1,3};   /* the girl, the masthead, the headlines */
    for(int o=0;o<3;o++)for(int k=0;k<cover.n;k++)if(cover.kind[k]==order[o])cover_sprite(cover.img[k]);
    sceGuDisable(GU_BLEND);sceGuEnable(GU_DEPTH_TEST);sceGuTexFunc(GU_TFX_MODULATE,GU_TCC_RGBA);
}
/* a photo shoot's cover: the masthead over the street drawn, the page's
 * edges dark (the cover's place: the screen's middle, its full height) */
static void ui_rect(float x,float y,float w,float h,uint32_t abgr);
static void draw_cover_photo(void) {
    const float w=168.f*272.f/220.f,x0=(480.f-w)*.5f;
    ui_rect(0,0,(int)x0,272,0xff000000);ui_rect((int)(x0+w),0,480-(int)(x0+w),272,0xff000000);
    sceGuDisable(GU_DEPTH_TEST);sceGuDisable(GU_LIGHTING);sceGuDisable(GU_FOG);sceGuEnable(GU_TEXTURE_2D);
    sceGuEnable(GU_BLEND);sceGuBlendFunc(GU_ADD,GU_SRC_ALPHA,GU_ONE_MINUS_SRC_ALPHA,0,0);
    sceGumMatrixMode(GU_MODEL);sceGumLoadIdentity();
    for(int k=0;k<cover.n;k++)if(cover.kind[k]==1)cover_sprite(cover.img[k]);
    sceGuDisable(GU_BLEND);sceGuEnable(GU_DEPTH_TEST);sceGuTexFunc(GU_TFX_MODULATE,GU_TCC_RGBA);
}
/* the cover's time: paused under it; closed after six seconds or a press */
static void cover_open(int shoot);
static int cover_step(uint32_t pressed,float elapsed) {
    cover.t+=fminf(elapsed,.1f);
    if(cover.preview) {   /* the session */
        float dt=fminf(elapsed,.1f);
        for(int k=0;k<4;k++){float want=cover.show?1.f:0.f;piece_open[k]+=(want-piece_open[k])*(1.f-expf(-dt*4.f));}   /* Show Off's doors and lids */
        door_style=player_look.doors;hood_split=look_hood_split(&player_look);
        if(cover.show && player_look.hydraulics && (cover.bounce-=dt)<=0){cover.bounce=1.4f;hydro.vh+=.6f+.4f*player_look.hydraulics;}   /* and the hops */
        if(cover.control) {   /* Control Car: driven (not paused), back to the options */
            float dx=car.x-cover.x0,dz=car.z-cover.z0;control_m=fmaxf(control_m,sqrtf(dx*dx+dz*dz));
            if(pressed&(PSP_CTRL_TRIANGLE|PSP_CTRL_UP|PSP_CTRL_START) || dx*dx+dz*dz>25.f*25.f)cover.control=0;   /* not far from the shoot */
            return !cover.control;
        }
        if(pressed&PSP_CTRL_UP){cover.opt=(cover.opt+1)%COVER_OPTS;cover_options();}   /* Take Picture at the bottom, Control Car at the top */
        if(pressed&PSP_CTRL_DOWN){cover.opt=(cover.opt+COVER_OPTS-1)%COVER_OPTS;cover_options();}
        if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_SQUARE))cover.cam=(cover.cam+1)%cover_cams();
        if(pressed&PSP_CTRL_RIGHT)cover.cam=(cover.cam+cover_cams()-1)%cover_cams();
        if(pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE)){cover.declined=cover.shoot;cover_close();}
        else if((pressed&PSP_CTRL_CROSS) && cover.opt==COVER_CAMERAS)cover.cam=(cover.cam+1)%cover_cams();
        else if((pressed&PSP_CTRL_CROSS) && cover.opt==COVER_SHOWOFF){cover.show=!cover.show;cover.bounce=0;show_offs+=cover.show;}
        else if((pressed&PSP_CTRL_CROSS) && cover.opt==COVER_CONTROL)cover.control=1;
        else if((pressed&PSP_CTRL_CROSS) && cover.t>.3f) {   /* Take Picture: the shoot done, its cover */
            int i=cover.shoot;career_set_rating(look_rating(&career_state()->look));CareerReward r=career_show_take(i,"career.sav");
            /* the photo's cash (500 + the stars x 100), as the original's Cash_Reward */
            if(r.cover){shows_taken++;char m[40];snprintf(m,sizeof m,"%s  +$%d",r.cover==2?"DVD Cover!":"Magazine Cover!",r.money);race_say(m);show_cash+=r.money;if(r.cover_speech)say_later(1.f,0,"Career_Magazine",0,9,r.cover_speech-1,0);cover_open(i);}
            else cover_close();
        }
        return 1;
    }
    if(cover.t>6.f || (cover.t>.5f && (pressed&(PSP_CTRL_CROSS|PSP_CTRL_CIRCLE|PSP_CTRL_START))))cover_close();
    return 1;
}
/* The photo shoots (career_show_*, the game's showcases), as the game
 * leads to them (Xbox default.xbe 0x13f620, 0x121820, 0x1219b0): at an open
 * one's start (TRIGGER_START_*, within 10 m, the free roam) Rachel's text,
 * UI_EngageEventDialog ("You've got 02:00:00 to get to his location", one
 * of the showcase's texts at random); accepted, its countdown (the
 * showcase's +16, 45 to 200 s) to its place, the GPS there: a magazine's,
 * the photographer's (its cover's marker, STAGE_n_SHOW_k_PICTURE); a unique
 * part's, its shop. There in time, a photo shoot's prompt (Up: its session,
 * cover_step: the cover counts for the stage, Rachel says its line) or the
 * part picked up; late, or the car gone from the place, it waits at its
 * start again. */
static void showgo_open(int i) {
    const CareerShow *v=career_show(i);
    if(!v->time){showgo.show=i;showgo.state=SG_THERE;return;}   /* a DVD cover's star: the session there, no countdown */
    if(!showgo.s){showgo.s=fe_load("showgo.n2ui");if(showgo.s){fe_show(showgo.s,1,1);fe_widen(showgo.s,480.f/640.f);}ui_open=NULL;}
    showgo.show=i;showgo.choice=0;showgo.say=v->says?rand()%v->says:0;
    if(!showgo.s){showgo.state=SG_THERE;return;}   /* (without the dialog: there already) */
    showgo.state=SG_ASK;menu=MENU_SHOWGO;
}
static void showgo_time(char *b,size_t n,float t) {   /* the game's clock (0x180b40): minutes, seconds, hundredths */
    int c=(int)fmaxf(0,t*100.f);snprintf(b,n,"%02d:%02d:%02d",c/6000,c/100%60,c%100);
}
static void showgo_draw(float dt) {
    FeScreen *s=showgo.s;const CareerShow *v=career_show(showgo.show);if(!v)return;
    static FeScreen *ready;char t[16],b[256];
    if(ready!=s) {
        fe_alpha(s,fe_find(s,0xde075b62u),0);fe_alpha(s,fe_find(s,0xb8a7c6ceu),0);fe_alpha(s,fe_find(s,0xb1000cc8u),0);fe_alpha(s,fe_find(s,0x47ff4e7cu),0);   /* the text drawn below; the single Yes and its backing (EventEngageDialog::Setup shows them for one button only: a third bar between Accept and Decline, beta issues 119/124), the debug label */
        ready=s;
    }
    lang_format(b,sizeof b,"From: %s","Rachel");fe_text(s,fe_find(s,0xfeced617u),b);
    fe_text(s,fe_find(s,0x2c167533u),career_text(v->subject));   /* (fe_text: in the PSP's language) */
    fe_button_focus(s,fe_find(s,0xd72f002au),fe_find(s,0x949f4947u),!showgo.choice);   /* Accept */
    fe_button_focus(s,fe_find(s,0x63857de0u),fe_find(s,0x949f4948u),showgo.choice);   /* Decline */
    fe_update(s,dt);fe_draw(s);
    showgo_time(t,sizeof t,v->time);
    const char *say=v->says?lang_en(career_text(v->say[showgo.say])):"%s",*at=strstr(say,"%s");
    if(at)snprintf(b,sizeof b,"%.*s%s%s",(int)(at-say),say,t,at+2);else snprintf(b,sizeof b,"%s",say);
    float x,y,sc;fe_place(s,fe_find(s,0x2c167533u),&x,&y,&sc);
    wrap_left(s,0,x,y+26.f,2.f*(240.f-x)-24.f,.4f,13.f,0xffe0e0e0,b,9);
}
static void shows_update(int paused,float dt) {
    int at=-1,start=-1;
    if(paused || race.state!=RACE_OFF || world_level || !career_count() || cover.on){show_prompt=show_start=-1;return;}
    if(showgo.state==SG_GO || showgo.state==SG_THERE) {
        int i=showgo.show;const CareerShow *v=career_show(i);
        if(!v || !career_show_open(i)){showgo.state=SG_OFF;show_prompt=show_start=-1;return;}
        float dx=v->to_x-car.x,dz=v->to_z-car.z,d2=dx*dx+dz*dz;
        if(v->time==0){dx=v->x-car.x;dz=v->z-car.z;d2=dx*dx+dz*dz;}
        if(showgo.state==SG_GO) {
            if(d2<10.f*10.f){showgo.state=SG_THERE;showgo.arrived++;gps_off();}   /* NotifyEnterShowcase: the clock stops (state 3) */
            else if((showgo.left-=dt)<=0){showgo.state=SG_OFF;showgo.late++;gps_off();race_say("Time's Up");show_prompt=show_start=-1;return;}
        }
        if(showgo.state==SG_THERE) {
            if(d2>40.f*40.f) {   /* away from the place */
                if(cover.declined==i)cover.declined=-1;
                if(!v->time){showgo.state=SG_OFF;show_prompt=show_start=-1;return;}   /* a DVD cover's star: at its place again */
                showgo.away++;   /* a world challenge's goal reached stays its goal, the clock stopped, till its photo (NotifyExitZone does nothing) */
            } else if(v->kind==SHOW_UNIQUE) {   /* a unique part's: picked up as the car arrives */
                career_show_take(i,"career.sav");showgo.state=SG_OFF;
                shows_taken++;race_say(v->perf?"Unique Parts: Performance Shop":"Unique Parts: Body Shop");
            } else if(cover.declined!=i)at=i;   /* a photo shoot: its prompt (Up: its session, cover_step) */
        }
    } else if(menu==MENU_OFF) {
        for(int i=0;i<career_show_count();i++) {   /* at an open one's place */
            if(!career_show_open(i))continue;
            const CareerShow *v=career_show(i);float dx=v->x-car.x,dz=v->z-car.z;
            if(dx*dx+dz*dz>10.f*10.f){if(showgo.declined==i)showgo.declined=-1;continue;}
            if(!v->time){if(showgo.declined!=i)showgo_open(i);}   /* a DVD cover's star is the showcase's own place: its session on Up */
            else if(fabsf(speed_of(&car))<=3.f)start=i;   /* a world challenge's start: Up asks (stopped, as the races' and the shops') */
            break;
        }
    }
    if((at>=0 || start>=0) && !dpad_s){dpad_s=fe_load("showdpad.n2ui");if(dpad_s)fe_show(dpad_s,1,1);}
    show_prompt=at;show_start=start;
}
/* Discover shops independently of interacting with their original zones.
 * Return the eligible shop for the Up prompt, without opening a dialog. */
static const char *shop_kind_name(int k) {
    static const char *const n[]={"Car Lot","Performance Shop","Body Shop","Graphics Shop","Car Specialties","Garage"};
    return k>=0 && k<6?n[k]:"Shop";
}
static int career_load_status=-2;
static int on_card;
/* Diagnostic only, explicitly armed beside the host0 executable. Each
 * completed SDK write+close preserves a small checkpoint outside the UI.
 * This is not a power-loss durability guarantee or a performance sample. */
#ifndef HOST_SIM
static int profile_diag_enabled=-1;static unsigned profile_diag_seq;
static volatile int profile_diag_error;
static int profile_diag_player,profile_diag_model_refused;
#endif
static volatile unsigned freeze_phase;static volatile uint32_t freeze_phase_ms;   /* the last transition's phase and when (the freeze panel's) */
static void profile_transition_mark(unsigned phase,int result) {
#ifdef HOST_SIM
    (void)phase;(void)result;
#else
    freeze_phase=phase;freeze_phase_ms=(uint32_t)(sceKernelGetSystemTimeWide()/1000);   /* (the freeze panel's: kept in RAM only, on the card too) */
    if(on_card)return;   /* no diagnostic creation on the user's Memory Stick */
    if(phase==PD_PLAYER_BEGIN){profile_diag_player=1;profile_diag_model_refused=0;}
    else if(phase==PD_PLAYER_END)profile_diag_player=0;
    if(profile_diag_enabled<0) {
        profile_diag_enabled=0;
        SceUID fd=sceIoOpen("profile-diag.on",PSP_O_RDONLY,0);
        if(fd>=0){char flag[7]={0};int n=sceIoRead(fd,flag,sizeof flag),closed=sceIoClose(fd);
            profile_diag_enabled=n==6 && !memcmp(flag,"N2PD1\n",6) && closed>=0;}
    }
    if(!profile_diag_enabled || profile_diag_seq>=PROFILE_DIAG_LIMIT)return;
    struct mallinfo mi=mallinfo();const CareerState *cs=career_state();
    uint32_t h=2166136261u;const unsigned char *s=(const unsigned char *)model_load_stage;
    if(s)for(unsigned n=0;n<64 && s[n];n++){h^=s[n];h*=16777619u;}
    ProfileTransitionRecord r={{PROFILE_DIAG_MAGIC,PROFILE_DIAG_VERSION,profile_diag_seq+1,phase,(uint32_t)result,
        sceKernelGetSystemTimeLow(),cs->stage,(uint32_t)(int32_t)cs->car,(uint32_t)career_load_status,
        (uint32_t)mi.uordblks,(uint32_t)mi.fordblks,(uint32_t)mi.arena,
        sceKernelTotalFreeMemSize(),sceKernelMaxFreeMemSize(),model_requested,h}};
    int flags=PSP_O_WRONLY|(profile_diag_seq?PSP_O_APPEND:PSP_O_CREAT|PSP_O_EXCL);
    SceUID fd=sceIoOpen("profile-transition.bin",flags,0600);
    if(fd<0){profile_diag_error=fd;profile_diag_enabled=0;return;}
    int wrote=sceIoWrite(fd,&r,sizeof r),closed=sceIoClose(fd);
    if(wrote!=(int)sizeof r || closed<0){profile_diag_error=closed<0?closed:wrote<0?wrote:-EIO;profile_diag_enabled=0;return;}
    profile_diag_seq++;
#endif
}
/* Only after a refused read, while resolving the player's model. errno
 * is captured immediately after fread; without ferror it may be stale.
 * ftell is the stream's logical position, not a raw host driver offset. */
static void profile_model_read_refused(FILE *f,size_t got,int read_errno) {
#ifdef HOST_SIM
    (void)f;(void)got;(void)read_errno;
#else
    if(!profile_diag_player || profile_diag_enabled!=1 || on_card || profile_diag_model_refused)return;
    profile_diag_model_refused=1;   /* reserve the tail: the first refusal only */
    int flags=(ferror(f)?1:0)|(feof(f)?2:0);long position=ftell(f);
    profile_transition_mark(PD_MODEL_READ_GOT,(int)got);
    profile_transition_mark(PD_MODEL_READ_FLAGS,flags);
    profile_transition_mark(PD_MODEL_READ_ERRNO,read_errno);
    profile_transition_mark(PD_MODEL_READ_POSITION,(int)position);
    errno=read_errno;
#endif
}
static void profile_model_retry_mark(int done,int result) {
#ifdef HOST_SIM
    (void)done;(void)result;
#else
    if(!profile_diag_player || profile_diag_enabled!=1 || on_card)return;
    profile_transition_mark(done?PD_MODEL_RETRY_END:PD_MODEL_RETRY_BEGIN,result);
#endif
}
static int shop_declined=-1,shop_prompt=-1;
static int shops_update(int paused) {
    if(race.state!=RACE_OFF || world_level || !career_count() || shopnis_active())return -1;   /* a shop's scene drives the car by the shop */
    if(challenge_on()){shop_declined=-1;return -1;}   /* a world challenge on: no shop zone (nor its discovery) but its goal */
    int at=-1;
    for(int i=0;i<career_shop_count();i++) {
        const CareerShop *sh=career_shop(i);if(sh->stage>career_state()->stage)continue;
        float dx=sh->x-car.x,dz=sh->z-car.z,d=dx*dx+dz*dz;
        if(sh->hidden && !(career_state()->shops_seen>>i&1) && d<80.f*80.f) {
            int save_status=career_shop_found(i,"career.sav");
            if(save_status!=CAREER_SAVE_NONE){CareerSaveResult r=career_save_result();r.status=save_status;career_ui_save_report(r);}
            ui_seen.shops++;   /* (no message: NotifyShopDiscovered puts it on the minimap, the original shows nothing; beta issue 188) */
        }
        if(career_shop_visible(i) && shopzones_at_height(sh->name,car.x,car.ground,car.z,sh->y))at=i;
    }
    if(at<0)shop_declined=-1;
    if(paused || at<0 || !engage_auto || (engage_gate>0 && fabsf(speed_of(&car))>engage_gate))return -1;   /* at any speed: the original's CanWeEngage asks only for the zone (beta issue 121) */
    return at;
}

/* One contextual Up owner, shared by its HUD and activation. A new edge
 * may ask again after Cancel; discovery never synthesizes that edge.
 * Player::RacingJoyHandler (GC 8021a930, event BF / DPADUP) separates
 * trigger discovery from engagement. Menus retain their own raw buttons. */
enum { STREET_NONE,STREET_EVENT,STREET_SHOP,STREET_PHOTO,STREET_OUTRUN,STREET_CHALLENGE };
/* The street's chimes, FE_COMMON_MB's (tools/convert_audio.py): an SMS
 * opening itself (SMSMessageQueue::DoAutopopup), the HUD's engage icon
 * coming in and settling a second later (EngageEvent::Start and
 * updateState), new mail's envelope, bank cash (FEngHud::ShowPickedUpBank).
 * Beta issue 120. And the GPS's way found (MinimapWrapper::UpdateGPS: each
 * time its status turns to a path found, PlayUISoundFX 0x12, the bank's 18;
 * the way searched again off the route rings it again; beta issue 106).
 * chime_plays: telemetry, by kind. */
enum { CHIME_POPUP,CHIME_ENGAGE,CHIME_SETTLE,CHIME_SMS,CHIME_BANK,CHIME_GPS,CHIMES };
static int sfx_chime[CHIMES]={-1,-1,-1,-1,-1,-1};static unsigned chime_plays[CHIMES];
static struct { int kind,id,opened;float kmh; } engage_press={STREET_NONE,-1,0,0};
static struct { int found,k,dir;float x,z,near; } flyby={0,-1,-1,0,0,1e9f};   /* telemetry of script 15's pass (yaw 4/5): its target, way in, nearest the car came */   /* telemetry: the last Up that engaged, the car's speed then (beta issue 121) */
static void chime(int k) {
    chime_plays[k]++;
    if(snd_ok && sfx_chime[k]>=0)audio_play_ui(sfx_chime[k],1.f);   /* frontend chimes stay dry in tunnels */
}
static int street_engage_kind(void) {
    if(mode!=MODE_DRIVE || front!=FRONT_OFF || menu!=MENU_OFF || race.state!=RACE_OFF ||
       world_level || replay_on || cover.on || arrival_letterbox() || shopnis_active())return STREET_NONE;
    if(engage_auto && engage_k>=0 && career_state()->open[engage_k])return STREET_EVENT;
    if(shop_prompt>=0)return STREET_SHOP;
    if(show_prompt>=0)return STREET_PHOTO;
    if(show_start>=0)return STREET_CHALLENGE;
    if(outrun.state==OUTRUN_ROAM && outrun.engageable>=0 && !challenge_on())return STREET_OUTRUN;   /* RandomEncounterState::CanThisCarBeEngaged: none in a world challenge */
    return STREET_NONE;
}

/* The shops' scenes, as the original's CAnimManager::ShopNIS_*: entering a
 * city shop, the car drives in on the scene's path through the shop's
 * roll-up door as it opens, the scene's own camera, the traffic gone
 * (MakeTrafficDisappear); then the shop's first-time movie and its screen
 * (BackFromShopEnterNIS). Leaving, the car drives out to the street from
 * that door, which rolls down behind it, and the traffic comes back. The
 * prologue's car lot and garage too: left without the scenes, the car went
 * back to the airport and the arrival played again. */
static float shopsc_memo[3][3],shopsc_oy,shopsc_o[2];   /* shopsc_o: the scene's origin (x, z), at the shop's door */
static struct { unsigned began[2],ended[2],skipped,stale;float end_door_m,ctl_s,clamp_s; } shopsc_stats;   /* telemetry: the scenes by SHOPNIS_*; stale: the last exit's door hold still on as a scene began (beta issues 103 and 108); out of a shop, the car's distance from the scene's origin as it ends, the seconds the player's car was then held (Rachel talking) and the chase eye kept in front of the door */
static float shopsc_ground(float *memo,float x,float z,float below) {
    float dx=x-memo[0],dz=z-memo[1];
    if(dx*dx+dz*dz>.2f*.2f){memo[0]=x;memo[1]=z;memo[2]=shopsc_oy;world_ground(x,z,shopsc_oy,below,below,&memo[2]);}
    return memo[2];
}
/* The car on the scene's path, its speed by how far it went this frame.
 * A pose more than 1.1 m or 15 degrees from the last is a jump (the first
 * pose, a skip), the car put there at rest, as the original's
 * (NISMover::SetDesiredPosAndAngle: Car::ResetToPosition). A skip to the
 * scene's end left the speed of its last metres in one frame: X, the
 * throttle, in the garage's way out sent the car into the street at 120
 * to 270 mph (beta issue 95). */
static void shop_scene_pose(float dt) {
    float x,z,yaw;shopnis_car(&x,&z,&yaw);
    float gy=shopsc_ground(shopsc_memo[0],x,z,3.f);
    float dx=x-car.x,dz=z-car.z,moved=dt>0?sqrtf(dx*dx+dz*dz):0,turn=dt>0?lerp_angle(car.yaw,yaw,1)-car.yaw:0;
    if(moved>1.1f || fabsf(turn)>.2618f)moved=turn=0;   /* a jump, not a roll */
    car.x=x;car.z=z;car.yaw=yaw;car.ground=gy;car.y=gy-car.floor_y;car.vy=0;
    car.vx=dt>0 && moved>0?dx/dt:0;car.vz=dt>0 && moved>0?dz/dt:0;
    car.spin=fmodf(car.spin+moved/.33f,6.2831853f);
    float v=moved/fmaxf(dt,1e-3f);
    car.wheel+=(fmaxf(-.55f,fminf(.55f,v>.5f?atanf(2.6f*turn/fmaxf(dt,1e-3f)/fmaxf(v,1.f)):0))-car.wheel)*fminf(1,dt*8);
}
static int shop_exit_clamp;   /* (below, shop_exit_clamp_eye) */
static int shop_scene_start(int sh,int which) {
    if(shop_exit_clamp)shopsc_stats.stale++;
    if(shop_eye_fix)shop_exit_clamp=0;   /* the last exit's door is not this scene's: back in the shop within EXIT_CLAMP_M of it, the next exit's first frames were held to it (beta issues 103 and 108) */
    if(admission_failed || world_critical_closed()){admission_failed=1;admission_log("shop-scene-admission",0,0,-1);return -1;}
    if(!career_count() || world_level)return 0;   /* the prologue too: in by the scene, then the shop's first-time movie (BackFromShopEnterNIS: LaunchPreShopMovie); out by it */
    const CareerShop *s=career_shop(sh);float g[3],gy;unsigned ang;
    if(!s || !shopnis_marker(s->name,g,&ang))return 0;
    float o[3]={g[1],g[2],g[0]};   /* GU: the game's y, z, x */
    step_mark(which==SHOPNIS_EXIT?"shop-exit-settle":"shop-enter-settle");
    race_teleport_settle(o[0],o[2]);
    step_mark(which==SHOPNIS_EXIT?"shop-exit-settled":"shop-enter-settled");
    if(admission_failed || world_critical_closed()){admission_failed=1;admission_log("shop-scene-stream",0,0,-1);return -1;}
    if(world_ground(o[0],o[2],g[2],6.f,6.f,&gy) || world_ground(o[0],o[2],s->y,30.f,30.f,&gy))o[1]=gy;
    if(!shopnis_begin(which,s->name,o))return 0;
    shopsc_oy=o[1];shopsc_o[0]=o[0];shopsc_o[1]=o[2];for(int k=0;k<3;k++)shopsc_memo[k][0]=1e9f;
    for(int i=0;i<TRAFFIC_MAX;i++)traffic[i].active=0;   /* the game's traffic goes for its scenes */
    traffic_target=0;
    if(which==SHOPNIS_EXIT)shop_declined=sh;   /* out of the shop, its dialog not again until the car leaves it */
    shopsc_stats.began[which]++;
    shop_scene_pose(0);camera_snap();
    return 1;
}
/* Into the shop: its screen, its first-time movie (the car lot's, the garage's).
 * The screen comes in the frame the scene ends, its load under the loading
 * screen (shop_in_loading: return_to_front), as the PS2's: its scene's last
 * frame, then LOADING. A street frame between showed the chase camera
 * behind the car inside the garage, the HUD up. */
static int shop_in_loading;
static void shop_go_in(void) {
    step_mark("shop-go-in");
    front_request=shop_front;shop_in_loading=1;
    const char *place=shop_front==FRONT_CARLOT?"carlot":shop_front==FRONT_CRIB?"crib":NULL;
    if(place && movie_queue("place",place,NULL,1))movies_play();
}
/* The scene by its clock (X skips it past its first half second, as the
 * game's ShopNIS_SafeSkipOver), the car on its path; at its end into the
 * shop, or back on the street. */
/* The prologue's second visit (DDAY_EVENT_B, the original's CRIB_1): out of
 * the car lot in the player's own car, the GPS to the garage as the exit
 * scene ends (PlayerCareerState::NotifyExitShopNISFinished). */
static int dday_gps;static void targets_build(void);static int gps_to_cat(int c);
/* Out of a shop: the chase camera as the exit scene ends (the game puts
 * the player's camera back there, CAnimManager::ShopNIS_SafeUpdate). The
 * scene leaves the car a few metres out of the door, and the chase eye
 * behind it sat inside the shop's building (the body shop's, the garage's:
 * a grey screen, no inside drawn), so near the door the eye stays in front
 * of it: no farther back than EXIT_DOOR_M behind where the scene left the
 * car, along the car's way out (shop_exit_clamp_eye), until the car is
 * EXIT_CLAMP_M away. The scene's last shot held until the car moved left
 * the camera there for good if the player waited.
 * The player's car stays held a little longer while Rachel is still talking
 * as the scene ends (her car lot lines over the first car's way out): up
 * to EXIT_TALK_S, or until she stops. */
static int shop_exit_clamp;static float shop_exit_door[2],shop_exit_out[2],shop_exit_talk;
#define EXIT_DOOR_M 4.f
#define EXIT_CLAMP_M 30.f
#define EXIT_TALK_S 2.5f
static void shop_exit_clamp_eye(float *e) {
    if(!shop_exit_clamp)return;
    if(mode!=MODE_DRIVE || race.state!=RACE_OFF || hypotf(car.x-shop_exit_door[0],car.z-shop_exit_door[1])>EXIT_CLAMP_M){shop_exit_clamp=0;return;}
    float ce=(car.x-shop_exit_door[0])*shop_exit_out[0]+(car.z-shop_exit_door[1])*shop_exit_out[1];
    float ee=(e[0]-shop_exit_door[0])*shop_exit_out[0]+(e[2]-shop_exit_door[1])*shop_exit_out[1];
    /* The car itself behind the door's line (a scene from another door: in
     * the next visit's exit the car starts inside the shop) has no eye to
     * keep in front of it: k 0 put the eye on the car, on its target (beta
     * issues 103 and 108) */
    if(ee>=0 || ce<=ee || (shop_eye_fix && ce<=0))return;
    float k=fmaxf(ce,0.f)/(ce-ee);   /* along the car to the eye, as far as the door's line, at its height */
    e[0]=car.x+(e[0]-car.x)*k;e[2]=car.z+(e[2]-car.z)*k;
    shopsc_stats.clamp_s+=1/30.f;
}
/* Accepted New Career invalidates the old scene even if it was paused before
 * returning to the frontend. No end callback, GPS target, car pose or save. */
static void shop_scene_cancel(void) {
    shop_exit_clamp=0;shop_exit_talk=0;dday_gps=0;
    shopnis_cancel();camera_snap();
}
static void dday_gps_now(void) { if(dday_gps){dday_gps=0;targets_build();gps_to_cat(6);} }   /* 6: MC_GARAGE (below) */
static void shop_scene_step(float dt,uint32_t pressed) {
    if(!shopnis_active())return;
    int cut=(pressed&PSP_CTRL_CROSS) && shopnis_clock()>.5f;
    if(cut){shopnis_skip();shopsc_stats.skipped++;}
    else shopnis_update(dt);
    shop_scene_pose(cut?0:dt);   /* a skip: the car at the scene's end, at rest */
    if(!shopnis_done())return;
    int which=shopnis_which();
    if(which>=SHOPNIS_DYNO_ENTER){dyno_scene_done(which);return;}   /* the dyno's (beta issue 144) */
    shopnis_stop();shopsc_stats.ended[which]++;
    if(which==SHOPNIS_ENTER)shop_go_in();
    else {   /* MakeTrafficReappear: the street again */
        traffic_clear();camera_snap();dday_gps_now();
        shop_exit_clamp=1;shop_exit_out[0]=sinf(car.yaw);shop_exit_out[1]=cosf(car.yaw);
        shop_exit_door[0]=car.x-shop_exit_out[0]*EXIT_DOOR_M;shop_exit_door[1]=car.z-shop_exit_out[1]*EXIT_DOOR_M;
        shop_exit_talk=audio_speech_playing()?EXIT_TALK_S:0;
        shopsc_stats.end_door_m=hypotf(car.x-shopsc_o[0],car.z-shopsc_o[1]);shopsc_stats.ctl_s=shopsc_stats.clamp_s=0;
    }   /* MakeTrafficReappear: the street again */
}
/* The shop scenes' near plane. Their eye stands half a metre over the
 * street, and a street triangle of 4 m beside it, cut at the near plane,
 * lands past the GE's 4096-pixel guard band: the GE drops it whole, and
 * the floor under it showed (CRIB_1's driveway, dark, a black square at
 * the car's tail). As far as SHOP_NEAR_MAX, the cut points half as far out
 * from the screen's centre; never past 80% of the way to the car's box,
 * which the camera comes within a wheel's width of. */
#define SHOP_NEAR_MAX 1.f
static float shop_scene_near(const float *e) {
    float dx=e[0]-car.x,dz=e[2]-car.z,c=cosf(car.yaw),s=sinf(car.yaw);
    float lx=fabsf(dx*c-dz*s)-model.half[0],lz=fabsf(dz*c+dx*s)-model.half[1];   /* in the car's own axes, past its sides */
    float y0=car.y+model.floor_y-.1f,y1=y0+1.7f,ly=e[1]<y0?y0-e[1]:e[1]>y1?e[1]-y1:0.f;
    lx=fmaxf(lx,0.f);lz=fmaxf(lz,0.f);
    return fminf(fmaxf(.8f*sqrtf(lx*lx+lz*lz+ly*ly),.5f),SHOP_NEAR_MAX);
}
static void shop_scene_camera(void) {
    float e[3],t[3],fov;shopnis_camera(e,t,&fov);
    e[1]+=shopsc_ground(shopsc_memo[1],e[0],e[2],30.f);
    t[1]+=shopsc_ground(shopsc_memo[2],t[0],t[2],30.f);
    look_camera_near(e,t,2.f*atanf(tanf(fov*.5f)*.75f)*57.29578f,shop_scene_near(e));   /* the game's horizontal field at 4:3 to the PSP's vertical */
}
/* On the dyno's rollers (beta issue 144), the original's DynoCarCameraMover:
 * round the car on a sphere, the stick turning it about the car (any way
 * round) and up and down between level and some 22 degrees over it, L and
 * R taking it in (to 5 m) and out (to 10 m) by 2% a frame; it starts where
 * DynoEnter's last shot stands (7.2 m the game's own). */
static struct { int on;float yaw,el,dist,fovy;int lx,ly;uint32_t keys; } dorb;
static void dyno_orbit_camera(float dt) {
    float t[3]={car.x,car.ground+.7f,car.z};
    if(!dorb.on) {   /* from the scene's last shot */
        float e[3],tt[3],fov;shopnis_camera(e,tt,&fov);
        e[1]+=shopsc_ground(shopsc_memo[1],e[0],e[2],30.f);
        float dx=e[0]-t[0],dy=e[1]-t[1],dz=e[2]-t[2],d=sqrtf(dx*dx+dy*dy+dz*dz);
        dorb.dist=d>.1f?fminf(10.f,fmaxf(5.f,d)):7.2f;dorb.yaw=atan2f(dx,dz);dorb.el=d>.1f?asinf(fmaxf(-1.f,fminf(1.f,dy/d))):.2f;
        dorb.fovy=2.f*atanf(tanf(fov*.5f)*.75f)*57.29578f;dorb.on=1;
    }
    float sx=(dorb.lx-128)/127.f,sy=(dorb.ly-128)/127.f;
    if(fabsf(sx)<.2f)sx=0;if(fabsf(sy)<.2f)sy=0;
    dorb.yaw+=sx*1.6f*dt;dorb.el=fmaxf(.03f,fminf(.38f,dorb.el-sy*.8f*dt));
    float k=powf(1.02f,dt*60.f);
    if(dorb.keys&PSP_CTRL_LTRIGGER)dorb.dist/=k;
    if(dorb.keys&PSP_CTRL_RTRIGGER)dorb.dist*=k;
    dorb.dist=fminf(10.f,fmaxf(5.f,dorb.dist));
    float e[3]={t[0]+dorb.dist*sinf(dorb.yaw)*cosf(dorb.el),t[1]+dorb.dist*sinf(dorb.el),t[2]+dorb.dist*cosf(dorb.yaw)*cosf(dorb.el)};
    look_camera_near(e,t,dorb.fovy,shop_scene_near(e));
}
/* Out of a shop the street entered: back to the street at its door, the
 * exit scene driving the car out (the original's way out of a shop); 0 if
 * there is no scene to play (the caller's old way). */
static int shop_exit_to_street(void) {
    int sh=shop_city;shop_city=-1;
    if(sh<0 || !career_count())return 0;
    const CareerShop *s=career_shop(sh);float g[3];unsigned ang;
    dday_gps=career_state()->stage==0 && s && s->kind==SHOP_LOT && career_state()->car!=FLEET_RACHEL;
    if(!s || !shopnis_marker(s->name,g,&ang))return 0;
    if(!switch_world(0)){admission_failed=1;admission_log("shop-exit-world",0,0,-1);return -1;}
    tod_start();   /* the street loaded again: its sunrise */
    if(admission_failed || world_critical_closed()){admission_failed=1;admission_log("shop-exit-admission",0,0,-1);return -1;}
    car_set_phys(&car,player_phys());car_place(&car,g[1],g[2],g[0],0,model.floor_y,player_top());nos_sync(1);
    cam.view=option_view();
    trax_context(1);career_roam_begin();career_world_anims();
    int started=shop_scene_start(sh,SHOPNIS_EXIT);
    if(started<0)return -1;
    if(!started){race_teleport_settle(car.x,car.z);camera_snap();dday_gps_now();}
    return 1;
}

/* Resume Career (StartCareerHelper, the garage's Resume): the free roam at
 * the career's place to start again (RaceStarter::StartCareerFreeRoam:
 * GetRespawnParameters into the player's DriverInfo), its ground found
 * again, as the original puts the car there; inside something solid, the
 * nearest road's lane (car_respawn). 0: no ground there (the caller's
 * earlier place). */
static int spawn_place(const float p[4]) {
    race_teleport_settle(p[0],p[2]);   /* the cells around streamed in first */
    if(admission_failed)return 0;
    float gy;
    if(!world_ground(p[0],p[2],p[1],1.5f,1.5f,&gy) || !isfinite(gy))return 0;
    car_set_phys(&car,player_phys());car_place(&car,p[0],gy,p[2],p[3],model.floor_y,player_top());nos_sync(1);
    if(car_inside_solid(&car))car_respawn();   /* (not car_fits: its margin moved a car left by a kerb or a wall to the next road's lane, 18 m off) */
    camera_snap();
    return 1;
}
/* The outrun each frame (outrun.c): what the career allows
 * (RandomEncounterState::CheckForRightConditions: the stage's wins below
 * its limit; in the prologue, stage 0, only in Rachel's 350Z until its
 * three races are run: Rachel's third timed line after them, the
 * "stage 0 timeout", ends them, and the player's own car has none
 * before stage 1; the PS2's RAM in a new career: the encounter on in
 * Rachel's car 30 s into the free roam), the rivals' cars, and what its
 * events bring. */
static int outrun_allowed(void) {
    if(!career_count())return 1;
    const CareerState *cs=career_state();
    if(cs->stage>=STAGE_N)return 1;   /* the career done: no limit */
    if(cs->stage==0)return cs->car==FLEET_RACHEL && !career_must_pick_car();
    const CareerStage *st=career_stage_info(cs->stage);
    return !st || st->outruns<0 || cs->outruns<st->outruns;
}
static struct { int frames,deep_frames,run,run_max,solid_frames,car_frames,n;float deep,log[8][6]; } orun_hit;   /* viewer-stats outrun.contacts: rival frames, frames with one 0.3 m into a traffic car (the longest run), inside a wall, into the player or the other rival; the deepest; log: frame, rival, depth, m from the player, in the physics, speed */
static void outrun_tick(float dt) {
    if(race.state!=RACE_OFF || world_level){if(outrun.state!=OUTRUN_WAIT || outrun.r[0].car || outrun.r[1].car)rivals_drop();orun.up=0;return;}
    int roam=roads_count() && menu==MENU_OFF && front==FRONT_OFF && !outrun_off && !cover.on;
    if(roam && outrun.state==OUTRUN_ROAM)rivals_load();
    Car *all[TRAFFIC_MAX+8];int na=gather_cars(all);
    OutrunInput in={&car,all,na,roam,outrun_allowed(),orun.up,UNITS_METRIC,dt};
    orun.up=0;
    int ev=outrun_update(&in);
    if(ev&OUTRUN_EV_START) {
        gps_off();   /* the GPS stops (GPSManager::Stop) */
        career_sms_event(SMS_OUTRUN_INTRO,NULL);   /* Rachel explains, the first time */
        outrun_say(0,0);orun.shown=0;orun.over=0;
    }
    if(ev&OUTRUN_EV_WON)outrun_end(1);
    if(ev&OUTRUN_EV_LOST)outrun_end(0);
}
#ifdef HOST_SIM
#include "../tools/sim/outrun_turn_fixture.h"
#endif
/* After the frame's moves and contacts (the rivals move before the
 * traffic: moving after its contacts, a rival tailing a traffic car was
 * drawn 0.45 m inside it every frame, the contacts never seeing them
 * together, beta issue 72): what was drawn, for the telemetry. */
/* The outrun's own time a frame (us, the game's clock: the calibrated
 * PPSSPP's PSP-3000), in the frames with a rival's car in the physics and
 * in those with the rivals on the belt only (beta issues 72, 74). */
static struct { double us[2];float max[2];int n[2]; } orun_cost;
static unsigned long long outrun_now(void) { return sceKernelGetSystemTimeWide(); }
static void outrun_cost(float us) {
    int phys=0,on=0;for(int k=0;k<OUTRUN_CARS;k++)if(outrun.r[k].on && outrun.r[k].car){on=1;phys|=outrun.r[k].physics;}
    if(!on)return;
    orun_cost.us[phys]+=us;orun_cost.n[phys]++;if(us>orun_cost.max[phys])orun_cost.max[phys]=us;
}
static void outrun_watch(void) {
    if(race.state!=RACE_OFF || world_level)return;
    /* The rivals inside a traffic car (0.3 m and more, as drawn this frame)
     * or a wall: through a car they pushed along, then the two into a wall
     * (beta issue 72) */
    {int deep=0,solid=0,incar=0;
     for(int k=0;k<OUTRUN_CARS;k++) {
         const Car *c=outrun.r[k].car;if(!outrun.r[k].on || !c)continue;
         float d=hypotf(c->x-car.x,c->z-car.z);
         for(int i=0;i<TRAFFIC_MAX;i++)if(traffic[i].active) {
             float pen=cars_overlap(c,&traffic[i].car);
             if(pen>.3f) {
#ifdef HOST_SIM
                 if(getenv("SIM_HITDBG"))fprintf(stderr,"HIT f=%u k=%d slot=%d pen=%.2f d=%.0f physics=%d rail=%d lite=%d rg=%.2f tg=%.2f rv=%.1f tv=%.1f r=(%.1f,%.1f) t=(%.1f,%.1f) ryaw=%.2f tyaw=%.2f state=%d\n",now_frame,k,i,pen,d,outrun.r[k].physics,traffic[i].rail,traffic[i].car.lite,c->ground,traffic[i].car.ground,car_speed(c),car_speed(&traffic[i].car),c->x,c->z,traffic[i].car.x,traffic[i].car.z,c->yaw,traffic[i].car.yaw,outrun.state);
#endif
                 deep=1;orun_hit.deep=fmaxf(orun_hit.deep,pen);
                 if(orun_hit.n<8 && (!orun_hit.n || now_frame-(unsigned)orun_hit.log[orun_hit.n-1][0]>30)){float *e=orun_hit.log[orun_hit.n++];e[0]=(float)now_frame;e[1]=(float)k;e[2]=pen;e[3]=d;e[4]=(float)outrun.r[k].physics;e[5]=car_speed(c);}
             }
         }
         if(cars_overlap(c,&car)>.3f)incar=1;   /* the player, and the other rival (beta issue 74) */
         for(int j=k+1;j<OUTRUN_CARS;j++)if(outrun.r[j].on && outrun.r[j].car && cars_overlap(c,outrun.r[j].car)>.3f)incar=1;
         if(d<110.f && world_collision_known(c->x,c->z) && car_inside_solid(c))solid=1;
     }
     orun_hit.deep_frames+=deep;orun_hit.run=deep?orun_hit.run+1:0;if(orun_hit.run>orun_hit.run_max)orun_hit.run_max=orun_hit.run;
     orun_hit.solid_frames+=solid;orun_hit.car_frames+=incar;
     for(int k=0;k<OUTRUN_CARS;k++)if(outrun.r[k].on && outrun.r[k].car)orun_hit.frames++;}
}
/* The outrun on the HUD (HUD_SingleRace's own): the engage indicator
 * while a rival can be challenged (the D-pad, Up lit, the outrun's icon
 * blinking: EventIndicator's random encounter); in the getaway the meter
 * (GetAwayMeter: green "Ahead", red "Behind", the bar filling to the
 * winning distance, the gap in meters or feet), "Outrun Challenge Accepted" on its
 * third frame, "You have the Lead!" / "You Lost the Lead!" as the lead
 * changes hands; at the end its result (RaceOverMessage). */
enum { FEHUD_GETAWAY=18,FEHUD_OUTMSG,FEHUD_RACERS,FEHUD_ENGAGE,FEHUD_GPS_RING,FEHUD_ZONES,FEHUD_REGION,FEHUD_GPS_SEARCH,FEHUD_HURRY,FEHUD_SHOWCASE };   /* after the race HUD's own (tools/convert_hud.py FREE_GROUPS) */
#define FEHUD_OUTOVER FEHUD_OVER   /* its result: the race over message's group */
#define FEHUD_GA_BAR    0xacbaf9efu   /* Getaway_Distance_Bar */
#define FEHUD_GA_NUM    0x92cdc512u   /* Distance_Number */
#define FEHUD_GA_UNIT   0xbcea10ceu   /* Distance_Text */
#define FEHUD_GA_GROUP  0x8ca76279u
#define FEHUD_OUT_MSG   0x407919afu   /* Out_Run_Message */
#define FEHUD_ENG_ICON  0x3b1b624au   /* the event's icon, ICON_RANDOM_ENCOUNTER on it */
#define FEHUD_ENG_UP    0x0a729b1bu   /* the D-pad's Up lit */
static int arrival_hud(int part);
/* SMSGetEnvelopeImageHashAndColour: a message's envelope by its colour
 * category (career.n2cr's envelope byte), the texture and the colour
 * (ABGR) the HUD's and the mailbox's envelope take */
static uint32_t sms_envelope(int category,uint32_t *abgr) {
    switch(category) {
    case 1:*abgr=0xff2dc8c8u;return 0x88c9990au;   /* ENGAGE_SMS_RACHEL_MESSAGE, yellow */
    case 2:*abgr=0xff2b80d5u;return 0x8b2f36eeu;   /* ENGAGE_SMS_OPPONENT_MESSAGE, orange */
    case 3:*abgr=0xff8af4cau;return 0x470222fdu;   /* ENGAGE_SMS_SPECIAL_EVENT_MESSAGE, pale green */
    case 4:*abgr=0xff3030cfu;return 0xa9dfe648u;   /* ENGAGE_SMS_OUTRUN_MESSAGE, red */
    case 5:*abgr=0xffff8080u;return 0x5d9b6555u;   /* ENGAGE_SMS_SHOP_MESSAGE, blue */
    case 6:*abgr=0xffc88232u;return 0x756b5c1bu;   /* ENGAGE_SMS_TIPS_MESSAGE */
    case 7:*abgr=0xffb54a80u;return 0x55476a96u;   /* ENGAGE_SMS_RACE_MESSAGE */
    default:*abgr=0xff0e9c0eu;return 0x4b9b8f5au;  /* ENGAGE_SMS_MAIL, green (the tips') */
    }
}
/* The backing and centre are shared with race/shop/rival engagement.
 * UpdateSMS (GC 80111014): the idle centre is Cingular. A new message:
 * the envelope in its category's texture and colour on its "animation";
 * settled, the plain envelope "static" and the count's text written empty
 * (the original prints "" there: no xN, beta issue 122). The upper backing
 * has no invented sender/body label. */
static int street_sms_hud(float dt,int prompt) {
    static SmsIndicator state;static FeScreen *screen;
    if(screen!=hud_s){state=(SmsIndicator){.latest=-1};screen=hud_s;}
    int fresh=race.state==RACE_OFF && career_count() && arrival_hud(2)?career_sms_new():0,latest=-1;
    if(fresh)for(int i=career_sms_count()-1;i>=0;i--)if(career_sms_unread(i)){latest=i;break;}
    float was_age=state.age;static int was=SMS_IND_OFF;
    int phase=sms_indicator_step(&state,fresh,latest,prompt!=STREET_NONE,arrival.on && !arrival.opened,dt);
    /* new mail's chime as its phone comes, the settle's as it gives way to
     * the command (the prologue's held phone: none, as the original's) */
    if(phase==SMS_IND_PHONE && (was!=SMS_IND_PHONE || state.age<was_age))chime(CHIME_SMS);
    else if(phase==SMS_IND_COMMAND && was==SMS_IND_PHONE)chime(CHIME_SETTLE);
    was=phase;
    int visible=phase!=SMS_IND_OFF && prompt==STREET_NONE;
    int envelope=fe_find(hud_s,FEHUD_SMS_ICON),count=fe_find(hud_s,0x668c9cd6u);
    fe_show(hud_s,FEHUD_SMS,visible);fe_alpha(hud_s,count,0);
    if(visible){
        int centre=fe_find(hud_s,0x50910822u),right=fe_find(hud_s,0xa206a0b4u);
        uint32_t texture=fe_hash(phase==SMS_IND_PHONE?"ENGAGE_PHONE_ICON":phase==SMS_IND_COMMAND?"PS2_SELECT":"ENGAGE_CINGULAR_ICON");
        fe_texture(hud_s,centre,texture);
        fe_play(hud_s,centre,phase==SMS_IND_STATIC?FE_SCRIPT_INIT:fe_hash("Pulse"));
        fe_play(hud_s,right,fe_hash(phase==SMS_IND_STATIC?"static":"pulse"));
        fe_play(hud_s,envelope,phase==SMS_IND_STATIC?fe_hash("static"):FEHUD_SMS_BLINK);
        uint32_t colour=0xffffffffu,picture=FEHUD_SMS_ICON;
        if(phase!=SMS_IND_STATIC && latest>=0)picture=sms_envelope(career_sms_mail(latest)->envelope,&colour);
        if(!fe_texture(hud_s,envelope,picture))fe_texture(hud_s,envelope,FEHUD_SMS_ICON);   /* (a hud.n2ui without the categories' envelopes: the plain one) */
        if(colour!=0xffffffffu)fe_paint(hud_s,envelope,colour);else fe_color(hud_s,envelope,colour);   /* the animation's base colour (FEKeyTrack::SetBaseValueAt), its alpha the script's */
    }
    return visible;
}
/* EventIndicator in the career's free roam: Player::DetermineEventInfo
 * keeps it on out of a race; in the prologue Stage0StateManager decides:
 * the telephone pulsing for two seconds once the arrival's camera lets go
 * (ShowTelephone, state 2), then nothing until Rachel's SMS and from its
 * reading to the minimap's coming (the PS2 shows no box there: frames
 * 18280 and 21-in-control), the indicator after. 0 off, 1 on, 2 the
 * telephone. */
static int indicator_now;
static int indicator_state(int post) {
    if(post || race.state!=RACE_OFF || !career_count() || world_level || mode!=MODE_DRIVE)return 0;
    if(!arrival.on)return 1;
    if(arrival.t<ARR_SHOW)return 0;
    if(!arrival.opened)return arrival.t<ARR_SHOW+2.f?2:0;
    return arrival_hud(0);
}
/* Nothing to announce (EventIndicator::SetResetState): its backing and the
 * D-pad's ring with the Cingular logo at the centre, or the telephone
 * (EngageEvent::UpdateCareerStage0: ENGAGE_PHONE_ICON, "Pulse"). */
static void indicator_idle(int phone) {
    int c=fe_find(hud_s,0x50910822u);
    fe_texture(hud_s,c,fe_hash(phone?"ENGAGE_PHONE_ICON":"ENGAGE_CINGULAR_ICON"));
    fe_play(hud_s,c,phone?fe_hash("Pulse"):FE_SCRIPT_INIT);
    fe_alpha(hud_s,fe_find(hud_s,FEHUD_ENG_ICON),0);fe_alpha(hud_s,fe_find(hud_s,FEHUD_ENG_UP),0);fe_alpha(hud_s,fe_find(hud_s,0xa206a0b4u),0);
}
static void outrun_hud(float dt,int hidden) {
    static int was_on,ahead=-1;static float blink;
    if(hidden) {
        for(int g=FEHUD_GETAWAY;g<=FEHUD_ENGAGE;g++)fe_show(hud_s,g,0);
        fe_show(hud_s,FEHUD_SMS,0);if(race.state==RACE_OFF)fe_show(hud_s,FEHUD_OUTOVER,0);   /* (a race's message is original_hud's) */
        if(indicator_now){fe_show(hud_s,FEHUD_ENGAGE,1);indicator_idle(indicator_now==2);}   /* the prologue's, before the rest of the HUD */
        return;
    }
    int on=outrun.state==OUTRUN_RACE;
    fe_show(hud_s,FEHUD_GETAWAY,on);
    int prompt=street_engage_kind();
    /* GetEventTypeTexHash (GC 801115f0), included by convert_hud.py.
     * Older HUDs may lack them: hide the CTA rather than reuse a wrong icon. */
    static const char *const races[]={"MODE_ICON_CIRCUIT","MODE_ICON_SPRINT","MODE_ICON_SHORT_TRACK","MODE_ICON_CIRCUIT","MODE_ICON_DRAG","MODE_ICON_DRIFT"};
    static const char *const shops[]={"SHOP_ICON_CAR_LOT","SHOP_ICON_PERFORMANCE","SHOP_ICON_BODY","SHOP_ICON_GRAPHIC","SHOP_ICON_INTERIORS","SHOP_ICON_CRIB"};
    const char *icon=prompt==STREET_OUTRUN?"ICON_RANDOM_ENCOUNTER":NULL;
    if(prompt==STREET_EVENT){const CareerEvent *e=career_event(engage_k);const CareerRecord *r=career_record(engage_k);
        if(e->type<6)icon=races[e->type];
        if(e->reward==2)icon="MODE_ICON_U_RACING_LEAGUE";else if(r && r->suv)icon="MODE_ICON_SUV";}
    if(prompt==STREET_SHOP){int t=career_shop(shop_prompt)->kind;if(t<6)icon=shops[t];}
    if(prompt==STREET_CHALLENGE)icon="MODE_ICON_WORLD_CHALLENGE";   /* EventIndicator 0x12, a world challenge's zone (FEngHud::EnterTriggerZone) */
    {   /* the engage icon's chimes: in as it comes, its settle a second on (gone before that: none) */
        static int kind=STREET_NONE,id=-1;static float age;
        int now=prompt==STREET_EVENT?engage_k:prompt==STREET_SHOP?shop_prompt:prompt==STREET_PHOTO?show_prompt:prompt==STREET_OUTRUN?outrun.engageable:-1;
        if(prompt==STREET_NONE)kind=STREET_NONE;
        else if(prompt!=kind || now!=id){kind=prompt;id=now;age=0;chime(CHIME_ENGAGE);}
        else if(age<1.f && (age+=dt)>=1.f)chime(CHIME_SETTLE);
    }
    int sms=street_sms_hud(dt,prompt);
    fe_show(hud_s,FEHUD_ENGAGE,icon!=NULL || sms || indicator_now);
    if(!icon && !sms && indicator_now)indicator_idle(indicator_now==2);
    fe_alpha(hud_s,fe_find(hud_s,FEHUD_ENG_ICON),icon!=NULL);
    fe_alpha(hud_s,fe_find(hud_s,FEHUD_ENG_UP),icon!=NULL);
    fe_alpha(hud_s,fe_find(hud_s,0xa206a0b4u),sms);
    if(icon) {
        int ic=fe_find(hud_s,FEHUD_ENG_ICON),up=fe_find(hud_s,FEHUD_ENG_UP);
        /* Restore the package's PS2 command after SMS used this centre. */
        fe_texture(hud_s,fe_find(hud_s,0x50910822u),fe_hash("3RDPERSON_DPAD_PS2"));
        if(!fe_texture(hud_s,ic,fe_hash(icon))){fe_show(hud_s,FEHUD_ENGAGE,0);if(prompt==STREET_CHALLENGE)challenge_icon_missing=1;}
        else if(prompt==STREET_CHALLENGE)challenge_icon_missing=0;
        else if((blink-=dt)<=0){fe_play_at(hud_s,ic,FE_SCRIPT_BLINK,0);fe_play_at(hud_s,up,FE_SCRIPT_BLINK,0);blink=1.f;}
    } else blink=0;
    if(on!=was_on){fe_play(hud_s,fe_find(hud_s,FEHUD_GA_GROUP),on?0x4f90cf9bu:0xfb12d252u);was_on=on;ahead=-1;}   /* Active / InActive */
    if(on) {
        float d=outrun.lead,frac=fminf(1,fabsf(d)/outrun.limit);
        int now=d>=0;
        if(now!=ahead) {   /* Ahead / Behind: the number's script and the bar's colour */
            fe_play(hud_s,fe_find(hud_s,FEHUD_GA_NUM),now?0x026bb992u:0x520393a9u);
            fe_paint(hud_s,fe_find(hud_s,FEHUD_GA_BAR),now?0x30cf30u:0x000095u);
            ahead=now;
        }
        int bar=fe_find(hud_s,FEHUD_GA_BAR);
        fe_crop(hud_s,bar,(99.f+frac*(256.f-99.f-1.f))/256.f);   /* the bar from its 99 px of 256 to its end at the winning distance */
        char b[24];snprintf(b,sizeof b,"%d",(int)(UNITS_METRIC?fabsf(d):fabsf(d)*3.28f));fe_text(hud_s,fe_find(hud_s,FEHUD_GA_NUM),b);
        fe_text(hud_s,fe_find(hud_s,FEHUD_GA_UNIT),UNITS_METRIC?unit_word(0x6bb2d6afu,"Meters"):unit_word(0x1578c3u,"Feet"));
        if(++orun.shown==3) {   /* its third frame: the challenge accepted */
            int m=fe_find(hud_s,FEHUD_OUT_MSG);
            fe_text(hud_s,m,outrun.rival_leads?"Outrun Challenge Accepted\nCatch Them!":"Outrun Challenge Accepted\nLose Them!");
            fe_play_at(hud_s,m,0x8ab83edbu,0);orun.msg=1.8f;   /* ZoomIn */
        }
    }
    static int led=-1;
    if(on && led>=0 && led!=!outrun.rival_leads) {
        int m=fe_find(hud_s,FEHUD_OUT_MSG);
        fe_text(hud_s,m,outrun.rival_leads?"You Lost the Lead!":"You have the Lead!");
        fe_play_at(hud_s,m,0x8ab83edbu,0);orun.msg=1.8f;
    }
    led=on?!outrun.rival_leads:-1;
    orun.msg-=dt;fe_show(hud_s,FEHUD_OUTMSG,orun.msg>0);
    if(orun.over>0) {   /* the result, in big */
        if(orun.over>=4.f){fe_play_at(hud_s,fe_find(hud_s,FEHUD_OVER_TEXT),0x657a31f6u,0);fe_play_at(hud_s,fe_find(hud_s,FEHUD_OVER_BACK),0x36819d93u,0);}   /* RaceOver, and the backing's getaway look */
        orun.over-=dt;
        fe_text(hud_s,fe_find(hud_s,FEHUD_OVER_TEXT),orun.over_text);
        fe_show(hud_s,FEHUD_OUTOVER,orun.over>0);
    } else fe_show(hud_s,FEHUD_OUTOVER,0);
}

/* ------------------------------------------------------------------ sound */
/* Engine from a virtual six-speed gearbox, tyres, wind, nitrous, impacts. */
static int sfx_fe_move=-1,sfx_fe_accept=-1,sfx_fe_back=-1,sfx_fe_down=-1,sfx_fe_left=-1,sfx_fe_right=-1,sfx_fe_start=-1;   /* the menus' sounds (FE_COMMON_MB; tools/convert_audio.py) */
static int title_sfx,title_keys;   /* telemetry: menu sounds played on the title, its presses that were not the continue */
static unsigned menu_sfx_n[7];   /* telemetry: menu_sound's by key: accept, back, start, up, down, left, right */
static void fe_sound(int s) {
    if(front==FRONT_TITLE)title_sfx++;
    audio_play_ui(s,1.f);
}
/* A menu's press: move, accept or back, as the original's frontend. */
static void menu_sound(uint32_t pressed) {
    if(!snd_ok)return;
    /* at their full level: on the PS2 a menu's sound peaks 4 dB over the
     * race's engine (6.6 over the menu's music), as these do */
    /* each key its own, as the original's MenuScreen::BaseNotifySound and
     * FrontendSoundMap (its screens' filters, a vertical menu without Left
     * and Right and so on, not followed here) */
    int k=pressed&PSP_CTRL_CROSS?0:pressed&(PSP_CTRL_CIRCLE|PSP_CTRL_TRIANGLE)?1:pressed&PSP_CTRL_START?2:
          pressed&PSP_CTRL_UP?3:pressed&PSP_CTRL_DOWN?4:pressed&PSP_CTRL_LEFT?5:pressed&PSP_CTRL_RIGHT?6:-1;
    const int s[7]={sfx_fe_accept,sfx_fe_back,sfx_fe_start,sfx_fe_move,sfx_fe_down,sfx_fe_left,sfx_fe_right};
    if(k>=0 && s[k]>=0){menu_sfx_n[k]++;fe_sound(s[k]);}
}
static int snd_wind=-1,sfx_shift,snd_hydro=-1,sfx_hydro=-1,snd_rain=-1;
static int snd_traffic[2]={-1,-1};static int traffic_heard;   /* the traffic's engines (traffic_sound); telemetry: frames one was heard */
int speed_snd_off=0;   /* 1: no wooshes, 2: no tyres nor road, 4: no bottoming out nor landings (their cost, A/B; poked) */
/* The compact profile (the PSP-1000's 32 MB) plays no wooshes: their spheres
 * (70 KB) and their bank decoded (0.5 MB) stay out of its budget, and with
 * them the mixer's dearest voices. The tyres, the road and the impacts stay. */
static int wooshes_off(void) { return (speed_snd_off&1) || small_memory; }
static int wooshes;static float woosh_wait[TRAFFIC_MAX];   /* passing one close: each car's 3 s; telemetry: wooshes played */
static int sfx_train=-1,sfx_plane=-1;   /* the animated world's (world_sound) */
static int sfx_horn[3]={-1,-1,-1},horns;   /* a traffic car's horn (traffic_horn); telemetry: horns blown */
static int turbo_blowoffs;static float turbo_share_max;   /* telemetry (viewer-stats turbo_sound) */
static int snd_turbo=-1,sfx_turbo_bov[3]={-1,-1,-1};   /* the turbo's whistle, its three blow-offs (the bank's fifth sound, a hiss, the original never plays) */
/* telemetry (the smoke's): the engine sound's revs against the
 * tachometer's (outside the shifts, the limiter and the transients), frames
 * with a rival within 40 m and those with its engine heard */
static struct { double err;int frames,over;float worst;int rival_near,rival_heard,shift_sounds,blips,limiter; } esnd;
