        {static const char *const n[CHIMES]={"chime_popup","chime_engage","chime_settle","chime_sms","chime_bank","chime_gps"};for(int k=0;k<CHIMES;k++)sfx_chime[k]=audio_sfx(n[k]);}   /* (older sfx.n2sf: none, silent) */
