        const OGState *body=&original_player.rewind.state;const OGEngineProfile *engine=&original_player.config.profile.engine;
        int selected=original_player.rewind.output.display_gear,shifted=gear!=selected;gear=selected;
        tach.idle=engine->idle_rpm;tach.redline=engine->red_rpm;tach.limiter=engine->max_rpm;tach.style=tach_style(tach.redline,tach.limiter);
        pbox.gear=selected;pbox.want=(int)body->drive.wanted_gear-1;pbox.rpm=car_engine_rpm(&car);pbox.clutch=body->drive.engagement;pbox.shifting=body->drive.phase!=3;
        pbox.cls=(int)original_player.config.profile.car_class;
