        float p[3]={0},v[3]={0},e[3]={car.x,car.ground+1.f,car.z};
        int on=active && sfx[k]>=0 && worldanim_nearest(kind[k],e,p,v);
        float dx=p[0]-e[0],dy=p[1]-e[1],dz=p[2]-e[2],d=on?fmaxf(sqrtf(dx*dx+dy*dy+dz*dz),1.f):1e9f;
        float near_k=fminf(1.f,fmaxf(0.f,(radius[k]-d)/(radius[k]*.9f)));
