        if(wsnd[k].vol<.002f && target<=0){if(wsnd[k].voice>=0){audio_stop(wsnd[k].voice);wsnd[k].voice=-1;}continue;}
        if(wsnd[k].voice<0 && (wsnd[k].voice=audio_loop(sfx[k]))<0)continue;
