            throttle=b->engine.limiter?0:b->delegated_throttle*b->engine.throttle_scale;
            rev=(b->engine.omega*9.549304f-e->idle_rpm)/fmaxf(1.f,e->max_rpm-e->idle_rpm);limiter=b->engine.limiter;
