    {static int marked;const ImpactStats *is=impacts_stats();   /* the run's sound recording: where each impact is */
     if(is->impacts!=marked){char b[48];snprintf(b,sizeof b,"impact %d %d %d",is->last_stitch,is->last_surface,is->last_intensity);test_mark(b);marked=is->impacts;}}
