    if(ready!=s) {
        mp=fe_find(s,0x0f365871u);o_type=fe_find(s,0x15e1351bu);o_dist=fe_find(s,0x080c9daau);o_purse=fe_find(s,0xb54b81a7u);
        o_from=fe_find(s,0xfeced617u);o_subj=fe_find(s,0x2c167533u);o_body=fe_find(s,0xde075b62u);shown=-1;ready=s;
    }
