/* An engage tip (the city's markers of type 0x12): driving through one
 * sends its SMS ("GPS: Find your way to race events..."), banks its money
 * (career_tip_send) and the PS2 shows it at once in UI_EngageMessageDialog.fng, "Incoming SMS Message": from,
 * subject and the text, X back to the street, O to the mailbox. */
static unsigned tip_load_ms,tip_save_ms,tip_n,tip_money;   /* the street held by an SMS (viewer-stats street_stall); the tips' money banked */
/* A tip flagged CAREER_TIP_QUEUE (all but ENGAGE_TIP_CAREER_PROG, in the
 * original's data: its SMS's +4) only sends its SMS: the mailbox, the HUD's
 * envelope and new mail's chime (street_sms_hud), no dialog (show 0). The
 * one that opens itself chimes as DoAutopopup does. Beta issue 120. */
static void tip_open(int sms,int show) {
    uint64_t t0=sceKernelGetSystemTimeWide();
    if(show && !tip_s){tip_s=fe_load("msgdlg.n2ui");if(tip_s){fe_show(tip_s,1,1);fe_widen(tip_s,480.f/640.f);}ui_open=NULL;}
    uint64_t t1=sceKernelGetSystemTimeWide();
    tip_money+=(unsigned)career_tip_send(sms,NULL);if(show)career_sms_read(sms);career_save("career.sav");
    {unsigned l=(unsigned)((t1-t0)/1000),v=(unsigned)((sceKernelGetSystemTimeWide()-t1)/1000);if(l>tip_load_ms)tip_load_ms=l;if(v>tip_save_ms)tip_save_ms=v;tip_n++;}
    if(!show || !tip_s)return;
    tip_sms=sms;menu=MENU_TIP;chime(CHIME_POPUP);
}
/* Open Bayview (roam_stage): the original's tips know no stage, its
 * barriers keep the car from the ones past them. The city open, a tip
 * counts only in the part of it the career's stage opens: the roads
 * reached from the stage's shops past none of its barriers (gps_area_build),
 * worked out again at each new stage; none at all without the GPS's net. */
static struct { int stage,built,held,open,tips; } tip_area={-1};
static int p205_step;   /* script 205's (the pause's Options > Debug): its last step */
/* Script 203's (Open Bayview): the GPS's target shop, how near the car
 * came, and the career before (0) and after (1, its save read back). */
static struct { int on,set,shop,reached,saved,load,tips,stages_done,stage_tips[6],crossed,shot;float tx,tz,d0,dmin;struct { int stage,sms,open,won;unsigned money;uint32_t shops; } c[2]; } o203;
static void o203_snap(int k) {
    if(!career_count())return;
    const CareerState *cs=career_state();o203.c[k].stage=cs->stage;o203.c[k].money=cs->money;o203.c[k].shops=cs->shops_seen;
    o203.c[k].sms=0;for(int i=0;i<career_sms_count();i++)o203.c[k].sms+=career_sms_sent(i);
    o203.c[k].open=0;o203.c[k].won=0;for(int i=0;i<career_count();i++){o203.c[k].open+=career_shown(i);o203.c[k].won+=cs->best[i]==1;}
}
static int tip_in_stage(const CareerTip *t) {
    int st=career_stage_now();
    if(roam_stage()==st)return 1;   /* the career's own barriers up */
    if(tip_area.stage!=st) {
        float xz[2*SHOP_MAX];int n=0;
        for(int i=0;i<career_shop_count() && n<SHOP_MAX;i++){const CareerShop *sh=career_shop(i);if(sh->stage<=st){xz[2*n]=sh->x;xz[2*n+1]=sh->z;n++;}}
        tip_area.built=n && gps_area_build(st,xz,n);tip_area.stage=tip_area.built?st:-1;   /* (again next time without the city's roads)*/
        tip_area.open=0;tip_area.tips=career_tip_count();
        for(int i=0;tip_area.built && i<career_tip_count();i++)tip_area.open+=gps_area_has(career_tip(i)->x,career_tip(i)->z)==1;
    }
    return tip_area.built && gps_area_has(t->x,t->z)==1;
}
static void tip_update(void) {   /* on the street: the first tip the car is over, once */
    if(!tips_on || menu!=MENU_OFF || race.state!=RACE_OFF || world_level || !career_count())return;
    for(int i=0;i<career_tip_count();i++) {
        const CareerTip *t=career_tip(i);float dx=car.x-t->x,dz=car.z-t->z,r=t->radius+2.f;
        if(dx*dx+dz*dz<r*r && !career_sms_sent(t->sms)) {
            if(!tip_in_stage(t)){static int last=-1;if(last!=i){tip_area.held++;last=i;}continue;}   /* past the stage's barriers (Open Bayview) */
            tip_open(t->sms,!(t->flags&CAREER_TIP_QUEUE));return;
        }
    }
}
/* The city's cash (markers of type 0x13): driving over one banks it, once,
 * from the career stage it is there; the HUD says so, as the PS2's "Bank
 * Cash". */
static void cash_update(void) {
    if(menu!=MENU_OFF || race.state!=RACE_OFF || world_level || !career_count())return;
    for(int i=0;i<career_cash_count();i++) {
        const CareerCash *c=career_cash(i);float dx=car.x-c->x,dz=car.z-c->z;
        if(dx*dx+dz*dz<5.f*5.f && career_cash_here(i)) {
            int got=career_take_cash(i,"career.sav"),o=fe_find(hud_s,FEHUD_CASH_BANK);
            char m[48],g[16];snprintf(m,sizeof m,"%s %s",lang_or(0x5d10f6afu,"Bank Reward:"),money_grouped(g,sizeof g,got));   /* PickedUpBankIndicator::Update: "%s %$d", "Bank Reward: 1,000" (beta issue 200) */
            if(o>=0){fe_text(hud_s,o,m);fe_play_at(hud_s,o,FEHUD_CASH_ANIMATE,0);}   /* FEngSetScript(Cash_Bank, Cash_Animate): under the balance, into it */
            else race_say(m);   /* a hud.n2ui converted before Cash_Bank (beta issue 182) */
            chime(CHIME_BANK);
            return;
        }
    }
}
static void tip_draw(float dt) {
    FeScreen *s=tip_s;
    fe_alpha(s,fe_find(s,0xfeced617u),1);fe_alpha(s,fe_find(s,0x2c167533u),1);fe_alpha(s,fe_find(s,0x42adb44cu),1);
    static const uint32_t buttons[]={0xb02b46b7u,0x00169268u,0x97b71ddeu,0xe202f7c4u};
    for(unsigned k=0;k<sizeof buttons/sizeof *buttons;k++)fe_alpha(s,fe_find(s,buttons[k]),1);
    const CareerSms *m=career_sms(tip_sms);if(!m)return;char b[128];
    static FeScreen *ready;
    if(ready!=s) {
        fe_alpha(s,fe_find(s,0x47ff4e7cu),0);fe_alpha(s,fe_find(s,0x980822b3u),0);   /* the debug labels */
        ready=s;
    }
    for(int k=0;k<10;k++){int o=fe_find(s,k<9?0xde075b61u+k:0x9ef2c7b1u);fe_text(s,o,"");fe_alpha(s,o,0);}   /* the reader's lines (it shares the package) */
    lang_format(b,sizeof b,"From: %s",lang_en(career_text(m->sender)));fe_text(s,fe_find(s,0xfeced617u),b);   /* the game's words in the PSP's language (lang.c) */
    lang_format(b,sizeof b,"Subject: %s",lang_en(career_text(m->subject)));fe_text(s,fe_find(s,0x2c167533u),b);
    fe_update(s,dt);fe_draw(s);
    /* the text under the subject (placed once the FADEIN has moved it), as wide as the box */
    float x,y,sc;fe_place(s,fe_find(s,0x2c167533u),&x,&y,&sc);
    wrap_left(s,0,x,y+26.f,2.f*(240.f-x)-24.f,.4f,13.f,0xffe0e0e0,lang_en(career_text(m->body)),9);
}

/* Career Status (UI_Status_Master.fng over UI_Status_Career.fng), as the
 * PS2's on the pad's Down: its first page, Overall Career Statistics, the
 * visual rating in stars, then the career's numbers (the money spent on
 * the cars counted since save version 9); X continues. */
static void status_open(void) {
    if(!statusm_s){statusm_s=fe_load("statusm.n2ui");statusc_s=fe_load("statusc.n2ui");statusr_s=fe_load("statusr.n2ui");statusd_s=fe_load("statusd.n2ui");
        FeScreen *all[4]={statusm_s,statusc_s,statusr_s,statusd_s};
        for(int k=0;k<4;k++)if(all[k]){fe_show(all[k],1,1);fe_widen(all[k],480.f/640.f);}
        ui_open=NULL;}
    if(!statusm_s || !statusc_s)return;
    menu=MENU_STATUS;status_page=0;
}
/* The Career Status' other pages, as the PS2's (Right from the first):
 * the stage's (the prologue's "Intro Status" goals on the first page's
 * rows; a contract stage's UI_Status_Region: the contract's terms done) and
 * the stage's DVD covers (UI_Status_DVD: each with the star rating it
 * needs, ticked once won; "Not Available" before the contract stages). */
static void status_stage_draw(FeScreen *m,FeScreen *c,FeScreen *r,const int *label,const int *value,float dt) {
    const CareerState *cs=career_state();char b[48];
    if(cs->stage<2 || !r) {   /* the prologue: the goals left, on the first page's rows */
        const char *goal[7];int n=0;
        if(cs->car==FLEET_RACHEL)goal[n++]="Go to Car Lot";
        goal[n++]="Go To Garage";
        if(cs->stage==1){CareerContract k;career_contract(&k);static char line[40];snprintf(line,sizeof line,"Races Finished: %d/%d",k.finish,k.finish_need);goal[n++]=line;}
        fe_text(m,fe_find(m,0x3223a234u),"Intro Status");
        for(int k=0;k<7;k++) {
            fe_alpha(c,fe_find(c,0x28887216u+k),k<n?1.f:0.f);fe_alpha(c,label[k],k<n?1.f:0.f);fe_alpha(c,value[k],0);
            if(k<n)fe_text(c,label[k],goal[k]);
            static const uint32_t parts[]={0x654668ecu,0x4e4963ddu,0x7770beffu,0x77abeb28u,0xb830bb54u};
            for(int q=0;q<5;q++)fe_alpha(c,fe_find(c,parts[q]+k),0);
        }
        /* no Visual Rating on this page: everything of its strip out (the
         * stars, the bar), the first page brings it back */
        int rows=fe_find(c,0x8d7e0c53u);   /* the rows' texts and frame hang from a group up there: kept */
        for(int i=0;i<fe_count(c);i++){float x,y;fe_origin(c,i,&x,&y);if(i!=rows && fe_parent(c,i)<0 && y<-80.f)fe_alpha(c,i,0);}
        fe_update(m,dt);fe_draw(m);fe_update(c,dt);fe_draw(c);
        return;
    }
    CareerContract k;career_contract(&k);
    snprintf(b,sizeof b,"Stage %d Status",cs->stage);fe_text(m,fe_find(m,0x3223a234u),b);
    int done=(k.choice<k.choice_need?k.choice:k.choice_need)+(k.sponsor<k.sponsor_need?k.sponsor:k.sponsor_need)+
             (k.url<k.url_need?k.url:k.url_need)+(k.dvd<k.dvd_need?k.dvd:k.dvd_need);
    int need=k.choice_need+k.sponsor_need+k.url_need+k.dvd_need,pct=need?done*100/need:100;
    static const char *const names[5]={"Region Completion Status:","World Event Wins:","Sponsor Event Wins:","URL Event Wins:","DVD Covers Required:"};
    int got[5]={pct,k.choice,k.sponsor,k.url,k.dvd},needs[5]={0,k.choice_need,k.sponsor_need,k.url_need,k.dvd_need};
    for(int i=0;i<5;i++) {
        fe_text(r,fe_find(r,0x4d2f5c61u+i),names[i]);
        if(i)snprintf(b,sizeof b,"%d/%d",got[i],needs[i]);else snprintf(b,sizeof b,"%d%%",pct);
        fe_text(r,fe_find(r,0x317ad6f2u+i),b);
    }
    {   /* the completion's slider: the tab along its track (235 wide at 110) */
        int tab=fe_find(r,0x8dafa5e4u);float x,y;fe_origin(r,tab,&x,&y);fe_moveto(r,tab,110.f-117.5f+235.f*pct/100.f,y);
        fe_alpha(r,fe_find(r,0xd734d0b8u),0);fe_alpha(r,fe_find(r,0xd734c2cfu),0);
    }
    fe_update(m,dt);fe_draw(m);fe_update(r,dt);fe_draw(r);
}
static void status_dvd_draw(FeScreen *m,FeScreen *d,float dt) {
    const CareerState *cs=career_state();char b[48];
    fe_text(m,fe_find(m,0x3223a234u),"DVD Unlocks");
    int n=0,shown=cs->stage>=2 && cs->stage<STAGE_N;
    for(int i=0;i<career_cover_count() && n<4 && shown;i++) {
        const CareerCover *v=career_cover(i);if(!v->dvd || v->stage!=cs->stage)continue;
        snprintf(b,sizeof b,"DVD Cover #%d",n+1);fe_text(d,fe_find(d,0x2734fb0eu+n),b);
        snprintf(b,sizeof b,"Achieve %.1f star rating",v->rating/10.f);fe_text(d,fe_find(d,0xb62767f2u+n),b);
        fe_alpha(d,fe_find(d,0x449a7d70u+n),cs->dvds>n?1.f:0.f);
        n++;
    }
    for(int i=0;i<4;i++)fe_alpha(d,fe_find(d,0x2a9afedu+i),i<n?1.f:0.f);   /* the covers' rows, as many as the stage has */
    fe_alpha(d,fe_find(d,0x42e73d71u),n?0.f:1.f);   /* "Not Available" */
    fe_update(m,dt);fe_draw(m);fe_update(d,dt);fe_draw(d);
}
static void status_draw(float dt) {
    FeScreen *m=statusm_s,*c=statusc_s;
    static FeScreen *ready;static int label[7],value[7];
    if(ready!=c) {   /* the rows top to bottom, each label with the value on its line */
        int lab[7],val[7];float ly[7],vy[7],x,sc;
        for(int k=0;k<7;k++){lab[k]=fe_find(c,0x566bf789u+k);val[k]=fe_find(c,0xa148528au+k);fe_place(c,lab[k],&x,&ly[k],&sc);fe_place(c,val[k],&x,&vy[k],&sc);}
        for(int k=0;k<7;k++){int best=k;for(int j=k;j<7;j++)if(ly[j]<ly[best])best=j;int t=lab[k];lab[k]=lab[best];lab[best]=t;float f=ly[k];ly[k]=ly[best];ly[best]=f;}
        for(int k=0;k<7;k++){label[k]=lab[k];value[k]=val[k];}   /* the values' hashes run top to bottom */
        (void)vy;
        /* a bar on Game Completion only, as the PS2 shows the page */
        for(int k=0;k<7;k++)if(k!=1) {
            static const uint32_t parts[]={0x654668ecu,0x4e4963ddu,0x7770beffu,0x77abeb28u,0xb830bb54u};
            for(int q=0;q<5;q++)fe_alpha(c,fe_find(c,parts[q]+k),0);
        }
        fe_alpha(m,fe_find(m,0x47ff4e7cu),0);fe_alpha(c,fe_find(c,0x47ff4e7cu),0);
        ready=c;
    }
    {   /* the pages: the arrows that lead somewhere, the dot along the top bar */
        static float tab_y;static int tab_ready;int tab=fe_find(m,0x3fbb7a4eu);
        if(!tab_ready){float x;fe_origin(m,tab,&x,&tab_y);tab_ready=1;}
        fe_moveto(m,tab,-275.f+275.f*status_page,tab_y);
        fe_alpha(m,fe_find(m,0x444969fdu),status_page>0?1.f:0.f);fe_alpha(m,fe_find(m,0x444969feu),status_page<2?1.f:0.f);
    }
    if(status_page==1){status_stage_draw(m,c,statusr_s,label,value,dt);return;}
    if(status_page==2 && statusd_s){status_dvd_draw(m,statusd_s,dt);return;}
    /* the first page: every row of the stats back (the stage page hides some) */
    for(int k=0;k<7;k++){fe_alpha(c,fe_find(c,0x28887216u+k),1);fe_alpha(c,label[k],1);fe_alpha(c,value[k],1);}
    for(int i=0;i<fe_count(c);i++){float x,y;fe_origin(c,i,&x,&y);if(fe_parent(c,i)<0 && y<-80.f)fe_alpha(c,i,1);}   /* the Visual Rating strip (and the rows' group) */
    {static const uint32_t parts[]={0x654668ecu,0x4e4963ddu,0x7770beffu,0x77abeb28u,0xb830bb54u};
     for(int q=0;q<5;q++)fe_alpha(c,fe_find(c,parts[q]+1),1);}
    const CareerState *cs=career_state();
    int won=0,raced=0;for(int k=0;k<career_count();k++){if(cs->best[k]==1)won++;if(cs->best[k])raced++;}
    char b[7][32];
    snprintf(b[1],32,"%d %%",career_count()?won*100/career_count():0);
    snprintf(b[2],32,"%u",cs->money);snprintf(b[3],32,"%u",cs->spent);snprintf(b[4],32,"%u",cs->races);
    snprintf(b[5],32,"%d",won);snprintf(b[6],32,"%.1f",cs->races?100.f*won/cs->races:0.f);
    static const char *const names[7]={"Overall Status","Game Completion Status:","Bank:","Total Spent On Car:","Races Entered:","Overall Wins:","Win Percent:"};
    for(int k=0;k<7;k++){fe_text(c,label[k],names[k]);fe_text(c,value[k],k?b[k]:"");}
    fe_text(m,fe_find(m,0x3223a234u),"Overall Career Statistics");   /* the header between the arrows; the title stays Career Status */
    {int pct=career_count()?won*100/career_count():0;int fill=fe_find(c,0x4e4963deu);   /* Game Completion's bar */
     fe_alpha(c,fill,pct?1.f:0.f);fe_alpha(c,fe_find(c,0x77abeb29u),pct?1.f:0.f);fe_size(c,fill,16.f*pct/12.f,5.8f);}
    /* the stars: the visual rating in halves (look_rating: 0-100). Each
     * star has two half images at its place (UI_Status_Career.fng): the
     * left half (unturned) and its mirror; a half star shows the left one. */
    int halves=look_rating(&cs->look)/5;
    for(int k=0;k<10;k++) {
        uint32_t left=k<4?0x413f8f29u+2*k:k==4?0x413f8f31u:0x6931747au+2*(k-5),mirror=k<4?0x413f8f2au+2*k:k<9?0x69317479u+2*(k-4):0x6931749au;
        fe_alpha(c,fe_find(c,0x6ec2f0deu+k),k<halves/2?1.f:0.f);
        fe_alpha(c,fe_find(c,left),k==halves/2 && halves&1?1.f:0.f);
        fe_alpha(c,fe_find(c,mirror),0.f);
    }
    fe_update(m,dt);fe_draw(m);fe_update(c,dt);fe_draw(c);
}

/* The pause's Options (UI_PauseOptionsMain.fng): the PS2's carousel of
 * Audio, Gameplay and Player; the port has the Audio page (UI_PauseOptions.
 * fng): the PS2's seven volumes, Up/Down to pick, Left/Right in tenths, kept
 * in options.sav. Its rows are the port's over the page's frame. */
static const char *const OPT_NAMES[7]={"Master Volume","Menu Music Volume","Game Music Volume","Speech & Movie Volume","Sound Effects Volume","Tire Volume","Engine Volume"};
static float opt_vol[7]={1,.7f,1,1,1,1,1};static int opt_row;   /* the PS2's: Menu Music at 7 of 10, the rest full */
/* A drag or a drift under way: no songs, the street's ambience in their
 * place, as the original's EAXS_PFController::EAXS_UpdateMusic (with
 * g_tweakIsDragRace or g_tweakIsDriftRace, the ambient streams). */
static int race_music_off(void) { return race.state!=RACE_OFF && (race.mode==RMODE_DRAG || race.mode==RMODE_DRIFT); }
static void opts_apply(int in_menus) {
    audio_bus(AUDIO_MASTER,opt_vol[0]);audio_bus(AUDIO_MUSIC,in_menus?opt_vol[1]:debug_view&4194304 || race_music_off()?0:opt_vol[2]);
    audio_bus(AUDIO_SPEECH,opt_vol[3]);audio_bus(AUDIO_SFX,opt_vol[4]);audio_bus(AUDIO_ENGINE,opt_vol[6]);
}
/* options.sav: the seven volumes (f32), then 'N2OP', u8 count, the choices */
static void opts_load(void) {
    opts_loaded=1;
    opt_val[OP_UNITS]=strcmp(lang_code(),"en")!=0;   /* never chosen: metric but in English (LanguageHasChanged) */
    FILE *f=fopen("options.sav","rb");if(!f)return;
    float v[7];if(fread(v,sizeof v,1,f)==1)for(int k=0;k<7;k++)opt_vol[k]=v[k]<0?0:v[k]>1?1:v[k];
    char m[4];uint8_t n;uint8_t c[64];
    if(fread(m,1,4,f)==4 && !memcmp(m,"N2OP",4) && fread(&n,1,1,f)==1 && n<=sizeof c && fread(c,1,n,f)==n)
        for(int k=0;k<n && k<OP_N;k++)opt_val[k]=c[k]<11?c[k]:opt_val[k];
    fclose(f);
    fps_apply();wide_apply();
    if(opt_val[OP_MOVIE]>=MOVIE_ASPECTS)opt_val[OP_MOVIE]=MOVIE_STRETCH;
    if(opt_val[OP_OVERLAY]>1)opt_val[OP_OVERLAY]=0;   /* On */
    if(opt_val[OP_OPENCITY]>1)opt_val[OP_OPENCITY]=0;   /* Off */
    movie_aspect=opt_val[OP_MOVIE];
}
static void opts_save(void) {
    FILE *f=fopen("options.sav","wb");if(!f)return;
    uint8_t n=OP_N;fwrite(opt_vol,sizeof opt_vol,1,f);fwrite("N2OP",1,4,f);fwrite(&n,1,1,f);fwrite(opt_val,1,OP_N,f);fclose(f);
}
static void opts_open(void) {
    if(!optsm_s){optsm_s=fe_load("poptsm.n2ui");opts_s=fe_load("popts.n2ui");
        if(optsm_s){fe_show(optsm_s,1,1);fe_widen(optsm_s,480.f/640.f);}
        if(opts_s){fe_show(opts_s,1,1);fe_widen(opts_s,480.f/640.f);}
        ui_open=NULL;}
    if(!optsm_s || !opts_s)return;
    menu=MENU_OPTS;
}
enum { PAGE_AUDIO,PAGE_VIDEO,PAGE_GAMEPLAY,PAGE_PLAYER,PAGE_DEBUG };   /* the Options pages (below: option_page); Debug the port's, after the original's */
static int opt_page;
static int audio_input(uint32_t pressed);
static int pause_opt;   /* the pause's Options carousel */
static void opts_input(uint32_t pressed) {
    if(menu==MENU_OPTS) {   /* the carousel: Audio, Gameplay, Player */
        static const int pages[4]={PAGE_AUDIO,PAGE_GAMEPLAY,PAGE_PLAYER,PAGE_DEBUG};
        if(pressed&PSP_CTRL_LEFT)pause_opt=(pause_opt+3)%4;
        if(pressed&PSP_CTRL_RIGHT)pause_opt=(pause_opt+1)%4;
        if(pressed&PSP_CTRL_CROSS){menu=MENU_AUDIO;opt_row=0;opt_page=pages[pause_opt];}
        else if(pressed&(PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE)){int n;const PauseItem *it=pause_items(&n);menu=MENU_MAIN;menu_sel=0;for(int k=0;k<n;k++)if(it[k].action==P_OPTIONS)menu_sel=k;}   /* back on Options */
        else if(pressed&PSP_CTRL_START)menu=MENU_OFF;
        return;
    }
    if(audio_input(pressed))menu=pressed&PSP_CTRL_START?MENU_OFF:MENU_OPTS;
}
/* The Options pages (UI_Options.fng in the menus, UI_PauseOptions.fng the
 * pause's Audio), as the PS2's: Audio's seven volumes and its Audio Mode
 * (the PS2's Dolby Pro Logic II the PSP's stereo); Video, Gameplay and
 * Player's choices (opt_val), each between its arrows. The rows over the
 * package's panel, the picked one dark as the game's Highlight. */
typedef struct { const char *name;uint8_t op,n;const char *const *vals; } OptRow;   /* n 0: a slider 0-10 */
static const char *const V_ONOFF[2]={"On","Off"},*const V_OFFON[2]={"Off","On"},*const V_UNITS[2]={"MPH","KM/H"},*const V_DIFF[3]={"Easy","Medium","Hard"},
    *const V_MAP[2]={"Rotate","Static"},*const V_SAVE[3]={"Autosave","Prompt","Off"},*const V_TRANS[2]={"Auto","Manual"},
    *const V_CAM[CAM_OPTIONS]={"Bumper","Hood","Close","Far","Close (PC)","Far (PC)"},*const V_SPLIT[2]={"Leader","Off"},*const V_DETAIL[4]={"70 m","90 m","110 m","130 m"},*const V_FPS[2]={"30 fps","60 fps"},
    *const V_MOVIE[MOVIE_ASPECTS]={"Stretched","4:3","Cropped"};
/* The port's rows, not the PS2's (not on the PSP-1000's heap, small_memory:
 * hidden): Detail Distance, how far the buildings keep their near models
 * (the cap of near_update's swap: 70 m the original's), and Frame Rate, 30
 * (two vblanks a street frame, as ever) or 60 (one, when the frame fits:
 * the simulation keeps its fixed 60 Hz steps either way). */
/* The PS2's Screen X and Screen Y (VOScreenPosHoriz, VOScreenPosVert: the
 * TV picture moved +-15 pixels, eSetScreenDisplayOffsets, to centre it
 * inside a CRT's overscan; the GameCube's Screen Scale instead) are not
 * here: the PSP's LCD shows the whole frame, so a shift would only cut an
 * edge off (beta issue 145). Their saved values stay in options.sav, unread.
 * Frame Rate only in an emulator (kemulator:, below): on a PSP the GE alone
 * takes over 16.7 ms in every stretch measured (OTIMIZACAO.md), so 60 never
 * came and the row changed nothing; there the game keeps 30, whatever an
 * old options.sav says. */
/* Movie Aspect, the port's too (Jussimir's, 12/11/2026): the original's
 * movies are 4:3 and the PSP's screen 16:9; Stretched (the default) over
 * the whole screen, 4:3 whole between black bars (the original's shape,
 * the port up to v0.3.0), Cropped filling the screen, its top and bottom
 * cut (movie.c movie_crop). Below the rows that change with the PSP, so those above
 * keep their places on each PSP. */
/* Brightness, the port's as well (Jussimir's, 12/11/2026): the original
 * has none on any console (the PS2's page: Widescreen, Screen X, Screen Y;
 * the GameCube's and the Xbox's: Widescreen, Screen Scale). Its page only
 * shows the colour calibration test (ColorCal_Logo, ColorCal_Blurb: the
 * logo dark on black, "lower the brightness of your television"), meant
 * for the TV's own knob, which the PSP's screen lacks. The row is that
 * knob: a slider under Widescreen, its middle (the default, an old
 * options.sav too) the frame as drawn; each step down takes bright_step
 * off the black level (the logo sinks into the box), each step up lifts
 * the shadows as much, the whites kept (bright_pass). */
/* Debug Overlay, the port's too (Jussimir's, 15/11/2026): the lines over
 * the picture that the test builds keep (overlay_shown), On by default;
 * Off hides them, the game's HUD kept. Below Movie Aspect, so the rows
 * above keep their places. Open Bayview, the last row (a tester's wish,
 * beta issue 203; Off by default): the free roam's barriers of the last
 * stage whatever the career's (roam_stage). */
static const OptRow VIDEO_ROWS[]={{"Widescreen",OP_EXPAND,2,V_ONOFF},{"Brightness",OP_BRIGHT,0,NULL},{"Detail Distance",OP_DETAIL,4,V_DETAIL},{"Frame Rate",OP_FPS,2,V_FPS},{"Movie Aspect",OP_MOVIE,MOVIE_ASPECTS,V_MOVIE}};
static const OptRow DEBUG_ROWS[]={{"Debug Overlay",OP_OVERLAY,2,V_ONOFF},{"Open Bayview",OP_OPENCITY,2,V_OFFON}};   /* Options > Debug (the menus' and the pause's): the port's test options */
static int in_emulator;   /* PPSSPP (kemulator:'s IS_EMULATOR, set in main); 0 on a PSP and whenever unsure */
static int fps_60(void) { return opt_val[OP_FPS] && !small_memory && in_emulator; }
static void fps_apply(void) { street_vblanks=fps_60()?1:2; }
/* Widescreen: On (the default) the original's layout with its Widescreen on
 * (the menus and dialogs in the 4:3 frame in the middle, the HUD at the
 * screen's edges; beta issue 119); Off the menus spread across the whole
 * screen, as the original with the option off on a wide TV (the port up to
 * v0.2.5). widescreen-off.txt forces Off (comparisons). */
static int wide_test;
static void wide_apply(void) {
    fe_widescreen_off=opt_val[OP_EXPAND] || wide_test;
    music_card_menu_x=fe_widescreen_off?MUSIC_MENU_X_SPREAD:MUSIC_MENU_X;
}
/* 60 fps chosen: 30 while the loader is behind and a second after. At 60 in
 * the calibrated PPSSPP the loader thread, below the game, got too little of
 * the 16.7 ms frames: the 4101's wheels met cells without their collision
 * (1051 frames unknown, 24 missing). */
static int fps_hold;static unsigned fps_held_frames;
static void fps_frame(void) {
    if(!fps_60())return;
    if(world_loader_behind())fps_hold=60;else if(fps_hold>0)fps_hold--;
    street_vblanks=fps_hold>0?2:1;fps_held_frames+=fps_hold>0;
}
static const OptRow GAME_ROWS[]={{"Jump Camera",OP_JUMPCAM,2,V_ONOFF},{"Rearview Mirror",OP_MIRROR,2,V_ONOFF},{"Speedometer Units",OP_UNITS,2,V_UNITS},
    {"Career Difficulty",OP_DIFF,3,V_DIFF},{"Explore Map Mode",OP_EXPLOREMAP,2,V_MAP},{"Race Map Mode",OP_RACEMAP,2,V_MAP},{"Save",OP_SAVE,3,V_SAVE}};
static const OptRow PLAYER_ROWS[]={{"Transmission",OP_TRANS,2,V_TRANS},{"Stability Control",OP_STAB,2,V_OFFON},{"Camera",OP_CAMERA,CAM_OPTIONS,V_CAM},
    {"Gauges",OP_GAUGES,2,V_ONOFF},{"Race Position",OP_POSITION,2,V_ONOFF},{"Lap Info",OP_LAPINFO,2,V_ONOFF},{"Split Time",OP_SPLIT,2,V_SPLIT}};
static const char *const PAGE_NAMES[5]={"Audio","Video","Gameplay","Player","Debug"};
static const OptRow *page_rows(int page,int *n) {
    if(page==PAGE_VIDEO) {   /* Widescreen, Brightness, Detail Distance and Frame Rate where they are (above), Movie Aspect */
        static OptRow r[5];int k=0;
        r[k++]=VIDEO_ROWS[0];r[k++]=VIDEO_ROWS[1];if(!small_memory)r[k++]=VIDEO_ROWS[2];
        if(!small_memory && in_emulator)r[k++]=VIDEO_ROWS[3];
        r[k++]=VIDEO_ROWS[4];*n=k;return r;
    }
    if(page==PAGE_DEBUG){*n=2;return DEBUG_ROWS;}
    if(page==PAGE_GAMEPLAY){*n=7;return GAME_ROWS;}
    if(page==PAGE_PLAYER){*n=7;return PLAYER_ROWS;}
    *n=8;return NULL;   /* Audio: the volumes and its mode */
}
/* The original's option rows (UIWidgetMenu over UI_Options.fng and
 * UI_PauseOptions.fng): the picked row's OPTION_BACKING (U2_Menu_Box_Layer1
 * between two U2_Menu_Text_Corner_layer1 caps, the left one turned; grey 192
 * at 200), its arrows (U2_Menu_Arrow_White at 150, the left one turned:
 * eWidgetArrowImages 1), and cSlider::DrawHorizontal's bar: U2_temp_sliderBG
 * black at 65, the green fill (99, 178, 34) with its U2_temp_slider_fill_corner
 * ends (the far one only when full) and the round U2_SliderBar_Tab where the
 * value is. Sizes in FEng units at the uniform scale, as icons keep. */
#define OPT_K (272.f/480.f)
/* Where the original's rows fall (UI_Options.fng's TITLE_MASTER and
 * DATA_MASTER grid, measured on its Audio page by OpenUG2's clean-room
 * spec, docs/cleanroom-settings/SPEC_GUI.md 2.3): a pitch of 36 FEng units,
 * the first row at -126.2; the labels from x -268.9, the backing -286.2 to
 * 261.8, the arrows at 6.2 and 246.2, the value at 127.8, the slider's fill
 * from 54.6 to the tab at 196.6. OPT_X: an FEng x in ux's 480 frame. */
#define OPT_X(x) (240.f+(x)*.75f)
#define OPT_Y0 (136.f-126.2f*OPT_K)
#define OPT_PITCH (36.f*OPT_K)
static void opt_backing(FeScreen *s,float x0,float x1,float y,float h) {
    uint32_t box=fe_hash("U2_MENU_BOX_LAYER1"),cap=fe_hash("U2_MENU_TEXT_CORNER_LAYER1"),c=0xc8c0c0c0u;
    if(!fe_has_texture(s,box) || !fe_has_texture(s,cap)){ui_rect(x0,y-h*.5f,x1-x0,h,0xaf404040);return;}   /* the pause's package: no backing of its own */
    fe_icon_flipped(s,cap,x0+h*.5f,y,h,h,c);
    fe_icon(s,box,(x0+x1)*.5f,y,x1-x0-2*h,h,c);
    fe_icon(s,cap,x1-h*.5f,y,h,h,c);
}
static void opt_arrows(FeScreen *s,float xl,float xr,float y) {
    uint32_t a=fe_hash("U2_MENU_ARROW_WHITE");float d=24*OPT_K;
    if(!fe_has_texture(s,a)){fe_string_align(s,0,xl,y,.42f,0xffc0c0c0,"<",1);fe_string_align(s,0,xr,y,.42f,0xffc0c0c0,">",1);return;}
    fe_icon_flipped(s,a,xl,y,d,d,0x96ffffffu);fe_icon(s,a,xr,y,d,d,0x96ffffffu);
}
static void opt_slider(FeScreen *s,float x0,float w,float y,float f) {
    f=f<0?0:f>1?1:f;
    uint32_t end=fe_hash("U2_TEMP_SLIDER_FILL_CORNER"),green=0xff22b263u;float e=15*OPT_K,fh=7*OPT_K,x=x0+w*f;
    fe_icon(s,fe_hash("U2_TEMP_SLIDERBG"),x0+w*.5f+3*OPT_K,y,w+e+6*OPT_K,32*OPT_K,0x41000000u);   /* the track to 202.9 */
    if(f>0) {
        fe_icon(s,end,x0,y,e,e,green);
        ui_rect(x0,y-fh*.5f,w*f,fh,green);
        if(f>=.98f)fe_icon_flipped(s,end,x,y,e,e,green);
    }
    fe_icon(s,fe_hash("U2_SLIDERBAR_TAB"),x,y,16*OPT_K,16*OPT_K,0xffffffffu);
}
enum { VIDEO_VISIBLE=4 };   /* Video's rows over its calibration box */
static void option_page(FeScreen *s,float dt) {
    static FeScreen *ready;
    if(ready!=s) {
        static const uint32_t hide[]={0x044f9b51u,0x044f9b52u,0x059980d8u,0x059980d9u,0x3fbb7a4eu,0x444969fdu,0x444969feu,0x4e4963ddu,0x4e4963deu,0x4e4963dfu,0x4e4963e0u,0x4e4963e1u,0x4e4963e2u,0x4e4963e3u,
            0x654668ecu,0x654668edu,0x654668eeu,0x654668efu,0x654668f0u,0x654668f1u,0x654668f2u,0x7770beffu,0x7770bf00u,0x7770bf01u,0x7770bf02u,0x7770bf03u,0x7770bf04u,0x7770bf05u,
            0x77abeb28u,0x77abeb29u,0x77abeb2au,0x77abeb2bu,0x77abeb2cu,0x77abeb2du,0x77abeb2eu,0x7b2dd6dbu,0x7b2dd6dcu,0x7b2dd6ddu,0x7b2dd6deu,0x7b2dd6dfu,0x7b2dd6e0u,0x7b2dd6e1u,
            0x9b483b01u,0x9b483b02u,0x9b483b03u,0x9b483b04u,0x9b483b05u,0x9b483b06u,0x9b483b07u,0x9b483b08u,0x9b483b09u,0x9c7c3c73u,0xb2980ba8u,0xb2980ba9u,0xb2980baau,0xb2980babu,
            0xb2980bacu,0xb2980badu,0xb2980baeu,0xb2980bafu,0xb2980bb0u,0xc07219cfu,0xc128b184u,0xa753c46cu,0x47ff4e7cu,
            0x608bb8c8u,0x8e1bea84u,0xe54c30beu,0x7326e44cu,0xc90dc4abu,0x97b71ddeu,0x2bac0ceeu};   /* the menus' UI_Options: its brightness test, Player 1, Player Select, the bar's arrows */
        for(unsigned k=0;k<sizeof hide/sizeof *hide;k++)fe_alpha(s,fe_find(s,hide[k]),0);
        ready=s;
    }
    int video=opt_page==PAGE_VIDEO;   /* its brightness test, as the PS2's */
    int vn;const OptRow *vrows=video?page_rows(PAGE_VIDEO,&vn):NULL;
    int debug=opt_page==PAGE_DEBUG;
    if(debug){vrows=page_rows(PAGE_DEBUG,&vn);}
    int detail_row=(video || debug) && opt_row<vn && vrows[opt_row].op!=OP_EXPAND && vrows[opt_row].op!=OP_BRIGHT;   /* the port's rows (Detail Distance, Frame Rate, Movie Aspect; Debug's) picked: its note in the test's place; Widescreen shows the test, as the PS2's, and Brightness, whose test it is */
    fe_alpha(s,fe_find(s,0x608bb8c8u),video);fe_alpha(s,fe_find(s,0x8e1bea84u),video && !detail_row);fe_alpha(s,fe_find(s,0xe54c30beu),video && !detail_row);   /* a note: its light lines on the test's dark box, the blurb and logo out */
    fe_alpha(s,fe_find(s,0x7326e44cu),opt_page==PAGE_PLAYER);   /* "Player 1" */
    int paused=s==opts_s;   /* the pause's page: "PAUSE OPTIONS" and the page on the right, no Audio Mode */
    static const char *const RIGHT[5]={"AUDIO","GAMEPLAY","PLAYER","PLAYER","DEBUG"};
    fe_text(s,fe_find(s,0x98643dfeu),RIGHT[opt_page]);if(!paused)fe_text(s,fe_find(s,0x42adb44cu),PAGE_NAMES[opt_page]);
    fe_text(s,fe_find(s,0xeb406fecu),profile_label());fe_alpha(s,fe_find(s,0xeb3a688au),0);
    fe_update(s,dt);fe_draw(s);
    int n;const OptRow *rows=page_rows(opt_page,&n);
    if(!rows && paused)n=7;
    /* The menus' page (UI_Options) as the original's: its names and values
     * dark grey (50) on the light panel, the picked row's pulsing light
     * green (204, 244, 138: its Highlight, 0.44 s in, held, 0.44 s out of
     * 1.2 s). The pause's own (UI_PauseOptions, a dark panel) keeps its
     * light text, its picked row green. */
    static float pulse;pulse=fmodf(pulse+dt,1.2f);
    float pa=pulse<.44f?pulse/.44f:pulse<.76f?1.f:(1.2f-pulse)/.44f;
    uint32_t lit=paused?0xff8af4ca:(uint32_t)(pa*255.f+.5f)<<24|0x8af4ccu,dim=paused?0xffe1e1e1:0xff323232u;
    /* Video's rows above the calibration box: four at most (a PSP with the
     * extra memory has five, the emulator's six: Frame Rate too), the list scrolled to keep the picked one in
     * them, as the original's menus scroll (UIWidgetMenu). */
    int top=0,shown_n=n;
    if(video && n>VIDEO_VISIBLE){shown_n=VIDEO_VISIBLE;top=opt_row>=VIDEO_VISIBLE?opt_row-VIDEO_VISIBLE+1:0;}
    for(int j=0;j<shown_n;j++) {
        int k=top+j;
        float y=OPT_Y0+j*OPT_PITCH,h=35*OPT_K;uint32_t on=k==opt_row,tc=on?lit:dim;
        if(on)opt_backing(s,ux(OPT_X(-286.2f)),ux(OPT_X(261.8f)),y,h);
        fe_string_align(s,0,ux(OPT_X(-268.9f)),y,.42f,tc,rows?rows[k].name:k<7?OPT_NAMES[k]:"Audio Mode",0);
        if(on)opt_arrows(s,ux(OPT_X(6.2f)),ux(OPT_X(246.2f)),y);
        if(!rows) {   /* Audio: a slider a row (no number: the original's has no SLIDER_VALUE) */
            if(k==7){fe_string_align(s,0,ux(OPT_X(127.8f)),y,.42f,tc,"Stereo",1);break;}
            opt_slider(s,ux(OPT_X(54.6f)),uw(OPT_X(196.6f)-OPT_X(54.6f)),y,opt_vol[k]);
            continue;
        }
        const OptRow *r=&rows[k];int v=r->op==OP_DETAIL?detail_index():opt_val[r->op];
        if(!r->n)opt_slider(s,ux(OPT_X(54.6f)),uw(OPT_X(196.6f)-OPT_X(54.6f)),y,v/10.f);   /* Screen X, Y */
        else fe_string_align(s,0,ux(OPT_X(127.8f)),y,.42f,tc,r->vals[v<r->n?v:0],1);
    }
    if(detail_row) {   /* the note, as the test's two lines */
        const char *l1,*l2;
        int op=vrows[opt_row].op;
        if(op==OP_OPENCITY) {
            if(opt_val[OP_OPENCITY]){l1="All of Bayview open to explore, no barriers.";l2="Your career, races and shops stay as they are.";}
            else{l1="The city opens area by area as the career goes on,";l2="as in the original.";}
        } else if(op==OP_OVERLAY) {
            if(opt_val[OP_OVERLAY]){l1="The frame rate and the debug lines are hidden.";l2="The game still keeps its bug report files.";}
            else{l1="The frame rate and the debug lines on screen:";l2="keep them in your photos for bug reports.";}
        } else if(op==OP_MOVIE) {
            static const char *const note[MOVIE_ASPECTS][2]={{"The movies fill the whole screen,","stretched to its width."},
                {"The movies whole, as the original's 4:3,","with black bars at the sides."},{"The movies fill the whole screen at their shape:","the top and bottom of the picture are cut off."}};
            int a=opt_val[OP_MOVIE]<MOVIE_ASPECTS?opt_val[OP_MOVIE]:0;l1=note[a][0];l2=note[a][1];
        } else if(op==OP_DETAIL) {
            int m=detail_cap_m();static char b[64];
            if(m<=70){l1="Buildings keep their detail out to 70 m, as the original.";l2="The smoothest frame rate.";}
            else{snprintf(b,sizeof b,"Buildings keep their detail out to %d m, less when",m);l1=b;l2="a frame runs late. It may lower the frame rate.";}
        } else if(opt_val[OP_FPS]){l1="60 fps when the frame has room, 30 when it does not:";l2="it may change from moment to moment.";}
        else{l1="30 fps, steady: the frame rate the game was made for.";l2="";}
        uint32_t nc=video || paused?0xffe1e1e1:dim;   /* Debug's on the page's own panel: its rows' dark grey (the pause's light) */
        fe_string_align(s,0,240,158,.42f,nc,l1,1);
        if(*l2)fe_string_align(s,0,240,174,.42f,nc,l2,1);
    }
}
/* Up/Down a row, Left/Right its value (a tenth on a slider); 1 when it closes (saved) */
static int audio_input(uint32_t pressed) {
    int n;const OptRow *rows=page_rows(opt_page,&n);
    if(!rows && menu==MENU_AUDIO)n=7;   /* the pause's Audio: no Audio Mode */
    if(pressed&PSP_CTRL_UP)opt_row=(opt_row+n-1)%n;
    if(pressed&PSP_CTRL_DOWN)opt_row=(opt_row+1)%n;
    if(pressed&(PSP_CTRL_LEFT|PSP_CTRL_RIGHT)) {
        int d=pressed&PSP_CTRL_LEFT?-1:1;
        if(!rows && opt_row<7) {
            float v=opt_vol[opt_row]+d*.1f;
            opt_vol[opt_row]=roundf((v<0?0:v>1?1:v)*10)/10;
        } else if(rows) {
            const OptRow *r=&rows[opt_row];uint8_t *v=&opt_val[r->op];
            if(r->op==OP_DETAIL)*v=(uint8_t)detail_index();   /* never chosen: from the value shown */
            if(!r->n)*v=(uint8_t)(*v+d<0?0:*v+d>10?10:*v+d);else *v=(uint8_t)((*v+r->n+d)%r->n);
            if(r->op==OP_CAMERA){cam.view=option_view();cam.ready=0;}   /* the pause's: the race on in it */
            if(r->op==OP_FPS)fps_apply();
            if(r->op==OP_EXPAND)wide_apply();
            if(r->op==OP_MOVIE)movie_aspect=opt_val[OP_MOVIE];
        }
    }
    if(pressed&(PSP_CTRL_TRIANGLE|PSP_CTRL_CIRCLE|PSP_CTRL_START)){opts_save();return 1;}
    return 0;
}
static void opts_draw(float dt) {
    if(menu==MENU_OPTS) {
        static const char *const icons[4]={"OPTIONS_ICON_AUDIO","OPTIONS_ICON_GAMEPLAY_S","OPTIONS_ICON_PLAYER_SET","OPTIONS_ICON_DEBUG"},*const titles[4]={"Audio","Gameplay","Player","Debug"};
        fe_text(optsm_s,fe_find(optsm_s,0x42adb44cu),"PAUSE OPTIONS");
        fe_alpha(optsm_s,fe_find(optsm_s,0x47ff4e7cu),0);
        ui_dt=dt;carousel(optsm_s,&CAROUSEL,icons,titles,4,pause_opt);
        fe_update(optsm_s,dt);fe_draw(optsm_s);
        return;
    }
    option_page(opts_s,dt);   /* the page the carousel opened */
}

/* ------------------------------------------------------------ the stages */
/* Sponsorship (UI_Sponsorship_new.fng): a contract stage starts with the
 * pick of a sponsor among those the previous stage's reputation per race
 * earned (sponsor_draw, below the SMS reader whose scroller it shares). */
/* Left-aligned lines broken at the width (the font's own advances); a
 * new line in the text leaves a blank one, as the PS2's paragraphs. */
/* align: 0 left of x, 1 centred on it; draw 0 only counts; the lines used */
static int wrap_text(FeScreen *s,int font,float x,float y,float w,float scale,float lh,uint32_t col,const char *text,int max_lines,int align,int draw) {
    char line[128];int lines=0;const char *p=text;
    while(*p && lines<max_lines) {
        int n=0,cut=-1;
        while(p[n] && p[n]!='\n' && n<127) {
            if(p[n]==' ')cut=n;
            memcpy(line,p,n+1);line[n+1]=0;
            if(fe_string_width(s,font,scale,line)>w && cut>0){n=cut;break;}
            n++;
        }
        memcpy(line,p,n);line[n]=0;
        if(n && draw)fe_string_align(s,font,x,y+lines*lh,scale,col,line,align);
        if(n)lines++;
        p+=n;
        if(*p=='\n'){while(*p=='\n')p++;lines++;}   /* a paragraph: one blank line */
        while(*p==' ')p++;
    }
    return lines;
}
static void wrap_left(FeScreen *s,int font,float x,float y,float w,float scale,float lh,uint32_t col,const char *text,int max_lines) {
    wrap_text(s,font,x,y,w,scale,lh,col,text,max_lines,0,1);
}
static void sponsor_open(void) {
    sponsor_n=career_sponsors_offered(sponsor_list);sponsor_sel=sponsor_scroll=0;
    if(!sponsor_n){sponsor_retry_waiting=0;return;}
    if(!sponsor_s) {
        /* The street retries a pending contract every frame. Refusing its
         * screen must never choose/sign/save a contract for the player. */
        uint32_t now=sceKernelGetSystemTimeLow();
        if(sponsor_retry_waiting && (uint32_t)(now-sponsor_retry_since)<1000000u)return;
        sponsor_s=fe_load("sponsor.n2ui");ui_open=NULL;
        if(!sponsor_s) {
            sponsor_retry_since=now;sponsor_retry_waiting=1;
            race_say("Unable to open sponsors. Retrying.");race.note_timer=3.f;
            return;
        }
        fe_show(sponsor_s,1,1);fe_widen(sponsor_s,480.f/640.f);   /* across the width, as the menus */
    }
    sponsor_retry_waiting=0;
    menu=MENU_SPONSOR;ui_seen.sponsors++;
    {   /* Rachel (the game's 0x132250): the first contract's (0x8000000,
         * then 0x20000 4 s on), later once a session (0x10) */
        static int said;
        if(career_state()->stage==2 && career_state()->sponsor<0){career_said+=audio_speech_match("Career",0,27,5,-1);say_later(1.f,1,"Career",0,17,5,-1);}   /* HandleSponsorSelect: the contract's terms a second of free roam on (its timer event 11) */
        else if(!said)career_said+=audio_speech_match("Career",0,4,5,-1);
        said=1;
    }
}
static void contract_lines(char out[4][64]) {
    CareerContract c;career_contract(&c);
    /* The compact PSP summary uses the disc's labels, not English sentences
     * looked up after the counts have already been inserted. */
    if(c.finish_need){snprintf(out[0],64,"%s %d/%d",lang_or(0xb1ee4ca9u,"Completed"),c.finish,c.finish_need);out[1][0]=out[2][0]=out[3][0]=0;return;}
    snprintf(out[0],64,"%s %d/%d",lang_or(0x80b8267cu,"URL"),c.url,c.url_need);
    snprintf(out[1],64,"%s %d/%d",lang_or(0x34e6adbau,"Sponsor"),c.sponsor,c.sponsor_need);
    snprintf(out[2],64,"%s %d/%d",lang_or(0xa1fa715fu,"Wins"),c.choice,c.choice_need);
    snprintf(out[3],64,"%s %d/%d",lang_or(0x653b26c4u,"DVD covers"),c.dvd,c.dvd_need);
}
static const char *menu_save_title(int confirmed) {
    /* uiCareerCrib::Setup uses the Save label (03ec7395). The PSP keeps
     * its confirmed-save notice, composed from the disc's words. */
    if(!confirmed)return lang_or(0x03ec7395u,"Save Game");
    const char *save=lang_text(0x03ec7395u),*done=lang_text(0xb1ee4ca9u);
    if(!save || !done)return "Game Saved";
    static char text[96];snprintf(text,sizeof text,"%s: %s",save,done);return text;
}
static void career_status_text(char *out,size_t size) {
    const CareerState *cs=career_state();const CareerSponsor *sp=career_sponsor(cs->sponsor);
    if(career_done()) {
        snprintf(out,size,"%s: %s   %s %u",lang_or(0x5e7e1192u,"Career"),lang_or(0xb1ee4ca9u,"Completed"),lang_or(0xa49003bau,"Total Reputation"),cs->rep);
        return;
    }
    char stage[40],sms[64],number[16];
    snprintf(number,sizeof number,"%d",cs->stage);lang_format(stage,sizeof stage,"Stage %d",number);
    snprintf(number,sizeof number,"%d",career_sms_new());lang_format(sms,sizeof sms,"%d unread messages",number);
    snprintf(out,size,"%s%s%s   %s %.1f   %s",stage,sp?"   ":"",sp?sp->name:"",lang_or(0x04b28917u,"Visual Rating"),look_rating(&cs->look)/10.f,sms);
}
/* The SMS mailbox (UI_SMS_Mailbox.fng, SMSMailboxViewer), as the
 * original's: five mailboxes on L1/R1 (MailboxCategories: Inbox, Game
 * Tips, Special Events, Rachel, Unlocks), each a list of "Subject: ..."
 * lines with an envelope in the message's colour, open once read; Up/Down
 * pick, X reads, Square deletes, Triangle back. A message waits in the
 * Inbox until it is read and the player has gone back to the street
 * (SMSMessageQueue::MarkAllReadMessagesSortable), then it is in its own
 * mailbox. Select opens it in free roam; with a single unread message,
 * straight into that one (SummonSMSMailbox). */
static uint8_t sms_filed[SMS_MAX/8];   /* read before this visit: in its own mailbox */
static void sms_list_build(void) {
    sms_n=0;
    for(int i=career_sms_count()-1;i>=0;i--) {   /* the newest first */
        if(!career_sms_listed(i))continue;
        int filed=sms_filed[i>>3]>>(i&7)&1;
        if(filed?career_sms_mail(i)->box==sms_box:sms_box==SMS_BOX_INBOX)sms_list[sms_n++]=i;
    }
    if(sms_sel>=sms_n)sms_sel=sms_n?sms_n-1:0;
}
static void sms_open(void) {
    if(!sms_s){sms_s=fe_load("sms.n2ui");if(sms_s){fe_show(sms_s,1,1);fe_widen(sms_s,480.f/640.f);}ui_open=NULL;}   /* across the width, as the menus */
    if(!tip_s){tip_s=fe_load("msgdlg.n2ui");if(tip_s){fe_show(tip_s,1,1);fe_widen(tip_s,480.f/640.f);}ui_open=NULL;}
    sms_scroll=0;sms_lines=0;sms_delete_ask=0;
    memset(sms_filed,0,sizeof sms_filed);
    for(int i=0;i<career_sms_count() && i<SMS_MAX;i++)if(career_sms_listed(i) && !career_sms_unread(i))sms_filed[i>>3]|=(uint8_t)(1<<(i&7));
    sms_box=SMS_BOX_INBOX;sms_sel=0;sms_list_build();   /* the Inbox first (SMSViewerManager::LaunchForMailbox) */
    if(!sms_s || !tip_s){if(!tip_s)fprintf(stderr,"NFSU2_SMS_ERROR reader=msgdlg.n2ui unavailable\n");return;}
    sms_reading=0;sms_fresh=1;menu=MENU_SMS;ui_seen.sms++;
}
/* Select: a single unread message read at once (LaunchForSingleMessage:
 * the reader, Triangle to the mailbox), else the mailbox. */
static void sms_summon(void) {
    sms_open();if(menu!=MENU_SMS || career_sms_new()!=1)return;
    for(int k=0;k<sms_n;k++)if(career_sms_unread(sms_list[k])){sms_sel=k;sms_reading=1;sms_scroll=0;career_sms_read(sms_list[k]);break;}
}
/* Straight into Rachel's first message, read (the PS2's arrival: SMS
 * Instructions). */
static void sms_read_newest(void) {
    sms_open();if(menu!=MENU_SMS || !sms_n)return;
    sms_sel=sms_n-1;sms_reading=1;sms_scroll=0;career_sms_read(sms_list[sms_sel]);
}
/* The same original message package serves tips and the mailbox reader;
 * one owner (tip_s), never two cached copies. Inputs cannot open both. */
/* SMSMessageViewer's CTextScroller: its ten lines are the package's own
 * text objects (0xde075b61..69, then 0x9ef2c7b1), below the subject's gap,
 * in their font, scale and colour; the wrap measured at their scale. */
typedef struct {FeScreen *s;float w,scale;int row[SMS_TEXT_ROWS];} SmsPage;
static float sms_measure(void *ctx,const char *line) {
    SmsPage *p=ctx;return fe_string_width(p->s,0,p->scale,line);
}
static void sms_emit(void *ctx,int row,const char *line) {
    SmsPage *p=ctx;if(row<0 || row>=SMS_TEXT_ROWS)return;
    fe_text(p->s,p->row[row],line);fe_alpha(p->s,p->row[row],1);
}
/* Sponsorship (uiSponsorsMain::RefreshHeader): one sponsor at a time,
 * Left/Right to the next, as the original's IconScrollerMenu: its name in
 * the bar between the arrows, its logo (DECAL_ICON_<NAME>), the contract's
 * terms in the package's ten lines (TERMS_1..10, the SMS reader's
 * CTextScroller, Up/Down), the signing bonus, a URL race's purse and the
 * sponsor race's, its races (SPONSOR_INFO_<NAME>). No Back: a contract
 * stage starts with a sponsor. */
static void sponsor_draw(float dt) {
    FeScreen *s=sponsor_s;int k=sponsor_list[sponsor_sel];const CareerSponsor *sp=career_sponsor(k);if(!s || !sp)return;
    static const uint32_t hide[]={0x47ff4e7cu,0x35e8f0b2u,0x1ba605ecu};   /* debug label; Back and its button */
    for(unsigned i=0;i<sizeof hide/sizeof *hide;i++)fe_alpha(s,fe_find(s,hide[i]),0);
    char b[160];
    fe_text(s,fe_find(s,0xf13f76b4u),sp->name);
    int logo=fe_find(s,0xb04669e3u);const char *icon=career_sponsor_icon(k);
    fe_alpha(s,logo,icon && fe_texture(s,logo,fe_hash(icon))?1.f:0.f);
    snprintf(b,sizeof b,"%d",sp->bonus);fe_text(s,fe_find(s,0xf25b6bbau),b);
    snprintf(b,sizeof b,"%d",career_url_purse(career_state()->stage));fe_text(s,fe_find(s,0x7d8e1791u),b);
    snprintf(b,sizeof b,"%d",sp->purse);fe_text(s,fe_find(s,0x195d8d22u),b);
    const char *races=career_sponsor_races(k);
    if(!races){snprintf(b,sizeof b,"\n%s, %s, %s",mode_name(sp->types[0]),mode_name(sp->types[1]),mode_name(sp->types[2]));races=b;}   /* a career.n2cr before version 13 */
    fe_text(s,fe_find(s,0xf13cef3fu),races);
    {   /* the ends' arrows out; the one towards the move blinks */
        static int last=-1;int l=fe_find(s,ARROW_LEFT),r=fe_find(s,ARROW_RIGHT);
        fe_alpha(s,l,sponsor_sel>0);fe_alpha(s,r,sponsor_sel<sponsor_n-1);
        if(last>=0 && last!=sponsor_sel)fe_play(s,sponsor_sel>last?r:l,FE_SCRIPT_BLINK);
        last=sponsor_sel;
    }
    scroll_handle(s,sponsor_sel,sponsor_n);
    fe_update(s,dt);
    /* the terms: wrapped short of the scroll bar's arrows, in the language's words */
    const char *terms=career_sponsor_terms(k);char old[160];
    if(!terms) {   /* a career.n2cr before version 13: the stage's contract */
        const CareerStage *st=career_stage_info(career_state()->stage);
        snprintf(old,sizeof old,"Win %d URL races, 3 sponsor races, %d races of your choice; %d DVD cover%s.",
                 st?st->url:0,st?st->choice:0,st?st->dvd:0,st && st->dvd==1?"":"s");
        terms=old;
    } else terms=lang_en(terms);
    float x,y,sc,ax,ay,asc;fe_place(s,fe_find(s,0xfcc58ddau),&x,&y,&sc);fe_place(s,fe_find(s,0x3760818eu),&ax,&ay,&asc);
    SmsPage p={s,ax-x-14.f,sc,{0}};
    for(int i=0;i<SMS_TEXT_ROWS;i++){p.row[i]=fe_find(s,i<9?0xfcc58ddau+i:0x9577494au);fe_text(s,p.row[i],"");fe_alpha(s,p.row[i],0);}
    sponsor_lines=sms_text_lines(terms,p.w,0,&p,sms_measure,NULL);
    sponsor_scroll=sms_text_scroll(sponsor_scroll,sponsor_lines,0);
    sms_text_lines(terms,p.w,sponsor_scroll,&p,sms_measure,sms_emit);
    {   /* the terms' scroll bar: its handle down the upright backing */
        int bar=fe_find(s,0x5ba12ce1u),tab=fe_find(s,0xf985dfdeu),last=sponsor_lines>SMS_TEXT_ROWS?sponsor_lines-SMS_TEXT_ROWS:0;
        float bx,by,bw,bh,tx,ty,tw,th;fe_origin(s,bar,&bx,&by);fe_base_size(s,bar,&bw,&bh);fe_origin(s,tab,&tx,&ty);fe_base_size(s,tab,&tw,&th);
        if(bar>=0 && tab>=0 && bh>4*bw && fe_parent(s,bar)==fe_parent(s,tab))fe_moveto(s,tab,tx,by-bh*.5f+th*.5f+(bh-th)*(last?(float)sponsor_scroll/last:0.f));
    }
    fe_draw(s);
}
static void sms_reader_draw(float dt) {
    FeScreen *s=tip_s;const CareerSms *m=career_sms(sms_list[sms_sel]);if(!s || !m)return;
    /* Text is supplied below, but every original image/group keeps its own
     * animation, colour and lifetime. No blanket alpha override of the frame. */
    static const uint32_t hide[]={0x47ff4e7cu,0x980822b3u,0xb02b46b7u,0x00169268u,0x97b71ddeu,0xe202f7c4u};
    for(unsigned k=0;k<sizeof hide/sizeof *hide;k++)fe_alpha(s,fe_find(s,hide[k]),0);
    fe_alpha(s,fe_find(s,0xfeced617u),1);fe_alpha(s,fe_find(s,0x2c167533u),1);
    fe_alpha(s,fe_find(s,0x42adb44cu),1);
    char b[128];lang_format(b,sizeof b,"From: %s",lang_en(career_text(m->sender)));fe_text(s,fe_find(s,0xfeced617u),b);
    lang_format(b,sizeof b,"Subject: %s",lang_en(career_text(m->subject)));fe_text(s,fe_find(s,0x2c167533u),b);
    fe_update(s,dt);
    float x,y,sc;fe_place(s,fe_find(s,0xde075b61u),&x,&y,&sc);
    SmsPage p={s,2.f*(240.f-x)-24.f,sc,{0}};
    for(int k=0;k<SMS_TEXT_ROWS;k++){p.row[k]=fe_find(s,k<9?0xde075b61u+k:0x9ef2c7b1u);fe_text(s,p.row[k],"");fe_alpha(s,p.row[k],0);}
    const char *body=lang_en(career_text(m->body));
    sms_lines=sms_text_lines(body,p.w,0,&p,sms_measure,NULL);
    int last=sms_lines>SMS_TEXT_ROWS?sms_lines-SMS_TEXT_ROWS:0;
    if(sms_scroll>last)sms_scroll=last;
    sms_text_lines(body,p.w,sms_scroll,&p,sms_measure,sms_emit);
    fe_draw(s);
    /* no page counter: the original shows its scroll bar's arrows only */
    fe_string_align(s,0,ux(24),252,.4f,0xffe8e8e8,BTN_TRIANGLE " Go to Mailboxes",0);
    fe_string_align(s,0,ux(456),252,.4f,0xffe8e8e8,BTN_X " Return to Gameplay",2);
}
static void sms_draw(float dt) {
    if(sms_reading && tip_s){sms_reader_draw(dt);return;}
    FeScreen *s=sms_s;char b[160];
    /* SMSMailboxViewer's ten slots: MESSAGE_TEXT_n, their envelopes
     * (ENGAGE_PHONE_ICON_n) and highlights (High_Light_n), top to bottom */
    static const uint32_t text_of[10]={0x0c6e4198u,0x0c6e4199u,0x0c6e419au,0x0c6e419bu,0x0c6e419cu,0x0c6e419du,0x0c6e419eu,0x0c6e419fu,0x0c6e41a0u,0x9a3674c8u},
                          icon_of[10]={0x6bde8997u,0x6bde8998u,0x6bde8999u,0x6bde899au,0x6bde899bu,0x6bde899cu,0x6bde899du,0x6bde899eu,0x6bde899fu,0xe7afbca7u},
                          light_of[10]={0x949f4946u,0x949f4947u,0x949f4948u,0x949f4949u,0x949f494au,0x949f494bu,0x949f494cu,0x949f494du,0x949f494eu,0x28887236u};
    static const uint32_t box_name[5]={0xc06e138au,0xf8cb19a3u,0x06f8e5bfu,0xe2442059u,0xea33e5b6u};   /* GetMailboxCategoryLanguageHash */
    static const char *const box_en[5]={"Inbox","Game Tips","Special Events","Rachel","Unlocks"};
    static FeScreen *ready;static int lit[10],shown[3];
    if(ready!=s || sms_fresh){ready=s;sms_fresh=0;for(int k=0;k<10;k++)lit[k]=-1;for(int k=0;k<3;k++)shown[k]=-1;}   /* (its FADEIN, opening, restarted every object's script) */
    int first=sms_sel>=10?sms_sel-9:0;
    for(int k=0;k<10;k++) {
        int i=first+k,on=!sms_reading && i<sms_n,text=fe_find(s,text_of[k]),icon=fe_find(s,icon_of[k]),light=fe_find(s,light_of[k]);
        fe_alpha(s,text,on);fe_alpha(s,icon,on);fe_alpha(s,light,on);
        if(!on){lit[k]=-1;continue;}
        int m=sms_list[i];const CareerSms *sm=career_sms(m);
        lang_format(b,sizeof b,"Subject: %s",lang_en(career_text(sm->subject)));fe_text(s,text,b);   /* FillSMSSubject */
        uint32_t colour;sms_envelope(career_sms_mail(m)->envelope,&colour);   /* SyncCurrentButton: the category's colour, open once read */
        fe_texture(s,icon,career_sms_unread(m)?0x4b9b8f5au:0xee28ac57u);fe_paint(s,icon,colour);   /* ENGAGE_SMS_MAIL, ENGAGE_SMS_READ_MESSAGE */
        int sel=i==sms_sel;
        if(lit[k]!=sel){uint32_t sc=sel?FE_SCRIPT_HIGHLIGHT:FE_SCRIPT_UNHIGHLIGHT;fe_play(s,text,sc);fe_play(s,light,sc);lit[k]=sel;}
    }
    {   /* the mailbox's name between L1 and R1, the ends' trigger away; Delete and Read with a list (BuildSubjectHeaderList) */
        int k=sms_box-SMS_BOX_INBOX;if(k<0 || k>4)k=0;
        fe_text(s,fe_find(s,0x980822b3u),lang_or(box_name[k],box_en[k]));
        const uint32_t obj[3]={0x54049a3du,0xd506a970u,0x31cf7ec2u};
        int want[3]={sms_box>SMS_BOX_INBOX,sms_box<SMS_BOX_UNLOCKS,sms_n>0};
        for(int j=0;j<3;j++)if(shown[j]!=want[j]){fe_play(s,fe_find(s,obj[j]),fe_hash(want[j]?"Show":"Hide"));shown[j]=want[j];}
        fe_alpha(s,fe_find(s,0x7d8c9ee7u),sms_n>0);   /* Read Message */
        scroll_handle(s,k,5);   /* the mailboxes' bar across the top */
    }
    {   /* the subjects' bar: its tab down the upright backing by the selection, the arrows away at the ends (RefreshHeader) */
        int bar=fe_find(s,0x884fba76u),tab=fe_find(s,0xf31e8ed3u);
        float bx,by,bw,bh,tx,ty,tw,th;fe_origin(s,bar,&bx,&by);fe_base_size(s,bar,&bw,&bh);fe_origin(s,tab,&tx,&ty);fe_base_size(s,tab,&tw,&th);
        if(bar>=0 && tab>=0)fe_moveto(s,tab,tx,by-bh*.5f+th*.5f+(bh-th)*(sms_n>1?(float)sms_sel/(sms_n-1):0.f));
        fe_alpha(s,fe_find(s,0x640f0f22u),sms_n>1 && sms_sel>0);fe_alpha(s,fe_find(s,0x640f0f23u),sms_n>1 && sms_sel<sms_n-1);
    }
    fe_update(s,dt);fe_draw(s);
    if(sms_delete_ask)confirm_box(s,lang_or(0xf0a6e6b5u,"Are you sure you want to delete this message?"),"",lang_or(0xf770u,"Yes"),lang_or(0x61cu,"No"),sms_delete_yes);
}

/* The original screens over the HUD: countdown, pause, results and
 * reward, the world map and the event dialog. dt: real time (the pause
 * stops the game's). */
/* the racer's car, as the results name it */
static const char *racer_car(int who) {
    const Racer *r=&race.r[who];
    return car_short(who==0?fleet_label(player_car):opp_pool[r->model].fleet>=0?fleet_label(opp_pool[r->model].fleet):opp_pool[r->model].label);
}
/* The tournament's screens, as the PS2's: the course's places, times and
 * the points each took (8/6/4/3/2/1), then the standings by the points so far;
 * X on (the next course from the standings), Triangle or O back to the
 * course's. */
static void tourn_draw(float dt) {
    const RaceEvent *e=race_event(race.event);char b[48];
    FeScreen *s=post_stage==4?tourn_std_s:tourn_res_s;if(!s)return;
    static const uint32_t hide[]={0x47ff4e7cu,0x9b8c9d7au,0x1f105857u,0xf6d3c68au};   /* debug label, online timeout and waiting, overtime */
    for(unsigned k=0;k<sizeof hide/sizeof *hide;k++)fe_alpha(s,fe_find(s,hide[k]),0);
    int more=race.tour_at<race.tour_n-1,who[RACERS];
    snprintf(b,sizeof b,"Race %d of %d",race.tour_at+1,race.tour_n);fe_text(s,fe_find(s,0x42adb44cu),b);
    fe_text(s,fe_find(s,0x19de3eu),post_stage==4 && more?"Next Race":"Continue");
    for(int k=0;k<race.nr;k++)who[k]=race.place[k];
    if(post_stage==4)for(int a=0;a<race.nr;a++)for(int c=a+1;c<race.nr;c++)if(race.points[who[c]]>race.points[who[a]] || (race.points[who[c]]==race.points[who[a]] && who[c]==0)){int t=who[a];who[a]=who[c];who[c]=t;}
    for(int k=0;k<6;k++) {
        int name=fe_find(s,0xa5cc56b5u+k),num=fe_find(s,0xda2e9a32u+k),carn=fe_find(s,0xfe58e79eu+k),tim=fe_find(s,0xa3ea9c37u+k),pts=fe_find(s,0xf2028e7eu+k);
        float a=k<race.nr?1.f:0.f;
        fe_alpha(s,name,a);fe_alpha(s,num,a);fe_alpha(s,carn,a);fe_alpha(s,tim,a);fe_alpha(s,pts,a);
        if(k>=race.nr)continue;
        int w=who[k];uint32_t col=w==0?0xff8af4cau:0xffffffffu;
        snprintf(b,sizeof b,"%d",k+1);fe_text(s,num,b);fe_color(s,num,col);
        fe_text(s,name,racer_label(w));fe_color(s,name,col);
        fe_text(s,carn,racer_car(w));fe_color(s,carn,col);
        if(post_stage!=4) {
            const Racer *r=&race.r[w];
            if(r->ko)snprintf(b,sizeof b,"KO");else race_time_text(b,sizeof b,racer_result_time(r,e,race.laps));
            fe_text(s,tim,b);fe_color(s,tim,col);
        }
        snprintf(b,sizeof b,"%d",post_stage==4?race.points[w]:url_points(k+1));fe_text(s,pts,b);fe_color(s,pts,col);
    }
    fe_update(s,dt);fe_draw(s);
}
static void question_idle(void);
static void ui_screens(float dt) {
    question_idle();
    if(dyno_hold && dyno_menu_on){dyno_world_draw(dt);return;}   /* on the dyno's rollers: its screens */
    if(race.state==RACE_DONE && tourn_on() && !tourn_res_s) {   /* a tournament's course over: its screens */
        if((tourn_res_s=fe_load("tournres.n2ui")))fe_show(tourn_res_s,1,1);
        if((tourn_std_s=fe_load("tournstand.n2ui")))fe_show(tourn_std_s,1,1);
        ui_open=NULL;
    }
    char b[32];
    if(race.state==RACE_COUNTDOWN && hud_s && race_intro<=0 && !race.quick) {
        /* the HUD's big font, popping in each second: 3, 2, 1, GO! (the
         * PS2's quick race counts down with no numbers) */
        float c=race.countdown-.5f;int n=(int)ceilf(c);
        float t=n-c,sc=1.6f+1.2f*fmaxf(0,.25f-t)*4;
        snprintf(b,sizeof b,"%s",n>0?(n==3?"3":n==2?"2":"1"):"GO!");
        uint32_t a=(uint32_t)(255*fminf(1,(1-t)*3));
        fe_string(hud_s,fe_font_largest(hud_s),240,110,sc,a<<24|0xe0e0e0,b);
        ui_seen.countdown=1;
    }
    /* screens open with their FADEIN (INIT leaves them hidden); the replay's
     * bar from Post Race and from the pause's Replay, mid-race, alike */
    FeScreen *now=menu==MENU_MAIN && pause_s?pause_s:menu==MENU_MAP?map_s:menu==MENU_IGMAP?igmap_s:menu==MENU_SHOP?shop_s:menu==MENU_STATUS?statusm_s:menu==MENU_OPTS?optsm_s:menu==MENU_AUDIO?opts_s:menu==MENU_ENGAGE?engage_s:menu==MENU_SPONSOR?sponsor_s:menu==MENU_SMS?(sms_reading && tip_s?tip_s:sms_s):menu==MENU_TIP?tip_s:menu==MENU_SHOWGO?showgo.s:
                  replay_on && menu==MENU_OFF?replay_s:results_up() && menu==MENU_OFF?(post_stage==3?postrace_s:post_stage==2?stats_s:post_stage==4?tourn_std_s:post_stage==5?sponsor_pop_s:post_stage?reward_s:tourn_on() && tourn_res_s?tourn_res_s:results_s):NULL;
    if(now!=ui_open) {
        if(now){fe_play_all(now,FE_SCRIPT_FADEIN);carousel_reset(now);}
        /* the replay bar's full-width backing (0xa9723345) is the loading
         * band: the game shows it only while a replay snapshot streams in
         * (ReplayMenu::StartLoading 0x800f8934 "Show", ServiceLoading
         * 0x800f8a34 "Hide") and the package's INIT chains it to HIDE. Left
         * at its base colour it was an opaque band over the car (the PS2's
         * is clear). */
        if(now && now==replay_s){int b=fe_find(now,0xa9723345u);if(b>=0){fe_play(now,b,FE_SCRIPT_INIT);fe_update(now,0);}
            /* the words under Start and Select ("START", "SELECT"): SHOW,
             * as the PS2's ReplayMenu (the GameCube's, without a Select
             * button, hides the second); the PSP has both buttons */
            fe_play(now,fe_find(now,0x7139516du),0x001ca7c0u);fe_play(now,fe_find(now,0x5497b9bfu),0x001ca7c0u);}
        if(now && now==pause_s)ui_seen.pauses++;
        if(now && now==results_s)ui_seen.results++;
        if(now && now==reward_s)ui_seen.rewards++;
        if(now && now==postrace_s)ui_seen.postraces++;
        if(now && now==stats_s)ui_seen.stats++;
        if(now && now==tourn_res_s)ui_seen.tourn_results++;
        if(now && now==tourn_std_s)ui_seen.tourn_standings++;
        if(now && now==sponsor_pop_s)ui_seen.sponsor_pops++;
        ui_open=now;
    }
    if(menu==MENU_MAIN && pause_s) {
        int n;const PauseItem *it=pause_items(&n);const char *icons[8],*titles[8];
        for(int k=0;k<n;k++){icons[k]=it[k].icon;titles[k]=it[k].title;}
        fe_alpha(pause_s,fe_find(pause_s,0x47ff4e7cu),0);   /* debug label */
        if(menu_sel>=n)menu_sel=n-1;
        fe_alpha(pause_s,fe_find(pause_s,ARROW_LEFT),menu_sel>0);fe_alpha(pause_s,fe_find(pause_s,ARROW_RIGHT),menu_sel<n-1);   /* the ends' arrows out */
        ui_dt=dt;carousel(pause_s,&CAROUSEL,icons,titles,n,menu_sel);
        fe_update(pause_s,dt);
        const char *l2,*l1=pause_ask?pause_question(pause_ask-1,&l2):NULL;
        if(l1)confirm_box(pause_s,l1,l2,"OK","Cancel",pause_ok);   /* in the menu's place, as the PS2's */
        else fe_draw(pause_s);
    }
    if(menu==MENU_MAP && map_s)world_map_draw(dt);
    if(menu==MENU_IGMAP && igmap_s)igmap_draw(dt);
    if(menu==MENU_SHOP && shop_s)shop_dialog_draw(dt);
    if(menu==MENU_TIP && tip_s)tip_draw(dt);
    if(menu==MENU_SHOWGO && showgo.s)showgo_draw(dt);
    if(menu==MENU_STATUS && statusm_s)status_draw(dt);
    if((menu==MENU_OPTS && optsm_s) || (menu==MENU_AUDIO && opts_s))opts_draw(dt);
    if(menu==MENU_ENGAGE && engage_s)engage_draw(dt);
    if(menu==MENU_SPONSOR && sponsor_s)sponsor_draw(dt);
    if(menu==MENU_SMS && sms_s)sms_draw(dt);
    if(replay_on && replay_s && menu==MENU_OFF)replay_draw(dt);
    else if(results_up() && menu==MENU_OFF && tourn_on() && tourn_res_s && (post_stage==0 || post_stage==4))tourn_draw(dt);
    else if(results_up() && menu==MENU_OFF && post_stage==5 && sponsor_pop_s) {   /* "CHOOSE A SPONSOR!" */
        fe_alpha(sponsor_pop_s,fe_find(sponsor_pop_s,0x47ff4e7cu),0);fe_alpha(sponsor_pop_s,fe_find(sponsor_pop_s,0x812a09d4u),0);   /* debug label; no Back to the street */
        fe_update(sponsor_pop_s,dt);fe_draw(sponsor_pop_s);
    }
    else if(results_up() && menu==MENU_OFF && results_s) {
        const RaceEvent *e=race_event(race.event);
        if(post_stage==0) {
            /* Event Results, as the PS2's: the racers' names (the player's
             * "No Profile", green), their cars, and Finish Time, turning to
             * Time Behind for 2 s every 6; the ones still racing at the
             * line at their pace; Square Race Stats, X Next */
            static int name[6],num[6],carn[6],tim[6],head;static float shown;static unsigned at,ready_gen;static FeScreen *ready;
            if(ready!=results_s || ready_gen!=debrief_gen) {
                for(int k=0;k<6;k++){name[k]=fe_find(results_s,0xa5cc56b5u+k);num[k]=fe_find(results_s,0xda2e9a32u+k);carn[k]=fe_find(results_s,0xfe58e79eu+k);tim[k]=fe_find(results_s,0xa3ea9c37u+k);}
                fe_alpha(results_s,fe_find(results_s,0x9b8c9d7au),0);   /* online timeout */
                fe_alpha(results_s,fe_find(results_s,0xc18c12fdu),0);   /* disconnected */
                fe_alpha(results_s,fe_find(results_s,0x47ff4e7cu),0);   /* debug label */
                head=fe_find(results_s,0xa4ec03beu);
                ready=results_s;ready_gen=debrief_gen;
            }
            if(at!=race.r[0].finish_frame){at=race.r[0].finish_frame;shown=0;}
            shown+=dt;
            fe_text(results_s,fe_find(results_s,0x62e6b564u),race.mode==RMODE_DRIFT?"":"Race Stats");
            fe_alpha(results_s,fe_find(results_s,0x97b71ddeu),race.mode!=RMODE_DRIFT);
            if(race.mode==RMODE_DRIFT) {   /* the player's score among the field's */
                int sc[RACERS],who[RACERS]={0,1,2,3},n=drift_board(sc);
                for(int a=0;a<n;a++)for(int c=a+1;c<n;c++)if(sc[who[c]]>sc[who[a]]){int t=who[a];who[a]=who[c];who[c]=t;}
                fe_text(results_s,head,"Points");
                for(int k=0;k<6;k++) {
                    float a=k<n?1.f:0.f;
                    fe_alpha(results_s,name[k],a);fe_alpha(results_s,num[k],a);fe_alpha(results_s,carn[k],a);fe_alpha(results_s,tim[k],a);
                    if(k>=n)continue;
                    snprintf(b,sizeof b,"%d",k+1);fe_text(results_s,num[k],b);
                    fe_text(results_s,name[k],racer_label(who[k]));fe_color(results_s,name[k],who[k]?0xffffffffu:0xff8af4cau);
                    fe_text(results_s,carn[k],who[k]?"":car_short(fleet_label(player_car)));
                    points_text(b,sizeof b,sc[who[k]]);fe_text(results_s,tim[k],b);
                }
                fe_update(results_s,dt);fe_draw(results_s);return;
            }
            int url=race.mode==RMODE_URL && race.tour_n>1,behind=fmodf(shown,6.f)>=4.f;
            fe_text(results_s,head,behind?"Time Behind":"Finish Time");
            float lead=racer_result_time(&race.r[race.place[0]],e,race.laps);
            for(int k=0;k<6;k++) {
                float a=k<race.nr?1.f:0.f;
                fe_alpha(results_s,name[k],a);fe_alpha(results_s,num[k],a);fe_alpha(results_s,carn[k],a);fe_alpha(results_s,tim[k],a);
                if(k>=race.nr)continue;
                const Racer *r=&race.r[race.place[k]];int me=race.place[k]==0;
                uint32_t col=me?0xff8af4cau:0xffffffffu;
                snprintf(b,sizeof b,"%d",k+1);fe_text(results_s,num[k],b);fe_color(results_s,num[k],col);
                fe_text(results_s,name[k],racer_label(race.place[k]));fe_color(results_s,name[k],col);
                fe_text(results_s,carn[k],car_short(me?fleet_label(player_car):(opp_pool[r->model].fleet>=0?fleet_label(opp_pool[r->model].fleet):opp_pool[r->model].label)));
                fe_color(results_s,carn[k],col);fe_color(results_s,tim[k],col);
                float t=racer_result_time(r,e,race.laps);
                if(r->ko)snprintf(b,sizeof b,"KO");
                else if(behind && k==0)snprintf(b,sizeof b,"--:--.--");
                else if(behind){float d=t-lead;int n=snprintf(b,sizeof b,"%c",d<0?'-':'+');race_time_text(b+n,sizeof b-n,fabsf(d));}
                else race_time_text(b,sizeof b,t);
                if(url){int n=(int)strlen(b);snprintf(b+n,sizeof b-n,"  %d pts",race.points[race.place[k]]);}
                fe_text(results_s,tim[k],b);
            }
            fe_update(results_s,dt);fe_draw(results_s);
        } else if(post_stage==3 && postrace_s) {
            fe_alpha(postrace_s,fe_find(postrace_s,0x47ff4e7cu),0);   /* debug label */
            int n;const PostItem *it=postrace_items(&n);const char *icons[6],*titles[6];
            for(int k=0;k<n;k++){icons[k]=it[k].icon;titles[k]=it[k].title;}
            if(postrace_sel>=n)postrace_sel=n-1;
            fe_alpha(postrace_s,fe_find(postrace_s,ARROW_LEFT),postrace_sel>0);fe_alpha(postrace_s,fe_find(postrace_s,ARROW_RIGHT),postrace_sel<n-1);   /* the ends' arrows out */
            ui_dt=dt;carousel(postrace_s,&CAROUSEL,icons,titles,n,postrace_sel);
            fe_update(postrace_s,dt);
            const char *l2,*l1=postrace_ask?postrace_question(postrace_ask-1,&l2):NULL;
            if(l1)confirm_box(postrace_s,l1,l2,"OK","Cancel",postrace_ok);   /* in the menu's place, as the PS2's */
            else fe_draw(postrace_s);
        } else if(post_stage==2 && stats_s) {
            /* Post Race Stats (UI_PostRaceStats.fng), as the PS2's: "4
             * No Profile - 206" between the arrows, and the racer's
             * numbers in the right box (its rows written over the frame,
             * the package's own scroll off the screen) */
            static FeScreen *ready;static unsigned ready_gen;
            static const uint32_t ROWS[]={0x44f9b51u,0x9b483b09u,0x9b483b08u,0x9b483b07u,0x9b483b06u,0x9b483b05u,0x9b483b04u,0x9b483b03u,0x9b483b02u,0x9b483b01u,
                0x59980d8u,0xb2980bb0u,0xb2980bafu,0xb2980baeu,0xb2980badu,0xb2980bacu,0xb2980babu,0xb2980baau,0xb2980ba9u,0xb2980ba8u,
                0x9cb7fedu,0x4bfc25u,0x4bfc24u,0x4bfc23u,0x4bfc22u,0x4bfc21u,0x4bfc20u,0x4bfc1fu,0x4bfc1eu,0x4bfc1du,
                0x213e2347u,0xa3ea9c3fu,0xa3ea9c3eu,0xa3ea9c3du,0xa3ea9c3cu,0xa3ea9c3bu,0xa3ea9c3au,0xa3ea9c39u,0xa3ea9c38u,0xa3ea9c37u,
                0x16ee2626u,0x16ee2627u,0xcd0dec7fu};
            if(ready!=stats_s || ready_gen!=debrief_gen) {
                for(unsigned k=0;k<sizeof ROWS/sizeof *ROWS;k++)fe_alpha(stats_s,fe_find(stats_s,ROWS[k]),0);
                for(int k=0;k<2;k++)fe_alpha(stats_s,fe_find_nth(stats_s,0x52bdee1du,k),0);   /* the lap list's highlights (no laps listed) */
                ready=stats_s;ready_gen=debrief_gen;
            }
            const Racer *r=&race.r[race.place[stats_at]];int who=race.place[stats_at];
            snprintf(b,sizeof b,"%d  %s - %s",stats_at+1,racer_label(who),car_short(who?(opp_pool[r->model].fleet>=0?fleet_label(opp_pool[r->model].fleet):opp_pool[r->model].label):fleet_label(player_car)));
            fe_text(stats_s,fe_find(stats_s,0xb4701445u),b);
            fe_update(stats_s,dt);fe_draw(stats_s);
            char v[5][24];const char *label[5]={"FINISH TIME:","TIME BEHIND:","TOP SPEED:","AVERAGE SPEED:","PERFECT SHIFTS:"};
            float t=racer_result_time(r,e,race.laps),lead=racer_result_time(&race.r[race.place[0]],e,race.laps),ran=r->finished?r->ran:r->time;
            race_time_text(v[0],sizeof v[0],t);
            if(r->dnf)snprintf(v[1],sizeof v[1],"%s",r->wrecked?"Totaled":"Blown Engine");else if(stats_at==0)snprintf(v[1],sizeof v[1],"--:--.--");
            else{v[1][0]='+';race_time_text(v[1]+1,sizeof v[1]-1,t-lead);}
            snprintf(v[2],sizeof v[2],"%.1f %s",r->vtop*SPEED_K,SPEED_UNIT_LOW);
            snprintf(v[3],sizeof v[3],"%.1f %s",ran>1.f?racer_total(r,e)/ran*SPEED_K:0.f,SPEED_UNIT_LOW);
            const DragBox *db=who?&r->box:&race.drag;snprintf(v[4],sizeof v[4],"%d/%d",db->perfect,db->shifts);   /* the launch counts, as the PS2's 0/1 */
            int n=race.mode==RMODE_DRAG?5:4;
            for(int k=0;k<n;k++) {
                float y=81.6f+k*20.4f;
                fe_string_align(stats_s,0,215,y,.42f,0xffe1e1e1,label[k],0);
                fe_string_align(stats_s,0,396,y,.42f,0xffe1e1e1,v[k],1);
            }
        } else if(reward_s) {
            static FeScreen *ready;static unsigned ready_gen;static int rep,cash,who;
            if(ready!=reward_s || ready_gen!=debrief_gen){rep=fe_find(reward_s,0x18d97a23u);cash=fe_find(reward_s,0x18d97a24u);who=fe_find(reward_s,0xeb406fecu);fe_alpha(reward_s,fe_find(reward_s,0xcd0dec7fu),0);ready=reward_s;ready_gen=debrief_gen;}
            const CareerReward *rw=&race.reward;
            snprintf(b,sizeof b,"%d",race.rewarded?rw->rep:0);fe_text(reward_s,rep,b);
            snprintf(b,sizeof b,"$%d",race.rewarded?rw->money:0);fe_text(reward_s,cash,b);
            fe_text(reward_s,who,fleet_label(player_car));
            {   /* the contract's news: the sponsor's purse, a cover, the next stage */
                char m[64];int y=200;
                if(race.rewarded && rw->purse){snprintf(m,sizeof m,"Sponsor Race Purse: $%d",rw->purse);fe_string(reward_s,0,240,y,.45f,0xff80ff80,m);y+=16;}
                if(race.rewarded && rw->cover){fe_string(reward_s,0,240,y,.45f,0xff40ffff,rw->cover==2?"Your car made a DVD cover!":"Your car made a magazine cover!");y+=16;}
                if(race.rewarded && rw->stage_up==1){snprintf(m,sizeof m,"Stage %d reached",career_state()->stage);fe_string(reward_s,0,240,y,.5f,0xff40ffff,m);}
                if(race.rewarded && rw->stage_up==2)fe_string(reward_s,0,240,y,.5f,0xff40ffff,"Career complete!");
            }
            fe_update(reward_s,dt);fe_draw(reward_s);
        }
    } else if(race.state!=RACE_DONE)post_stage=0;
}

