enum { MM_CAREER, MM_QUICK, MM_CUSTOM, MM_PROFILES, MM_OPTIONS, MM_N };
static const char *const main_icons[MM_N]={"MAIN_ICON_CAREER","MAIN_ICON_QUICK_RACE","MAIN_ICON_CUSTOMIZE_CAR","MAIN_ICON_PROFILE_MANAG","MAIN_ICON_OPTIONS"};
