static const int cust_gcat[CUST_N]={0,GCAT_VINYL,GCAT_KIT,GCAT_REAR,GCAT_SKIRT,GCAT_HOOD,GCAT_SPOILER,GCAT_RIMS,GCAT_HEADLIGHT,GCAT_BRAKELIGHT,
                                    GCAT_ROOF,GCAT_EXHAUST,0,0,0,0,GCAT_WIDE,GCAT_MIRROR,0,0,0,GCAT_AUDIO,0,0,0,0,GCAT_HOOD};
