static int trunk_slot,trunk_menu_layout;   /* the trunk's slot browsed (Trunk Slot n); the layout's list opened from the trunk's menu */
static int cust_cat,cust_msg_timer;static char cust_msg[160];
static const CarLook *cust_fitted(void) { return mycars_edit?&mycars_fitted:&career_state()->look; }
static const char *cust_model(void) { const FleetCar *f=fleet_car(mycars_edit?mycars_edit_car:career_state()->car);return f?f->model:""; }
/* The body shop's parts listed as the original's (garage_shown: the parts
 * table's order, the first levels first; beta #77): the look's choice at
 * the list's place k (0 the stock part), and the place of choice v. The
 * list shops (the trunk's audio) and the rims and vinyls keep their own. */
static int cust_ordered(int c) { return c<CUST_DECAL && c!=CUST_VINYL && c!=CUST_RIMS && c!=CUST_SPINNER && c!=CUST_AUDIO && (cust_gcat[c] || c==CUST_KIT); }
/* Only the parts on offer listed, as the original's (PartSelectionScreen::
 * BuildPartsList: the parts CarCustomizeManager::IsPartAvailable lets in,
 * the locked ones left out, not shown locked; beta #137): the stock part,
 * then those open (cust_value_open) or fitted, in the shop's order. */
static int cust_shown_list(int c,const uint8_t **out);
static int cust_listed(int c);   /* (the Hoods and Split Hoods: their own lists, cust_value, over the shop's order here) */
static int cust_choice(int c,int k) {
    if(k<=0 || !cust_ordered(c))return k;
    if(cust_listed(c))return 1+garage_shown(cust_model(),cust_gcat[c],k-1);
    const uint8_t *v;int n=cust_shown_list(c,&v);return k-1<n?v[k-1]:0;
}
static int cust_place(int c,int v) {
    if(v<=0 || !cust_ordered(c))return v;
    if(cust_listed(c))return 1+garage_shown_at(cust_model(),cust_gcat[c],v-1);
    const uint8_t *l;int n=cust_shown_list(c,&l);for(int k=0;k<n;k++)if(l[k]==v)return k+1;
    return 0;
}
static int cust_install(const CarLook *look,int cost,const char *path) {
    if(!mycars_edit)return career_buy_look(look,cost,path);
    if(player_car!=mycars_edit_car || player_custom_car!=player_car || player_custom_lod!=1 || memcmp(look,&player_look,sizeof *look))return -1;
    if(!garage_vinyls_rendered(cust_model(),look) || !mycars_install(&mycars_edit_slot,mycars_edit_car,look))return -1;
    mycars_fitted=*look;qr_pick(mycars_edit_car,mycars_edit_slot);return 0;
}
