    case QO_DIFF:snprintf(b,n,"%s",QO_DIFF_NAMES[qr_opt[k]]);break;
    case QO_CATCH:snprintf(b,n,"%s",qr_opt[k]?"On":"Off");break;
    case QO_LAPS:snprintf(b,n,"%d",qr_opt[QO_LAPKO] && qr_opt[QO_OPP]?qr_opt[QO_OPP]:qr_opt[k]);break;   /* Lap KO: a lap per opponent */
