/* "Would you like to install this part now?" / "... this performance
 * package?": the PS2's Yes / No over the dimmed shop, No first. */
/* the in-game dialog over the screen, as the PS2's (UI_InGameDialog: its
 * box, two lines, two buttons; first_on: the left one in focus) */
static void confirm_box_at(FeScreen *s,float y0,float h,const char *l1,const char *l2,const char *a,const char *b,int first_on);
/* The original's two-button question (DialogInterface::ShowTwoButtons,
 * feDialogScreen::BuildFromConfig; beta issue 117): in the game
 * UI_InGameDialog.fng (the pause's and Post Race's Quit, Restart, Return to
 * Explore Mode), in the menus GenericDialog_SMALL / MED / LARGE by the
 * message's length (CalcFEngDialogPackageName: its characters times the
 * body font's height, CONDUITMDITC_TT21I's 32: under 2561 SMALL, under 5122
 * MED). The package dims the screen behind it (its 1070 x 650 backing), the
 * title and its icon stay empty. The third button is the centered choice
 * for ShowOneButton. Captions and focus come from the caller (fe_button_focus: the package's
 * Highlight / UnHighlight). Read when a question opens, one at a time, let
 * go when none is drawn (question_idle); 0 when it is not there (a dist
 * before it, or no room): the caller's own box then. */
enum { Q_INGAME,Q_SMALL,Q_MED,Q_LARGE };
static FeScreen *question_s;static int question_kind=-1,question_absent;static uint64_t question_at;
static void question_idle(void) {   /* once a frame, before the screens: a question not drawn for a while let go */
    if(question_s && sceKernelGetSystemTimeWide()-question_at>250000u){ge_fence();fe_free(question_s);question_s=NULL;question_kind=-1;}
}
static FeScreen *question_load(int kind) {
    static const char *const file[4]={"igdialog.n2ui","gdialogs.n2ui","gdialogm.n2ui","gdialog.n2ui"};
    if(question_s && question_kind==kind)return question_s;
    if(question_absent>>kind&1)return NULL;
    if(question_s){ge_fence();fe_free(question_s);question_s=NULL;question_kind=-1;}
    FeLoadReport r;FeScreen *s=fe_load_checked(file[kind],&r);
    if(!s){if(r.stage==FE_LOAD_OPEN)question_absent|=1<<kind;return NULL;}
    fe_show(s,1,1);
    fe_alpha(s,fe_find(s,0xc26a8d5cu),0);fe_text(s,fe_find(s,0x426c7b4du),"");   /* the title's icon and words: the memory card's alone */
    fe_alpha(s,fe_find(s,0x47ff4e7cu),0);fe_alpha(s,fe_find(s,0xf7206332u),0);   /* the authors' labels */
    question_s=s;question_kind=kind;return s;
}
static int ui_question(int ingame,const char *l1,const char *l2,const char *a,const char *b,int first_on) {
    char m[256];snprintf(m,sizeof m,"%s%s%s",l1,l2 && l2[0]?"\n":"",l2?l2:"");
    float h=(float)strlen(m)*32.f;
    FeScreen *s=question_load(ingame?Q_INGAME:h<2561.f?Q_SMALL:h<5122.f?Q_MED:Q_LARGE);
    if(!s)return 0;
    int center=fe_find(s,0xb8a7c6ceu),center_back=fe_find(s,0xb1000cc8u);
    if(!b && (center<0 || center_back<0))return 0;   /* older packages can omit Button3 */
    int left=fe_find(s,0xb8a7c6ccu),left_back=fe_find(s,0xb1000cc6u);
    int right=fe_find(s,0xb8a7c6cdu),right_back=fe_find(s,0xb1000cc7u);
    uint64_t now=sceKernelGetSystemTimeWide();
    if(now-question_at>250000u)fe_play_all(s,FE_SCRIPT_FADEIN);   /* a new question: its way in */
    question_at=now;
    fe_text(s,fe_find(s,0x1e2640fau),m);
    fe_alpha(s,left,b!=NULL);fe_alpha(s,left_back,b!=NULL);
    fe_alpha(s,right,b!=NULL);fe_alpha(s,right_back,b!=NULL);
    fe_alpha(s,center,b==NULL);fe_alpha(s,center_back,b==NULL);
    if(b) {
        fe_text(s,left,a);fe_text(s,right,b);
        fe_button_focus(s,left,left_back,first_on);
        fe_button_focus(s,right,right_back,!first_on);
    } else {
        fe_text(s,center,a);
        fe_button_focus(s,center,center_back,1);
    }
    fe_update(s,ui_dt);fe_draw(s);
    return 1;
}
static void confirm_box(FeScreen *s,const char *l1,const char *l2,const char *a,const char *b,int first_on) { if(!ui_question(1,l1,l2,a,b,first_on))confirm_box_at(s,168,64,l1,l2,a,b,first_on); }
