    snprintf(b,sizeof b,"$%d",open && !fitted?price:0);fe_text(s,fe_find(s,0x2f5e7da3u),b);
    fe_alpha(s,fe_find(s,0xa936c3a2u),open);fe_alpha(s,fe_find(s,0x89782734u),open);   /* X Install */
