        if(title_swallow)break;   /* the movie's skip still held */
        if(title_allow && (pressed&(PSP_CTRL_START|PSP_CTRL_CROSS))){menu_sound(PSP_CTRL_CROSS);front_open(FRONT_MAIN);}
        else if(pressed)title_keys++;
