        if(take)switch(*sel){
            case MM_CAREER:   /* Career's own menu (MMCareer: UI_StartCareer) */
                mycars_edit=0;qr_own_domain=0;saved=0;front_sel[FRONT_STARTCAREER]=0;
                if(smoke_scripted){speech_career_context(1);front_open(FRONT_CRIB);break;}   /* the smoke scripts from before it: to the garage, as its Resume did */
                front_open(FRONT_STARTCAREER);break;
            case MM_QUICK:speech_career_context(0);qr_own_domain=0;front_open(FRONT_QRMODE);break;
            case MM_CUSTOM:speech_career_context(0);mycars_edit=0;mycars_tab=QRF_ALL;front_sel[FRONT_MYCARS]=0;front_open(FRONT_MYCARS);break;
            case MM_PROFILES:saved=0;front_sel[FRONT_PROFILES]=0;front_open(FRONT_PROFILES);break;   /* MMSaveLoad: UI_ProfileManager */
            default:saved=0;front_open(FRONT_OPTIONS);}
        break;
    case FRONT_STARTCAREER: {
        int it[3],n=sc_items(it);
        if(back)front_open(FRONT_MAIN);
        else if(take && *sel<n)switch(it[*sel]) {
            case SC_RESUME:   /* StartCareerHelper: a career begun to the garage, else its start (a profile with none yet: its "Start New Career") */
                speech_career_context(1);
                if(career_crib_first())front_open(FRONT_CRIB);else career_enter();
                break;
            case SC_NEW:new_career_ask(-1);break;
            default:profile_load_pick(1);
        }
        break;
    }
    case FRONT_PROFILES:
        if(back)front_open(FRONT_MAIN);
        else if(take)switch(*sel) {
            case PM_CREATE:new_career_ask(FRONT_PROFILES);break;
            case PM_LOAD:profile_load_pick(0);break;
            case PM_SAVE:profile_save_pick();break;
            default:profile_delete_pick();
        }
        break;
    case FRONT_MYCARS: {
        int cars[QR_CARS_MAX],nc=custom_cars(cars);   /* (All Cars: the stock and My Cars) */
        if(back)front_open(FRONT_MAIN);
        else if(take && nc) {
            if(mycars_load()<0){cust_say("My Cars save could not be read");break;}
            if(cc_slot_at(*sel)<0 && mycars_count()>=MYCARS_MAX){cust_say("My Cars is full");break;}
            mycars_edit_car=cars[*sel];mycars_edit_slot=cc_slot_at(*sel);
            if(mycars_edit_slot>=0){mycars_fitted=*mycars_look(mycars_edit_slot);mycars_fitted_perf=*mycars_perf(mycars_edit_slot);}
            else{garage_stock_look(&mycars_fitted);perf_stock(&mycars_fitted_perf);mycars_fitted.paint=(uint8_t)fleet_stock_paint(mycars_edit_car);}
            qr_pick(mycars_edit_car,mycars_edit_slot);
            mycars_edit=1;shop_menu=shop_root=SHOPM_CAR;front_sel[FRONT_CUSTOM]=0;front_open(FRONT_CUSTOM);
        }
        break;
    }
    case FRONT_QRMODE:
        if(back)front_open(FRONT_MAIN);
        else if(take && *sel<QR_OPEN){qr_mode=*sel;qropts_defaults();front_sel[FRONT_QRTRACK]=0;front_open(FRONT_QRTRACK);}
        break;
    case FRONT_QRTRACK:
        if(back)front_open(FRONT_QRMODE);else if(take && qr_tracks(NULL))front_open(FRONT_QROPTS);
        break;
    case FRONT_QRCAR:
        qr_pick_cursor();
        if(back)front_open(FRONT_QROPTS);
        else if(take && !qr_cars(NULL))break;
        else if(take && qr_rmode[qr_mode]==RMODE_DRAG)qr_go();   /* the drag's gearbox is its own: no question, as the PS2's */
        else if(take){qr_dialog=1;qr_manual=opt_val[OP_TRANS]==1;}   /* Transmission: Manual or Auto, on Options > Player's */
        break;
    case FRONT_OPTIONS:
        if(back)front_open(FRONT_MAIN);
        else if(take)switch(*sel){
            case OPT_AUDIO:case OPT_VIDEO:case OPT_GAMEPLAY:case OPT_PLAYER:opt_page=*sel;opt_row=0;front_open(FRONT_AUDIO);break;
            case OPT_TRAX:if(!jb.loaded)jukebox_load();for(int i=0;i<4;i++)trax_row_state[i]=-1;trax_grab=0;front_open(FRONT_TRAX);break;
            case OPT_CREDITS:credits_t=0;front_open(FRONT_CREDITS);break;
            case OPT_CONTROLS:front_open(FRONT_CONTROLS);break;
            case OPT_DEBUG:opt_page=PAGE_DEBUG;opt_row=0;front_open(FRONT_AUDIO);break;
            default:saved=career_save_from_menu();}
        break;
    case FRONT_CRIB:
        if(back)front_open(FRONT_MAIN);
        else if(take)switch(*sel) {
            case CRIB_RESUME:profile_label();if(profile_prompt && !profile_name[0]){prof_named_to=-2;prof_stage=PROF_ASK;prof_yes=0;}else career_enter();break;   /* no profile yet: the PS2's question first (the career needs one) */
            case CRIB_CARSEL:lot_select=1;front_open(FRONT_CARLOT);break;
            case CRIB_TUNE:
                if(fleet_car(career_state()->car)){dyno_enter_from=3;dyno_ask=DQ_ENTER;dyno_yes=0;}   /* UI_CRIB_TEST_TRACK's question first (beta issue 144) */
                else cust_say("Rachel's car is not yours: get one at the car lot");
                break;
            case CRIB_SAVE:saved=career_save_from_menu();break;
            default:front_open(FRONT_MAIN);
        }
        break;
    case FRONT_PERFCAT:
        if(back && perf_from_shop){shop_back_to(ITEM_PERF);front_open(FRONT_CUSTOM);}
        else if(back)SHOP_BACK(FRONT_PERFCAT);
        else if(take){int list[PERF_N],np=perf_categories(list);if(!mycars_edit && *sel==np){dyno_enter_from=perf_from_shop;dyno_ask=DQ_ENTER;dyno_yes=0;}else if(*sel<np){perf_cat=list[*sel];front_open(FRONT_PERFPKG);}}
        break;
    case FRONT_PERFPKG:{
        int lv[12],ix[12],np=perf_list(perf_cat,lv,ix),have=perf_fitted()->level[perf_cat];
        if(perf_row>=np)perf_row=0;
        perf_try=*perf_fitted();   /* on trial (the bars): the part or the package */
        if(*sel>0)perf_try_package(&perf_try,perf_cat,mycars_edit && *sel==4?0:*sel);else if(np)perf_fit_part(&perf_try,perf_cat,lv[perf_row],ix[perf_row]);
        if(back){front_open(FRONT_PERFCAT);front_sel[FRONT_PERFCAT]=perf_shop_slot(perf_cat);}
        else if(take) {
            if(*sel==0) {
                if(!np)break;
                if(!perf_open(lv[perf_row]))cust_say(perf_lock_why(lv[perf_row]));
                else if(perf_part_fitted(perf_fitted(),perf_cat,lv[perf_row],ix[perf_row]))cust_say("Already installed");
                else{perf_ask=1;perf_yes=0;}
            }
            else if(!perf_open(*sel))cust_say(perf_lock_why(*sel));
            else if(mycars_edit?!memcmp(&perf_try,perf_fitted(),sizeof perf_try):*sel<=have)cust_say("Already installed");
            else{perf_ask=2;perf_yes=0;}
        }
        break;
    }
    case FRONT_DYNO:dyno_pages_input(pressed,take,back);break;
    case FRONT_CUSTOM:{
        if(shop_menu==SHOPM_SPECIAL)fe_say(0x12);   /* Rachel at the Car Specialties Shop (UI_ICEMAIN's line) */
        const ShopMenu *m=&shop_menus[shop_menu];int item=shop_item(shop_menu,*sel);
        if(back && (shop_menu==shop_root || m->up<0)){if(mycars_edit){if(mycars_edit_slot>=0){mycars_tab=QRF_MYCARS;front_sel[FRONT_MYCARS]=mycars_edit_slot;}mycars_edit=0;front_open(FRONT_MYCARS);}else SHOP_BACK(FRONT_CUSTOM);}
        else if(back) {   /* up a menu, on the item that opened this one */
            int from=shop_menu,n=shop_items(m->up,NULL);shop_menu=m->up;*sel=0;
            for(int k=0;k<n;k++){int it=shop_item(shop_menu,k);if(it>=SHOP_SUB && shop_sub_menu[it-SHOP_SUB]==from)*sel=k;}
            carousel_reset(front_s[FRONT_CUSTOM]);
        }
        else if(take && shop_item_locked(item))cust_say("Locked");   /* the padlock's, as the PS2's */
        else if(take && item_part(item) && part_paint_refusal(item-ITEM_PART_SPOILER)){cust_say(part_paint_refusal(item-ITEM_PART_SPOILER));cust_msg_timer=300;}
        else if(take && item_part(item)){paint_part=item-ITEM_PART_SPOILER;cust_cat=CUST_PAINT;paint_vin=0;front_open(FRONT_PAINT);}   /* a part's paint */
        else if(take && item==CUST_AUDIO && shop_menu==SHOPM_SPECIAL && cust_fitted()->audio && garage_trunk_choices(0)){shop_menu=SHOPM_TRUNK;*sel=0;carousel_reset(front_s[FRONT_CUSTOM]);}   /* a layout installed: its menu (IceCategoryTrunkThing::React) */
        else if(take && item>=ITEM_TRUNK_SLOT && item<ITEM_TRUNK_END){trunk_slot=item-ITEM_TRUNK_SLOT;cust_cat=CUST_TRUNK_COMP;front_open(FRONT_PARTS);}
        else if(take && item==CUST_NEON_TRUNK && cust_fitted()->audio<3 && !parts_unlocked){cust_say("You must upgrade your trunk to CUSTOM LAYOUT\nin order to install trunk neon.");cust_msg_timer=300;}   /* CustomizeNeonMenu's (0xa9e966d7; the tests' every part open, script 55, past it) */
        else if(take && item==CUST_NEON_ENGINE && !engine_level3() && !parts_unlocked){cust_say("You need to install all level 3 engine, ECU and\nturbo upgrades to access engine neon.");cust_msg_timer=300;}   /* (0xd649be08) */
        else if(take && item>=SHOP_SUB) {
            int sub=shop_sub_menu[item-SHOP_SUB];
            if(sub>=0){shop_menu=sub;*sel=0;carousel_reset(front_s[FRONT_CUSTOM]);}
            else if(item==ITEM_PERF){
                const FleetCar *fc=fleet_car(perf_car());float tq[9],rpm[9],v[6];
                if(mycars_edit && (!fc || perf_dyno(fc->model,perf_fitted(),tq,rpm,NULL)<=0 || !perf_gears(fc->model,0,v)))cust_say("Performance data unavailable");
                else{perf_from_shop=1;front_open(FRONT_PERFCAT);}
            }
            else{dyno_enter_from=2;dyno_ask=DQ_ENTER;dyno_yes=0;}
        }
        else if(take && item==CUST_PAINT){cust_cat=CUST_PAINT;paint_vin=0;paint_part=-1;front_open(FRONT_PAINT);}   /* the paint shop's grid, as the PS2's */
        else if(take && item==CUST_VINYL){cust_cat=CUST_VINYL;front_open(FRONT_VLAYER);}   /* Choose Vinyl Layer first */
        else if(take){trunk_menu_layout=item==CUST_AUDIO && shop_menu==SHOPM_TRUNK;cust_cat=item;front_open(FRONT_PARTS);}
        break;
    }
    case FRONT_PAINT:break;   /* paint_input, above */
