/* viewer-stats.json: made in memory, then written. A smoke's periodic copy
 * (every 300 frames, kept for runs cut short) goes out on a thread under
 * the game's: through a PSP's host0 the write took the game 18-30 ms, a
 * dropped frame each time; the last one is written at once. */
FILE *fmemopen(void *,size_t,const char *);   /* newlib's, hidden by -std=c99 */
/* 0 (poked at load: tools/ppsspp_calib.py): no stats every 300 frames,
 * as on the PSP (its hold flag); the calibrated runs' cadence is the PSP's. */
int tele_periodic=1;   /* (poked) */
enum { TELE_LOG_OUT=64 };static int tele_lean;   /* telemetry: this snapshot the lean one (it did not fit whole): the logs 16 entries, the files' table 8, the hits the last 32 */
static char tele_buf[32768],tele_copy[32768];   /* bounded stats JSON; formatting failure is reported without publishing a partial snapshot. 24 KB: a 40 000-frame city race passed it at ~10 000 frames even lean (bayview-summit, 2026-11-04), the smoke read a stale snapshot short of the flag */static long tele_n;static volatile int tele_busy,tele_quit;static SceUID tele_sema=-1,tele_tid=-1;static int tele_async;
/* Failure-only diagnostic, rate limited; keep both existing buffers unchanged. */
static _Atomic uint32_t tele_error_frame=UINT32_MAX;
static void tele_error(const char *stage,unsigned frame,TelemetryResult r) {
    if(telemetry_error_due(frame,&tele_error_frame))telemetry_report(stderr,stage,frame,r,sizeof tele_buf);
}
static void tele_write_snapshot(const char *buf,long n) {
    TelemetryResult r=telemetry_write(out_stats,buf,(size_t)n);
    if(r.error){unsigned frame=0;sscanf(buf,"{\"frames\":%10u",&frame);tele_error("write",frame,r);}
}
static int tele_thread(SceSize a,void *p) {
    (void)a;(void)p;
    for(;;) {
        sceKernelWaitSema(tele_sema,1,NULL);
        if(tele_quit)break;
        tele_write_snapshot(tele_copy,tele_n);
        tele_busy=0;
    }
    return 0;
}
static void tele_out(long n) {
    if(tele_async && tele_sema<0) {
        tele_sema=sceKernelCreateSema("tele",0,0,1,NULL);
        SceUID t=tele_sema>=0?sceKernelCreateThread("Telemetry",tele_thread,0x30,0x2000,PSP_THREAD_ATTR_USER,NULL):-1;
        if(t<0 || sceKernelStartThread(t,0,NULL)<0)tele_async=0;else tele_tid=t;
    }
    if(tele_async && tele_sema>=0) {
        if(!tele_busy){memcpy(tele_copy,tele_buf,(size_t)n);tele_n=n;tele_busy=1;sceKernelSignalSema(tele_sema,1);}   /* still writing the last: this one skipped */
        return;
    }
    while(tele_busy)sceKernelDelayThread(1000);   /* the last copy out first: this one after it */
    if(marks_f)fflush(marks_f);   /* (test_mark: from the card, with the stats) */
    tele_write_snapshot(tele_buf,n);
}
/* The game's own threads ended before it exits: under PSPLink a thread still
 * running as the module goes (the flip's, above everything, on the display)
 * took PSPLink down to the XMB with it. Each is asked to stop and waited for
 * (a second at most), then ended. */
static int thread_end(SceUID *t) {
    if(*t<0)return -1;
    unsigned us=1000000;
    int joined=sceKernelWaitThreadEnd(*t,(void *)&us);
    if(joined<0)sceKernelTerminateThread(*t);
    sceKernelDeleteThread(*t);*t=-1;
    return joined;   /* fallback/delete is not a successful normal join */
}
/* Preserve the flip stop/join-result sequence without growing its pinned caller. */
static void __attribute__((noinline,noclone)) presentation_flip_stop(void) {
    flip_quit=1;flip_join_result=thread_end(&flip_tid);
}
static void threads_stop(void) {
    presentation_flip_stop();
    if(tele_tid>=0){tele_quit=1;sceKernelSignalSema(tele_sema,1);thread_end(&tele_tid);}
    probe_stop();
}
/* The rescue channel's exit (probe.c): the main loop ends as on HOME; a
 * game stuck elsewhere has its display threads stopped from the channel. */
static void exit_request(void) { quit_now(); }
static void exit_stuck(void) {
    presentation_flip_stop();
    if(tele_tid>=0){tele_quit=1;sceKernelSignalSema(tele_sema,1);thread_end(&tele_tid);}
}
/* A boot that cannot go on (no car pack): out with the threads ended. */
static void exit_early(void) { threads_stop();sceKernelExitGame(); }
/* Once after existing capture drains GE/flips, writer join, audio stop, and world ACK.
 * This is a separate POST-JOIN artifact; original terminal JSON stays PRE-JOIN.
 * No thread is reopened and no extra drain changes the measured window. */
static int presentation_write(unsigned frames,int world_ack,int world_closed,
        uint64_t pause_begin,uint64_t pause_end) {
    char name[80];snprintf(name,sizeof name,"%s.presentation.json",out_stats);
    int cpu=scePowerGetCpuClockFrequencyInt(),bus=scePowerGetBusClockFrequencyInt();
    int valid=flip_join_result==0 && !ge_pending && !q_state && flip_next<0 &&
        !drive_finished_frame && !presentation.rejected && !presentation.unsupported && presentation.frames>0 &&
        presentation.frames==presentation.submitted;
    FILE *f=fopen(name,"w");if(!f)return -1;
    uint64_t export_begin=sceKernelGetSystemTimeWide();
    fprintf(f,"{\"schema\":3,\"measurement_contract\":\"drive-actual-swap-ack-v3\",\"unsupported_basis\":\"actual DRIVE swap fallback, not SUBMIT configuration\",\"tag_lifetime\":\"one pending DRIVE list, consumed by actual swap\",\"phase\":\"post_join_post_world_pause_before_test_held\",\"presentation_valid\":%d,\"flip_join_result\":%d,",valid,flip_join_result);
    fprintf(f,"\"scope\":\"DRIVE rendered lists, triple-buffer runahead; includes paused/intro/HUD\",\"frames_total\":%u,\"build_id\":\"%s\",\"version\":\"%s\",",frames,build_id,game_version);
    fprintf(f,"\"clock_snapshot\":{\"phase\":\"post_join_post_world_pause\",\"valid\":%d,\"cpu_mhz_getter\":%d,\"bus_mhz_getter\":%d,\"pll_mhz_getter\":null},",cpu>0 && bus>0,cpu,bus);
    fprintf(f,"\"config_terminal\":{\"fb_street\":%d,\"street_runahead\":%d,\"street_vblanks\":%d},",fb_street,street_runahead,street_vblanks);
    /* Never read writer-owned counters if its normal WaitThreadEnd failed. */
    if(flip_join_result==0) {
        fprintf(f,"\"ack\":{\"submitted_drive_frames\":%u,\"frames\":%u,\"intervals\":%u,\"epochs\":%u,\"vblank_sum\":%u,\"first_frame\":%u,\"last_frame\":%u,\"rejected\":%u,\"unsupported_drive_frames\":%u,\"interval_hist_le1_2_3_ge4\":[%u,%u,%u,%u]},",presentation.submitted,presentation.frames,presentation.intervals,presentation.epochs,presentation.vblanks,presentation.first,presentation.last,presentation.rejected,presentation.unsupported,presentation.hist[0],presentation.hist[1],presentation.hist[2],presentation.hist[3]);
        fprintf(f,"\"legacy_flip_hist_le1_2_3_ge4\":[%u,%u,%u,%u]",flip_hist[0],flip_hist[1],flip_hist[2],flip_hist[3]);
    } else fputs("\"ack\":null,\"legacy_flip_hist_le1_2_3_ge4\":null",f);
    fprintf(f,",\"world_pause\":{\"api\":\"world_critical_begin\",\"timeout_ms\":10000,\"result\":%d,\"admission_closed_after\":%d,\"ownership_granted\":%d,\"pause_begin_us\":%llu,\"pause_end_us\":%llu,\"export_begin_us\":%llu,\"held_state\":\"%s\"},\"stream_retry_diag\":",world_ack,world_closed,world_ack==1 && world_closed,(unsigned long long)pause_begin,(unsigned long long)pause_end,(unsigned long long)export_begin,world_ack==1 && world_closed?"paused_closed":"refused_safe");
    /* Timeout grants no ring read, even if its ACK arrives later. The helper
     * independently verifies ACK/!busy or stopped before serializing. */
    int written=0;
    if(world_ack==1 && world_closed)written=world_split_diag_write(f);
    if(written==0)fputs("null",f);
    if(written<0){fclose(f);return -1;}   /* partial JSON: never append null */
    fprintf(f,",\"world_diag_write_result\":%d,\"export_world_status\":\"%s\",\"export_end_us\":%llu",written,written==1?"OWNERSHIP_ASSESSED":"UNASSESSED",(unsigned long long)sceKernelGetSystemTimeWide());
    fputs(",\"limitations\":[\"vcount transition uses NEXTFRAME contract; no physical scanout proof\",\"legacy histogram includes boot and cross-menu gaps or predicted fallback flips\",\"terminal clocks do not prove clocks throughout run\",\"world pause and terminal serialization are outside the measured frame window\",\"post-stop/post-ACK memory is not pre-stop headroom\",\"observer CPU/stack/BSS cost unmeasured; source-only proposal\"]}\n",f);
    int io_failed=ferror(f);
    int closed=fclose(f);
    return io_failed || closed!=0?-1:written;
}
/* Pause the world once at terminal, after the measured window, capture
 * drain, auxiliary joins and audio shutdown. Keep
 * admission closed on success or timeout; no resume, destroy, or retry. */
#if WORLD_COOP_RESUME_DIAG || WORLD_DISPATCH_DIAG
static int dispatch_diag_export(int terminal_ack);
#endif
static void presentation_terminal_hold(unsigned frames) {
    uint64_t begin=sceKernelGetSystemTimeWide();
    int ack=world_critical_begin(10000);
    uint64_t end=sceKernelGetSystemTimeWide();
    int result=presentation_write(frames,ack,world_critical_closed(),begin,end);
#if WORLD_COOP_RESUME_DIAG || WORLD_DISPATCH_DIAG
    /* Reuse this pause's explicit result; retain the world and displayed
     * frame. No second ACK, drain, join, resume or free for the diagnostic. */
    if(on_card && ack==1 && world_critical_closed() && flip_join_result==0 &&
       !ge_pending && !q_state && flip_next<0) {
        int dispatch_result=dispatch_diag_export(ack);
        if(dispatch_result!=1)printf("loader-dispatch held export failed %d\n",dispatch_result);
    }
#endif
    /* Publish only after the writer has returned from ferror/fclose, or its
     * explicit fopen/partial-FILE failure. test_held is set by the caller. */
    terminal_world_ack_result=ack;
    terminal_diag_export_result=result;
    /* Finalization result is distinct from valid JSON/ownership. I/O errors
     * (including fclose) invalidate the artifact; held remains safe. */
    printf("terminal_diag_export result=%d world_ack=%d phase=post_world_pause\n",result,ack);
    __asm__ volatile("" ::: "memory");   /* status before caller publishes held */
}
