        fb_triple=0;ge_draw_ready();sceGuStart(GU_DIRECT,loading_list);sceGuClearColor(0xff000000);sceGuClearDepth(0);sceGuClear(GU_COLOR_BUFFER_BIT|GU_DEPTH_BUFFER_BIT);loading_ground();
