    loading_on=0;
    unsigned timeout=2000000;sceKernelWaitThreadEnd(loading_tid,&timeout);sceKernelDeleteThread(loading_tid);loading_tid=-1;
    ge_fence();ge_flip_wait();sceGuSync(0,0);
