/* Script 108's watch: a frame that does not end in 20 s (the main loop
 * stuck in a call) writes hang.txt once, with the last admission stage
 * and the race's state; career_soak.py's watch kills the emulator after.
 * (PPSSPP only: the thread is never stopped.) */
#ifndef HOST_SIM   /* (the simulator has no threads of the PSP's) */
static SceUID career_long_main;   /* the main thread (its state in hang.txt) */
static int career_long_watch(SceSize args,void *argp) {
    unsigned last=0;int same=0;(void)args;(void)argp;
    for(;;) {
        sceKernelDelayThread(5000000);
        if(frames_seen!=last){last=frames_seen;same=0;continue;}
        if(++same!=4)continue;
        FILE *f=fopen("hang.txt","w");if(!f)continue;
        fprintf(f,"frame %u admission %s race state %d event %d intro %.2f menu %d world_level %d loading_on %d\n",
            last,last_mark?(const char *)last_mark:"-",race.state,race.state!=RACE_OFF?race_event(race.event)->id:-1,race_intro,menu,world_level,loading_on);
        SceKernelThreadInfo ti;memset(&ti,0,sizeof ti);ti.size=sizeof ti;
        if(sceKernelReferThreadStatus(career_long_main,&ti)>=0)fprintf(f,"main: status %d wait type %d wait id %d current priority %d\n",ti.status,ti.waitType,(int)ti.waitId,ti.currentPriority);
        fclose(f);career_long_line("HUNG: hang.txt");
    }
    return 0;
}
#endif
static void career_long_after(void) {
    if(cl.ev<0)return;
    const CareerEvent *e=career_event(cl.ev);int place=career_state()->best[cl.ev];char m[96];
    if(e->type<6)cl.type_n[e->type]++;
    cl.races++;
    int won=race.reward.place==1;if(!won && cl.lost[cl.ev]<255)cl.lost[cl.ev]++;
    {FILE *f=fopen("career-lost.bin","wb");if(f){fwrite(cl.lost,1,sizeof cl.lost,f);fclose(f);}}
    snprintf(m,sizeof m,"race %d type %d place %d best %d%s",e->id,e->type,race.reward.place,place,race.reward.stage_up?" stage up":"");
    career_long_line(m);
    cl.ev=-1;
}
